CREATE OR REPLACE FUNCTION public.accept_sicoob_invitation(p_token text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_actor_email text;
  v_email_confirmed_at timestamptz;
  v_invitation public.sicoob_invitations%ROWTYPE;
  v_profile public.profiles%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL OR p_token IS NULL OR p_token !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Convite ou sessão inválidos.';
  END IF;
  SELECT lower(email), email_confirmed_at
    INTO v_actor_email, v_email_confirmed_at
    FROM auth.users
   WHERE id = v_actor_id;
  IF v_actor_email IS NULL OR v_email_confirmed_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Confirme o email da conta antes de aceitar o convite.';
  END IF;

  SELECT * INTO v_invitation
    FROM public.sicoob_invitations i
   WHERE i.token_hash = extensions.digest(p_token, 'sha256')
   FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Convite não encontrado.';
  END IF;
  IF v_invitation.status = 'accepted' AND v_invitation.accepted_by = v_actor_id THEN
    RETURN v_invitation.id;
  END IF;
  IF v_invitation.status <> 'pending' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O convite foi revogado, substituído ou já utilizado.';
  END IF;
  IF v_invitation.expires_at <= now() THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O convite expirou.';
  END IF;
  IF v_actor_email IS DISTINCT FROM v_invitation.email THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Entre com a conta correspondente ao email convidado.';
  END IF;
  IF NOT public.sicoob_inviter_can_issue(
    v_invitation.invited_by, v_invitation.cooperative_id, v_invitation.role
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'A autoridade do emissor não está mais vigente.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.cooperativas c
     WHERE c.id = v_invitation.cooperative_id AND c.is_active IS TRUE
  ) OR (
    v_invitation.pa_id IS NOT NULL
    AND NOT EXISTS (
      SELECT 1 FROM public.postos_atendimento pa
       WHERE pa.id = v_invitation.pa_id
         AND pa.cooperativa_id = v_invitation.cooperative_id
         AND pa.is_active IS TRUE
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A cooperativa ou o PA do convite não está mais ativo.';
  END IF;

  SELECT * INTO v_profile
    FROM public.profiles p
   WHERE p.user_id = v_actor_id
   FOR UPDATE;
  IF FOUND AND (
    (v_profile.cooperativa_id IS NOT NULL AND v_profile.cooperativa_id IS DISTINCT FROM v_invitation.cooperative_id)
    OR (v_profile.pa_id IS NOT NULL AND v_profile.pa_id IS DISTINCT FROM v_invitation.pa_id)
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A conta já possui vínculo ativo em outro escopo.';
  END IF;

  -- O cadastro fechado cria um papel vendedor provisório. Se ele for o único
  -- papel e a conta ainda não possuir escopo institucional, o aceite o troca
  -- pelo papel aprovado, evitando acumular privilégios por efeito do bootstrap.
  IF FOUND
     AND v_profile.cooperativa_id IS NULL
     AND v_profile.pa_id IS NULL
     AND (SELECT count(*) FROM public.user_roles ur WHERE ur.user_id = v_actor_id) = 1
     AND EXISTS (
       SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id = v_actor_id AND ur.role = 'vendedor'::public.app_role
     ) THEN
    DELETE FROM public.user_roles
     WHERE user_id = v_actor_id AND role = 'vendedor'::public.app_role;
  END IF;

  INSERT INTO public.profiles (
    id, user_id, email, is_active, cooperativa_id, singular_id, pa_id, deleted_at
  ) VALUES (
    v_actor_id, v_actor_id, v_actor_email, true,
    v_invitation.cooperative_id, v_invitation.cooperative_id, v_invitation.pa_id, NULL
  )
  ON CONFLICT (user_id) DO UPDATE
    SET is_active = true,
        deleted_at = NULL,
        cooperativa_id = EXCLUDED.cooperativa_id,
        singular_id = EXCLUDED.singular_id,
        pa_id = EXCLUDED.pa_id,
        updated_at = now();

  INSERT INTO public.user_roles (user_id, role)
  VALUES (v_actor_id, v_invitation.role)
  ON CONFLICT (user_id, role) DO NOTHING;

  UPDATE public.sicoob_invitations
     SET status = 'accepted', accepted_by = v_actor_id, accepted_at = now(), updated_at = now()
   WHERE id = v_invitation.id;
  INSERT INTO public.sicoob_invitation_events (
    invitation_id, cooperative_id, action, actor_id, target_user_id,
    details
  ) VALUES (
    v_invitation.id, v_invitation.cooperative_id, 'accepted', v_actor_id, v_actor_id,
    jsonb_build_object('role', v_invitation.role::text, 'pa_id', v_invitation.pa_id)
  );
  RETURN v_invitation.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.acquire_ai_quota(_user_id uuid, _function_name text, _model text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _role app_role;
  _monthly_limit integer;
  _is_unlimited boolean;
  _used integer;
  _log_id uuid;
BEGIN
  -- Get user role
  SELECT role INTO _role FROM public.user_roles WHERE user_id = _user_id LIMIT 1;
  IF _role IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'log_id', null, 'reason', 'no_role');
  END IF;

  -- Get quota for role (with row lock to prevent concurrent reads)
  SELECT monthly_limit, is_unlimited INTO _monthly_limit, _is_unlimited
  FROM public.ai_usage_quotas WHERE role = _role
  FOR UPDATE;

  -- Count usage this month (locking rows to prevent race)
  SELECT count(*) INTO _used FROM public.ai_usage_logs
  WHERE user_id = _user_id 
    AND created_at >= date_trunc('month', now()) 
    AND status = 'success';

  -- Check if unlimited
  IF _is_unlimited THEN
    INSERT INTO public.ai_usage_logs (user_id, function_name, model, status)
    VALUES (_user_id, _function_name, _model, 'pending')
    RETURNING id INTO _log_id;

    RETURN jsonb_build_object('allowed', true, 'log_id', _log_id, 'used', _used, 'unlimited', true);
  END IF;

  -- Check quota
  IF _used >= _monthly_limit THEN
    RETURN jsonb_build_object('allowed', false, 'log_id', null, 'used', _used, 'limit', _monthly_limit, 'remaining', 0);
  END IF;

  -- Reserve slot by inserting a pending log
  INSERT INTO public.ai_usage_logs (user_id, function_name, model, status)
  VALUES (_user_id, _function_name, _model, 'pending')
  RETURNING id INTO _log_id;

  RETURN jsonb_build_object(
    'allowed', true, 
    'log_id', _log_id, 
    'used', _used + 1, 
    'limit', _monthly_limit, 
    'remaining', GREATEST(_monthly_limit - _used - 1, 0)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.add_sicoob_order_invoice(p_order_id uuid, p_invoice_number text, p_file_type text, p_file_path text, p_amount numeric DEFAULT NULL::numeric, p_access_key text DEFAULT NULL::text, p_issued_at date DEFAULT NULL::date)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_invoice_id uuid;
BEGIN
  IF v_actor_id IS NULL OR NOT public.sicoob_actor_can_manage_fulfillment(v_actor_id, p_order_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode anexar documentos a este pedido.';
  END IF;
  IF p_file_type NOT IN ('pdf', 'xml')
     OR p_file_path NOT LIKE p_order_id::text || '/invoices/%'
     OR NULLIF(trim(p_invoice_number), '') IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Dados da nota fiscal inválidos.';
  END IF;

  INSERT INTO public.sicoob_order_invoices (
    order_id, invoice_number, file_type, file_path, amount, access_key, issued_at, created_by
  ) VALUES (
    p_order_id, trim(p_invoice_number), p_file_type, p_file_path,
    p_amount, NULLIF(trim(p_access_key), ''), p_issued_at, v_actor_id
  ) RETURNING id INTO v_invoice_id;
  RETURN v_invoice_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.allocate_sicoob_consolidation_by_order_pa(p_consolidation_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_group public.order_consolidations%ROWTYPE;
  v_count integer;
BEGIN
  SELECT * INTO v_group FROM public.order_consolidations
   WHERE id = p_consolidation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Consolidação não encontrada.'; END IF;
  IF v_group.status NOT IN ('draft', 'pending_seller') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Distribuição já despachada e não pode ser refeita.';
  END IF;
  IF NOT public.sicoob_actor_can_manage_consolidation(v_actor_id, v_group.singular_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário fora do escopo da consolidação.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.order_consolidation_orders co
    JOIN public.sicoob_order_items oi ON oi.order_id = co.order_id
    WHERE co.consolidation_id = p_consolidation_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A consolidação não possui itens para distribuir.';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM public.order_consolidation_orders co
      JOIN public.sicoob_orders o ON o.id = co.order_id
      LEFT JOIN public.postos_atendimento pa ON pa.id = o.pa_id
     WHERE co.consolidation_id = p_consolidation_id
       AND (
         pa.id IS NULL
         OR pa.is_active IS DISTINCT FROM true
         OR NULLIF(trim(pa.nome), '') IS NULL
         OR NULLIF(trim(pa.codigo), '') IS NULL
         OR NULLIF(trim(pa.endereco), '') IS NULL
         OR NULLIF(trim(pa.cidade), '') IS NULL
         OR NULLIF(trim(pa.uf), '') IS NULL
       )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Todos os destinos precisam estar ativos, identificados e com endereço completo.';
  END IF;

  PERFORM set_config('app.sicoob_consolidation_operation', 'allocate', true);
  DELETE FROM public.sicoob_delivery_allocations a USING public.sicoob_delivery_destinations d
   WHERE a.destination_id = d.id AND d.consolidation_id = p_consolidation_id;
  DELETE FROM public.sicoob_delivery_destinations WHERE consolidation_id = p_consolidation_id;

  INSERT INTO public.sicoob_delivery_destinations (
    consolidation_id, pa_id, destination_name, address_snapshot
  )
  SELECT DISTINCT p_consolidation_id, pa.id, pa.nome,
    jsonb_build_object('codigo', pa.codigo, 'endereco', pa.endereco, 'cidade', pa.cidade, 'uf', pa.uf)
  FROM public.order_consolidation_orders co
  JOIN public.sicoob_orders o ON o.id = co.order_id
  JOIN public.postos_atendimento pa ON pa.id = o.pa_id
  WHERE co.consolidation_id = p_consolidation_id;

  INSERT INTO public.sicoob_delivery_allocations (destination_id, order_item_id, quantity)
  SELECT d.id, oi.id, oi.quantity
  FROM public.order_consolidation_orders co
  JOIN public.sicoob_orders o ON o.id = co.order_id
  JOIN public.sicoob_order_items oi ON oi.order_id = o.id
  JOIN public.sicoob_delivery_destinations d
    ON d.consolidation_id = p_consolidation_id AND d.pa_id = o.pa_id
  WHERE co.consolidation_id = p_consolidation_id;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.append_quote_history_note(p_quote_id uuid, p_action text, p_description text, p_field_changed text DEFAULT NULL::text, p_old_value text DEFAULT NULL::text, p_new_value text DEFAULT NULL::text, p_metadata jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_history_id uuid;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária.';
  END IF;
  IF p_action NOT IN (
    'created', 'updated', 'item_added', 'item_removed', 'item_updated',
    'pdf_generated', 'pdf_exported_bulk', 'sync_started', 'sync_error',
    'sync_success', 'note'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Tipo de anotação não permitido.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.quotes q
    WHERE q.id = p_quote_id
      AND (q.seller_id = v_actor_id OR public.can_manage_quote_scope(v_actor_id, q.id))
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Sem acesso ao orçamento.';
  END IF;

  INSERT INTO public.quote_history (
    quote_id, user_id, action, description, field_changed, old_value, new_value, metadata
  ) VALUES (
    p_quote_id, v_actor_id, p_action, left(p_description, 2000),
    p_field_changed, p_old_value, p_new_value, COALESCE(p_metadata, '{}'::jsonb)
  ) RETURNING id INTO v_history_id;
  RETURN v_history_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_local_quote_approval_response(_token text, _response text, _response_notes text, _signer_name text, _signer_document text, _signature_data_url text, _signer_ip text, _signer_user_agent text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'vault', 'extensions'
AS $function$
DECLARE
  v_token public.quote_approval_tokens%ROWTYPE;
  v_quote public.quotes%ROWTYPE;
  v_now timestamptz;
  v_evidence jsonb;
  v_key_id uuid;
  v_hmac_key text;
  v_quote_snapshot jsonb;
  v_quote_snapshot_sha256 text;
BEGIN
  IF _response IS NULL OR _response NOT IN ('approved', 'rejected')
     OR length(_response_notes) > 2000
     OR length(_signer_ip) > 64
     OR length(_signer_user_agent) > 512 THEN
    RAISE EXCEPTION 'Resposta inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT q.* INTO v_quote FROM public.quotes q
    JOIN public.quote_approval_tokens t ON q.id::text = t.quote_id
    WHERE t.token = _token FOR UPDATE OF q;
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT * INTO v_token FROM public.quote_approval_tokens WHERE token = _token FOR UPDATE;
  v_now := clock_timestamp();
  IF NOT FOUND OR v_token.status <> 'active' OR v_token.responded_at IS NOT NULL
     OR (v_token.expires_at IS NOT NULL AND v_token.expires_at <= v_now)
     OR v_quote.seller_id <> v_token.seller_id OR v_quote.deleted_at IS NOT NULL
     OR NOT v_quote.is_latest_version OR v_quote.status NOT IN ('draft', 'pending', 'sent', 'viewed', 'revision') THEN
    RETURN false;
  END IF;
  IF v_quote.valid_until IS NOT NULL AND v_quote.valid_until::date < CURRENT_DATE THEN
    RETURN false;
  END IF;

  IF _signature_data_url IS NOT NULL THEN
    SELECT k.id, v.decrypted_secret INTO v_key_id, v_hmac_key
    FROM public.quote_approval_evidence_keys k
    JOIN vault.decrypted_secrets v ON v.name=k.vault_secret_name
    WHERE k.is_active
    ORDER BY v.updated_at DESC LIMIT 1;
    IF v_hmac_key IS NULL OR length(v_hmac_key) < 32 THEN
      RAISE EXCEPTION 'Evidência de assinatura não configurada.' USING ERRCODE = '55000';
    END IF;
  END IF;

  UPDATE public.quotes SET status = _response, client_response = _response,
    client_response_at = v_now, client_response_notes = _response_notes
    WHERE id = v_quote.id;
  IF _signature_data_url IS NOT NULL THEN
    v_quote_snapshot := public.quote_approval_content_snapshot(v_quote.id);
    v_quote_snapshot_sha256 := encode(extensions.digest(convert_to(v_quote_snapshot::text, 'UTF8'), 'sha256'), 'hex');
    v_evidence := jsonb_build_object(
      'version', 1,
      'quote_id', v_quote.id,
      'quote_number', v_quote.quote_number,
      'quote_version', v_quote.version,
      'quote_snapshot', v_quote_snapshot,
      'quote_snapshot_sha256', v_quote_snapshot_sha256,
      'token_sha256', encode(extensions.digest(convert_to(_token, 'UTF8'), 'sha256'), 'hex'),
      'response', _response,
      'signer_name', _signer_name,
      'signer_document_sha256', encode(extensions.digest(convert_to(_signer_document, 'UTF8'), 'sha256'), 'hex'),
      'signed_at', v_now,
      'signer_ip', COALESCE(NULLIF(btrim(_signer_ip), ''), 'unknown'),
      'signer_user_agent', COALESCE(NULLIF(btrim(_signer_user_agent), ''), 'unknown'),
      'signature_image_sha256', encode(extensions.digest(convert_to(_signature_data_url, 'UTF8'), 'sha256'), 'hex')
    );
  END IF;
  UPDATE public.quote_approval_tokens SET
    status = 'responded', response = _response, response_notes = _response_notes,
    responded_at = v_now, updated_at = v_now,
    signer_name = _signer_name, signer_document = _signer_document,
    signer_ip = CASE WHEN _signature_data_url IS NOT NULL THEN COALESCE(NULLIF(btrim(_signer_ip), ''), 'unknown') END,
    signer_user_agent = CASE WHEN _signature_data_url IS NOT NULL THEN COALESCE(NULLIF(btrim(_signer_user_agent), ''), 'unknown') END,
    signed_at = CASE WHEN _signature_data_url IS NOT NULL THEN v_now END,
    signature_data_url = _signature_data_url,
    signature_evidence = v_evidence,
    signature_key_id = v_key_id,
    signature_algorithm = CASE WHEN _signature_data_url IS NOT NULL THEN 'hmac-sha256-v1' END,
    signature_hash = CASE WHEN _signature_data_url IS NOT NULL
      THEN encode(extensions.hmac(convert_to(v_evidence::text, 'UTF8'), convert_to(v_hmac_key, 'UTF8'), 'sha256'), 'hex') END
    WHERE id = v_token.id;
  INSERT INTO public.quote_history(quote_id, user_id, action, description)
    VALUES (v_quote.id, v_quote.seller_id, 'public_response',
      CASE _response WHEN 'approved' THEN 'Orçamento aprovado pelo link público.'
      ELSE 'Orçamento recusado pelo link público.' END);
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_quote_with_pdf_atomic(p_quote_id uuid, p_expected_quote_row_version integer, p_approved_pdf_url text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, status text, row_version integer, approved_pdf_url text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_quote public.quotes%ROWTYPE;
  v_updated public.quotes%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL OR p_expected_quote_row_version IS NULL
     OR p_approved_pdf_url IS NULL
     OR p_approved_pdf_url !~ '^quotes/[0-9a-fA-F-]+/[^/]+[.]pdf$'
     OR length(p_approved_pdf_url) > 1024 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Parâmetros de aprovação inválidos.';
  END IF;
  SELECT * INTO v_quote FROM public.quotes q WHERE q.id = p_quote_id FOR UPDATE;
  IF NOT FOUND
     OR NOT public.can_manage_quote_scope(v_actor_id, p_quote_id)
     OR v_quote.row_version IS DISTINCT FROM p_expected_quote_row_version
     OR v_quote.status::text NOT IN ('pending', 'sent')
     OR v_quote.deleted_at IS NOT NULL
     OR COALESCE(v_quote.is_latest_version, true) IS NOT TRUE
     OR p_approved_pdf_url !~ ('^quotes/' || v_quote.id::text || '/') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O orçamento não pode ser aprovado com este documento.';
  END IF;

  PERFORM set_config('app.quote_governance_write', 'true', true);
  UPDATE public.quotes
  SET status = 'approved', approved_pdf_url = p_approved_pdf_url,
      approved_by = v_actor_id, approved_at = now(),
      row_version = quotes.row_version + 1, updated_at = now()
  WHERE quotes.id = p_quote_id
  RETURNING * INTO v_updated;

  INSERT INTO public.quote_history (
    quote_id, user_id, action, description, field_changed, old_value, new_value, metadata
  ) VALUES (
    v_updated.id, v_actor_id, 'quote_approved_with_pdf',
    'Orçamento aprovado com PDF assinado', 'status', v_quote.status::text, 'approved',
    jsonb_build_object('approved_pdf_path', p_approved_pdf_url, 'notes', p_notes)
  );
  RETURN QUERY SELECT v_updated.id, v_updated.status::text, v_updated.row_version, v_updated.approved_pdf_url;
END;
$function$

CREATE OR REPLACE FUNCTION public.approve_sicoob_order(p_request_id uuid, p_order_id uuid, p_manager_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_request public.sicoob_approval_requests%ROWTYPE;
  v_order public.sicoob_orders%ROWTYPE;
  v_authority record;
BEGIN
  IF v_actor_id IS NULL OR p_manager_id IS DISTINCT FROM v_actor_id THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Identidade do aprovador inválida.';
  END IF;
  SELECT * INTO v_order FROM public.sicoob_orders WHERE id=p_order_id FOR UPDATE;
  SELECT * INTO v_request FROM public.sicoob_approval_requests WHERE id=p_request_id FOR UPDATE;
  IF NOT FOUND OR v_order.id IS NULL OR v_request.order_id <> v_order.id THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Solicitação ou pedido não encontrado.';
  END IF;
  IF v_request.status <> 'pending' THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Solicitação já decidida.';
  END IF;
  IF v_order.status NOT IN ('waiting_approval', 'escalated_to_board') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Pedido não está aguardando aprovação.';
  END IF;
  IF v_order.total_amount IS DISTINCT FROM v_request.amount_at_request THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='O valor do pedido diverge da solicitação submetida; reenvie para aprovação.';
  END IF;
  SELECT * INTO STRICT v_authority FROM public.resolve_sicoob_approval_authority(
    v_actor_id, v_order.id, v_request.requester_id,
    v_order.status='escalated_to_board', 'approve_order'
  );
  PERFORM set_config('app.sicoob_approval_operation', 'approve', true);
  UPDATE public.sicoob_approval_requests SET
    status='approved', approver_id=v_actor_id,
    approval_delegation_id=v_authority.delegation_id,
    authority_delegator_id=CASE WHEN v_authority.delegation_id IS NULL THEN NULL ELSE v_authority.authority_delegator_id END,
    updated_at=clock_timestamp()
  WHERE id=v_request.id;
  UPDATE public.sicoob_orders SET
    status='confirmed', approved_by=v_actor_id, approved_at=clock_timestamp(), updated_at=clock_timestamp()
  WHERE id=v_order.id;
  INSERT INTO public.sicoob_manager_audit(manager_id, order_id, action, details)
  VALUES (v_actor_id, v_order.id, 'approve', jsonb_build_object(
    'request_id', v_request.id,
    'policy_version', v_order.approval_policy_version,
    'authority_source', CASE WHEN v_authority.delegation_id IS NULL THEN 'direct' ELSE 'delegated' END,
    'delegation_id', v_authority.delegation_id,
    'authority_delegator_id', CASE WHEN v_authority.delegation_id IS NULL THEN NULL ELSE v_authority.authority_delegator_id END
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_quote_transition(p_actor_id uuid, p_quote quotes, p_new_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_is_seller boolean := p_quote.seller_id = p_actor_id;
  v_is_manager boolean := public.can_manage_quote_scope(p_actor_id, p_quote.id);
  v_is_singular_buyer boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE p.user_id = p_actor_id
      AND p.cooperativa_id = p_quote.singular_id
      AND p.role IN ('comprador_singular', 'gestor_compras')
  ) INTO v_is_singular_buyer;

  IF p_quote.deleted_at IS NOT NULL OR COALESCE(p_quote.is_latest_version, true) IS NOT TRUE THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O orçamento não está disponível para transição.';
  END IF;

  IF p_quote.status::text = p_new_status THEN
    RETURN;
  END IF;

  IF v_is_seller AND (
    (p_quote.status::text IN ('draft', 'rejected', 'rejected_singular', 'expired') AND p_new_status = 'draft')
    OR (p_quote.status::text = 'draft' AND p_new_status IN ('pending', 'sent', 'pending_singular_approval'))
    OR (p_quote.status::text = 'pending' AND p_new_status = 'sent')
  ) THEN
    RETURN;
  END IF;

  IF v_is_manager AND p_new_status = 'rejected'
     AND p_quote.status::text IN ('pending', 'sent') THEN
    RETURN;
  END IF;

  IF (v_is_singular_buyer OR v_is_manager)
     AND p_quote.status::text = 'pending_singular_approval'
     AND p_new_status IN ('approved_singular', 'rejected_singular') THEN
    RETURN;
  END IF;

  RAISE EXCEPTION USING
    ERRCODE = '42501',
    MESSAGE = 'A transição de status não é permitida para este ator e orçamento.';
END;
$function$

CREATE OR REPLACE FUNCTION public.assert_sicoob_approval_actor(p_actor_id uuid, p_order_id uuid, p_requester_id uuid DEFAULT NULL::uuid, p_board_only boolean DEFAULT false)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order public.sicoob_orders%ROWTYPE;
  v_policy record;
BEGIN
  SELECT * INTO v_order
    FROM public.sicoob_orders
   WHERE id = p_order_id;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Pedido não encontrado.';
  END IF;

  SELECT * INTO v_policy
    FROM public.get_sicoob_order_approval_policy(p_order_id);

  IF v_policy.require_active_membership
     AND NOT EXISTS (
       SELECT 1
         FROM public.profiles p
        WHERE (p.user_id = p_actor_id OR p.id = p_actor_id)
          AND p.is_active IS TRUE
          AND p.deleted_at IS NULL
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'A decisão exige vínculo ativo com a cooperativa.';
  END IF;

  IF v_policy.forbid_self_approval
     AND (v_order.created_by = p_actor_id OR p_requester_id = p_actor_id) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'A política vigente não permite decidir o próprio pedido.';
  END IF;

  IF NOT public.sicoob_actor_can_approve(p_actor_id, p_order_id, p_board_only) THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Aprovador fora da alçada ou do escopo do pedido.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_all_rls_compliance()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_total INTEGER;
    v_with_rls INTEGER;
    v_missing TEXT[];
    v_permissive TEXT[];
    v_score DECIMAL(5,2);
    v_result JSONB;
BEGIN
    -- Contar tabelas no schema public
    SELECT count(*) INTO v_total FROM pg_tables WHERE schemaname = 'public';

    -- Tabelas com RLS habilitado
    SELECT count(*) INTO v_with_rls 
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity = true;

    -- Listar tabelas sem RLS
    SELECT array_agg(relname) INTO v_missing
    FROM pg_class c
    JOIN pg_namespace n ON n.oid = c.relnamespace
    WHERE n.nspname = 'public' AND c.relkind = 'r' AND c.relrowsecurity = false;

    -- Listar tabelas com políticas excessivamente permissivas (USING true)
    SELECT array_agg(DISTINCT tablename) INTO v_permissive
    FROM pg_policies
    WHERE schemaname = 'public' AND (qual = '(true)' OR with_check = '(true)');

    -- Calcular score (0-100)
    IF v_total > 0 THEN
        v_score := (v_with_rls::DECIMAL / v_total::DECIMAL) * 100;
    ELSE
        v_score := 100;
    END IF;

    -- Salvar auditoria
    INSERT INTO public.qa_rls_audits (tables_total, tables_with_rls, tables_missing_rls, tables_permissive_rls, score)
    VALUES (v_total, v_with_rls, COALESCE(v_missing, '{}'), COALESCE(v_permissive, '{}'), v_score);

    SELECT jsonb_build_object(
        'score', v_score,
        'total', v_total,
        'with_rls', v_with_rls,
        'missing', COALESCE(v_missing, '{}'),
        'permissive', COALESCE(v_permissive, '{}')
    ) INTO v_result;

    RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_mcp_api_keys_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_action       text;
  v_user_id      uuid;
  v_resource_id  text;
  v_details      jsonb;
  v_old_scopes   text[];
  v_new_scopes   text[];
  v_old_revoked  timestamptz;
  v_new_revoked  timestamptz;
  v_old_expires  timestamptz;
  v_new_expires  timestamptz;
  v_old_name     text;
  v_new_name     text;
  v_changed      jsonb := '{}'::jsonb;
BEGIN
  -- Resolve identidade: created_by da linha, fallback para auth.uid(), fallback para zero-uuid (system)
  IF TG_OP = 'DELETE' THEN
    v_user_id    := COALESCE(OLD.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := OLD.id::text;
    v_action     := 'mcp_key.db_deleted';
    v_details    := jsonb_build_object(
      'name',       OLD.name,
      'key_prefix', OLD.key_prefix,
      'scopes',     to_jsonb(OLD.scopes),
      'was_revoked', (OLD.revoked_at IS NOT NULL),
      'created_by', OLD.created_by
    );
  ELSIF TG_OP = 'INSERT' THEN
    v_user_id    := COALESCE(NEW.created_by, auth.uid(), '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;
    v_action     := 'mcp_key.db_inserted';
    v_details    := jsonb_build_object(
      'name',         NEW.name,
      'key_prefix',   NEW.key_prefix,
      'scopes',       to_jsonb(NEW.scopes),
      'is_full',      (NEW.scopes @> ARRAY['*']::text[]),
      'expires_at',   NEW.expires_at,
      'rotated_from', NEW.rotated_from,
      'created_by',   NEW.created_by
    );
  ELSE -- UPDATE
    v_user_id    := COALESCE(auth.uid(), NEW.created_by, '00000000-0000-0000-0000-000000000000'::uuid);
    v_resource_id := NEW.id::text;

    v_old_scopes  := OLD.scopes;
    v_new_scopes  := NEW.scopes;
    v_old_revoked := OLD.revoked_at;
    v_new_revoked := NEW.revoked_at;
    v_old_expires := OLD.expires_at;
    v_new_expires := NEW.expires_at;
    v_old_name    := OLD.name;
    v_new_name    := NEW.name;

    -- Detecta o que mudou para um diff conciso
    IF v_old_name IS DISTINCT FROM v_new_name THEN
      v_changed := v_changed || jsonb_build_object('name', jsonb_build_object('old', v_old_name, 'new', v_new_name));
    END IF;
    IF v_old_scopes IS DISTINCT FROM v_new_scopes THEN
      v_changed := v_changed || jsonb_build_object('scopes', jsonb_build_object('old', to_jsonb(v_old_scopes), 'new', to_jsonb(v_new_scopes)));
    END IF;
    IF v_old_expires IS DISTINCT FROM v_new_expires THEN
      v_changed := v_changed || jsonb_build_object('expires_at', jsonb_build_object('old', v_old_expires, 'new', v_new_expires));
    END IF;
    IF v_old_revoked IS DISTINCT FROM v_new_revoked THEN
      v_changed := v_changed || jsonb_build_object('revoked_at', jsonb_build_object('old', v_old_revoked, 'new', v_new_revoked));
    END IF;

    -- Sem mudanças relevantes (ex.: somente touch em colunas auditadas externamente como last_used_at)
    -- Não auditamos: barulho desnecessário e last_used_at é registrado pelo mcp-server.
    IF v_changed = '{}'::jsonb THEN
      RETURN NEW;
    END IF;

    -- Sub-ação semântica para facilitar busca
    IF v_old_revoked IS NULL AND v_new_revoked IS NOT NULL THEN
      v_action := 'mcp_key.db_revoked';
    ELSIF v_old_scopes IS DISTINCT FROM v_new_scopes
          AND (v_new_scopes @> ARRAY['*']::text[])
          AND NOT (COALESCE(v_old_scopes, ARRAY[]::text[]) @> ARRAY['*']::text[]) THEN
      v_action := 'mcp_key.db_scope_escalated';
    ELSE
      v_action := 'mcp_key.db_updated';
    END IF;

    v_details := jsonb_build_object(
      'name',       NEW.name,
      'key_prefix', NEW.key_prefix,
      'changed',    v_changed,
      'is_full_now', (NEW.scopes @> ARRAY['*']::text[]),
      'created_by', NEW.created_by
    );
  END IF;

  -- Insere com source identificando trigger (edge functions usam 'mcp-keys-*')
  INSERT INTO public.admin_audit_log (
    user_id, action, resource_type, resource_id,
    details, source, status, created_at
  ) VALUES (
    v_user_id,
    v_action,
    'mcp_api_key',
    v_resource_id,
    v_details,
    'db_trigger:mcp_api_keys',
    'success',
    now()
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  -- Nunca bloquear a operação principal por falha de auditoria
  RAISE WARNING 'audit_mcp_api_keys_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_ownership_orphans(_triggered_by text DEFAULT 'manual'::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_started_at timestamptz := clock_timestamp();
  v_report_id uuid;
  v_owner_columns text[] := ARRAY['seller_id', 'user_id', 'owner_id', 'created_by'];
  v_table record;
  v_col text;
  v_null_count bigint;
  v_orphan_count bigint;
  v_total_null bigint := 0;
  v_total_orphan bigint := 0;
  v_tables_scanned int := 0;
  v_details jsonb := '[]'::jsonb;
  v_table_entry jsonb;
  v_rls jsonb;
  v_rls_gaps int := 0;
BEGIN
  IF auth.uid() IS NOT NULL
     AND NOT (has_role(auth.uid(), 'admin'::app_role) OR has_role(auth.uid(), 'dev'::app_role))
  THEN
    RAISE EXCEPTION 'audit_ownership_orphans: acesso negado';
  END IF;

  FOR v_table IN
    SELECT c.table_name, c.column_name
    FROM information_schema.columns c
    JOIN information_schema.tables t
      ON t.table_schema = c.table_schema AND t.table_name = c.table_name
    WHERE c.table_schema = 'public'
      AND c.column_name = ANY(v_owner_columns)
      AND t.table_type = 'BASE TABLE'
      AND c.table_name NOT IN (
        'login_attempts','step_up_audit_log','search_analytics',
        'query_telemetry','mcp_access_violations','product_views',
        'quote_history','optimization_queue','kit_templates'
      )
    ORDER BY c.table_name
  LOOP
    v_col := v_table.column_name;
    v_tables_scanned := v_tables_scanned + 1;

    EXECUTE format('SELECT count(*) FROM public.%I WHERE %I IS NULL',
      v_table.table_name, v_col) INTO v_null_count;

    EXECUTE format(
      'SELECT count(*) FROM public.%I t
        WHERE t.%I IS NOT NULL
          AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
      v_table.table_name, v_col, v_col
    ) INTO v_orphan_count;

    IF v_null_count > 0 OR v_orphan_count > 0 THEN
      v_table_entry := jsonb_build_object(
        'table', v_table.table_name,
        'owner_column', v_col,
        'null_owner_count', v_null_count,
        'missing_user_count', v_orphan_count
      );
      v_details := v_details || v_table_entry;
    END IF;

    v_total_null := v_total_null + v_null_count;
    v_total_orphan := v_total_orphan + v_orphan_count;
  END LOOP;

  -- Cobertura RLS das tabelas críticas
  v_rls := public.audit_rls_coverage();
  SELECT COALESCE(SUM(jsonb_array_length(elem->'missing_ops')),0)::int
    INTO v_rls_gaps
  FROM jsonb_array_elements(v_rls) elem;

  INSERT INTO public.ownership_audit_reports (
    total_tables_scanned, total_issues_found,
    null_owner_count, missing_user_count, details,
    triggered_by, duration_ms,
    rls_coverage, rls_gaps_count
  ) VALUES (
    v_tables_scanned,
    (v_total_null + v_total_orphan)::int,
    v_total_null::int,
    v_total_orphan::int,
    v_details,
    coalesce(_triggered_by, 'manual'),
    EXTRACT(MILLISECONDS FROM (clock_timestamp() - v_started_at))::int,
    v_rls,
    v_rls_gaps
  ) RETURNING id INTO v_report_id;

  RETURN v_report_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_sicoob_order_item_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF (TG_OP = 'INSERT') THEN
        INSERT INTO public.sicoob_order_item_logs (order_id, item_id, user_id, action, new_data)
        VALUES (NEW.order_id, NEW.id, auth.uid(), 'INSERT', row_to_json(NEW)::jsonb);
    ELSIF (TG_OP = 'UPDATE') THEN
        INSERT INTO public.sicoob_order_item_logs (order_id, item_id, user_id, action, old_data, new_data)
        VALUES (NEW.order_id, NEW.id, auth.uid(), 'UPDATE', row_to_json(OLD)::jsonb, row_to_json(NEW)::jsonb);
    ELSIF (TG_OP = 'DELETE') THEN
        INSERT INTO public.sicoob_order_item_logs (order_id, item_id, user_id, action, old_data)
        VALUES (OLD.order_id, OLD.id, auth.uid(), 'DELETE', row_to_json(OLD)::jsonb);
    END IF;
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_sicoob_rls_policies()
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_table TEXT;
    v_policy_exists BOOLEAN;
    v_rls_enabled BOOLEAN;
    v_tables_to_check TEXT[] := ARRAY['cooperativas', 'pa_budgets', 'sicoob_orders', 'sicoob_order_items', 'sicoob_order_history'];
BEGIN
    FOR v_table IN SELECT unnest(v_tables_to_check) LOOP
        -- 1. Verificar se RLS está habilitado
        SELECT relrowsecurity INTO v_rls_enabled 
        FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace 
        WHERE n.nspname = 'public' AND c.relname = v_table;

        IF NOT v_rls_enabled THEN
            INSERT INTO public.sicoob_rls_audit_logs (table_name, status, issue_details)
            VALUES (v_table, 'failure', 'RLS is DISABLED on this table');
            CONTINUE;
        END IF;

        -- 2. Verificar se existem políticas (evitar regressão de visibilidade total)
        SELECT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND tablename = v_table)
        INTO v_policy_exists;

        IF NOT v_policy_exists THEN
            INSERT INTO public.sicoob_rls_audit_logs (table_name, status, issue_details)
            VALUES (v_table, 'failure', 'No policies found. Table might be wide open or completely blocked.');
            CONTINUE;
        END IF;

        -- 3. Validação específica de isolamento (ex: deve conter filtro de PA ou Cooperativa)
        -- Nota: Esta é uma verificação heurística simples para o log
        IF v_table IN ('pa_budgets', 'sicoob_orders') THEN
            IF NOT EXISTS (
                SELECT 1 FROM pg_policies 
                WHERE schemaname = 'public' AND tablename = v_table 
                AND (qual ILIKE '%pa_id%' OR qual ILIKE '%cooperativa_id%')
            ) THEN
                INSERT INTO public.sicoob_rls_audit_logs (table_name, status, issue_details)
                VALUES (v_table, 'failure', 'Missing mandatory PA/Cooperative isolation filters in policies');
                CONTINUE;
            END IF;
        END IF;

        -- Se chegou aqui, a tabela passou na auditoria básica
        INSERT INTO public.sicoob_rls_audit_logs (table_name, status)
        VALUES (v_table, 'success');
    END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.audit_user_role_changes()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _actor uuid := auth.uid();
  _action text;
  _target uuid;
  _old_role text;
  _new_role text;
  _details jsonb;
BEGIN
  IF TG_OP = 'INSERT' THEN
    _action := 'role.granted';
    _target := NEW.user_id;
    _old_role := NULL;
    _new_role := NEW.role::text;
  ELSIF TG_OP = 'UPDATE' THEN
    -- só audita se a role mudou
    IF NEW.role IS NOT DISTINCT FROM OLD.role THEN
      RETURN NEW;
    END IF;
    _action := 'role.changed';
    _target := NEW.user_id;
    _old_role := OLD.role::text;
    _new_role := NEW.role::text;
  ELSIF TG_OP = 'DELETE' THEN
    _action := 'role.revoked';
    _target := OLD.user_id;
    _old_role := OLD.role::text;
    _new_role := NULL;
  ELSE
    RETURN NULL;
  END IF;

  _details := jsonb_build_object(
    'target_user_id', _target,
    'old_role', _old_role,
    'new_role', _new_role,
    'op', TG_OP,
    -- 'system' quando não há ator JWT (trigger por service_role/migration/edge function sem contexto)
    'source', CASE WHEN _actor IS NULL THEN 'system' ELSE 'authenticated' END
  );

  INSERT INTO public.admin_audit_log (
    user_id, action, resource_type, resource_id, details, source, created_at
  ) VALUES (
    COALESCE(_actor, _target),
    _action,
    'user_role',
    _target::text,
    _details,
    CASE WHEN _actor IS NULL THEN 'system' ELSE 'database_trigger' END,
    now()
  );

  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  -- nunca bloqueia a operação principal por falha no log
  RAISE WARNING 'audit_user_role_changes failed: %', SQLERRM;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.auto_revoke_orphan_full_keys(_source text DEFAULT 'cron'::text)
 RETURNS TABLE(key_id uuid, created_by uuid, revoked_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _now TIMESTAMP WITH TIME ZONE := now();
  _rec RECORD;
BEGIN
  IF _source NOT IN ('trigger','cron','manual') THEN
    RAISE EXCEPTION 'invalid source: %', _source USING ERRCODE = '22023';
  END IF;

  FOR _rec IN
    SELECT k.id, k.created_by
      FROM public.mcp_api_keys k
     WHERE k.revoked_at IS NULL
       AND '*' = ANY(k.scopes)
       AND NOT public.is_dev(k.created_by)
     FOR UPDATE
  LOOP
    -- Revoga a chave (trigger existente log_mcp_key_revocation registra a mudança)
    UPDATE public.mcp_api_keys
       SET revoked_at = _now,
           updated_at = _now
     WHERE mcp_api_keys.id = _rec.id
       AND mcp_api_keys.revoked_at IS NULL;

    -- Log dedicado do mecanismo de defesa
    INSERT INTO public.mcp_key_auto_revocations(key_id, created_by, revoked_at, source, reason)
    VALUES (_rec.id, _rec.created_by, _now, _source, 'creator_lost_dev_role');

    -- Correlação forense no audit log de step-up (mesma trilha das emissões FULL)
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (
      _rec.created_by,
      'mcp_full_issue',
      _rec.id::text,
      'auto_revoked',
      jsonb_build_object(
        'reason', 'creator_lost_dev_role',
        'source', _source
      )
    );

    key_id := _rec.id;
    created_by := _rec.created_by;
    revoked_at := _now;
    RETURN NEXT;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.bulk_update_quote_status_atomic(p_quote_ids uuid[], p_expected_row_versions integer[], p_status text, p_notes text DEFAULT NULL::text)
 RETURNS TABLE(id uuid, status text, row_version integer)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_quote public.quotes%ROWTYPE;
  v_updated public.quotes%ROWTYPE;
  v_index integer;
BEGIN
  IF v_actor_id IS NULL
     OR cardinality(p_quote_ids) IS NULL
     OR cardinality(p_quote_ids) NOT BETWEEN 1 AND 100
     OR cardinality(p_quote_ids) <> cardinality(p_expected_row_versions)
     OR p_status NOT IN (
       'draft', 'pending', 'sent', 'approved', 'rejected', 'expired',
       'pending_singular_approval',
       'approved_singular', 'rejected_singular'
     )
     OR (SELECT count(DISTINCT quote_id) FROM unnest(p_quote_ids) AS quote_id) <> cardinality(p_quote_ids) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Parâmetros de transição inválidos.';
  END IF;
  IF p_status = 'approved' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A aprovação final exige PDF assinado.';
  END IF;

  PERFORM 1 FROM public.quotes q WHERE q.id = ANY(p_quote_ids) ORDER BY q.id FOR UPDATE;
  IF (SELECT count(*) FROM public.quotes q WHERE q.id = ANY(p_quote_ids)) <> cardinality(p_quote_ids) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Um ou mais orçamentos não foram encontrados.';
  END IF;

  FOR v_index IN SELECT generate_subscripts(p_quote_ids, 1)
  LOOP
    SELECT * INTO v_quote FROM public.quotes q WHERE q.id = p_quote_ids[v_index];
    -- Autoriza antes de qualquer retorno idempotente. Sem esta verificação,
    -- um ator fora do escopo consegue confirmar existência, status e versão.
    IF NOT (
      v_quote.seller_id = v_actor_id
      OR public.can_manage_quote_scope(v_actor_id, v_quote.id)
    ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '42501',
        MESSAGE = 'Um ou mais orçamentos não estão no seu escopo.';
    END IF;
    -- Retry da mesma intenção: devolve o estado confirmado sem nova escrita.
    IF v_quote.status::text = p_status THEN
      CONTINUE;
    END IF;
    IF v_quote.row_version IS DISTINCT FROM p_expected_row_versions[v_index] THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Um ou mais orçamentos foram modificados.';
    END IF;
    PERFORM public.assert_quote_transition(v_actor_id, v_quote, p_status);
  END LOOP;

  PERFORM set_config('app.quote_governance_write', 'true', true);
  FOR v_index IN SELECT generate_subscripts(p_quote_ids, 1)
  LOOP
    SELECT * INTO v_quote FROM public.quotes q WHERE q.id = p_quote_ids[v_index];
    IF v_quote.status::text = p_status THEN
      RETURN QUERY SELECT v_quote.id, v_quote.status::text, v_quote.row_version;
      CONTINUE;
    END IF;

    UPDATE public.quotes q
    SET status = p_status::public.quote_status,
        rejection_notes = CASE WHEN p_status IN ('rejected', 'rejected_singular') THEN p_notes ELSE NULL END,
        approved_at = CASE WHEN p_status = 'approved_singular' THEN now() ELSE q.approved_at END,
        approved_by = CASE WHEN p_status = 'approved_singular' THEN v_actor_id ELSE q.approved_by END,
        row_version = q.row_version + 1,
        updated_at = now()
    WHERE q.id = v_quote.id
    RETURNING * INTO v_updated;

    INSERT INTO public.quote_history (
      quote_id, user_id, action, description, field_changed, old_value, new_value, metadata
    ) VALUES (
      v_updated.id, v_actor_id, 'status_changed',
      format('Status alterado de "%s" para "%s"', v_quote.status, p_status),
      'status', v_quote.status, p_status, jsonb_build_object('notes', p_notes, 'bulk', true)
    );
    RETURN QUERY SELECT v_updated.id, v_updated.status::text, v_updated.row_version;
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.capture_sicoob_order_approval_policy()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_policy record;
  v_protected_statuses constant text[] := ARRAY[
    'waiting_approval', 'escalated_to_board', 'confirmed', 'logistic',
    'in_production', 'in_separation', 'in_transit', 'delivered',
    'completed', 'cancelled'
  ];
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status = ANY(v_protected_statuses) THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'O pedido deve entrar no fluxo de aprovação por uma transição formal.';
    END IF;
    RETURN NEW;
  END IF;

  IF OLD.status = 'rejected' AND NEW.status IN ('draft', 'pending') THEN
    NEW.approval_policy_id := NULL;
    NEW.approval_policy_version := NULL;
    NEW.approval_policy_snapshot := NULL;
    RETURN NEW;
  END IF;

  IF OLD.status = ANY(v_protected_statuses)
     AND (
       NEW.approval_policy_id IS DISTINCT FROM OLD.approval_policy_id
       OR NEW.approval_policy_version IS DISTINCT FROM OLD.approval_policy_version
       OR NEW.approval_policy_snapshot IS DISTINCT FROM OLD.approval_policy_snapshot
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'A política aplicada ao pedido é imutável depois da submissão.';
  END IF;

  IF NOT (OLD.status = ANY(v_protected_statuses))
     AND NEW.status = ANY(v_protected_statuses) THEN
    SELECT * INTO v_policy
      FROM public.get_sicoob_order_approval_policy(OLD.id);

    NEW.approval_policy_id := v_policy.policy_id;
    NEW.approval_policy_version := v_policy.policy_version;
    NEW.approval_policy_snapshot := jsonb_build_object(
      'policy_id', v_policy.policy_id,
      'version', v_policy.policy_version,
      'forbid_self_approval', v_policy.forbid_self_approval,
      'require_active_membership', v_policy.require_active_membership,
      'captured_at', now()
    );
  ELSIF NOT (OLD.status = ANY(v_protected_statuses))
        AND (
          NEW.approval_policy_id IS DISTINCT FROM OLD.approval_policy_id
          OR NEW.approval_policy_version IS DISTINCT FROM OLD.approval_policy_version
          OR NEW.approval_policy_snapshot IS DISTINCT FROM OLD.approval_policy_snapshot
        ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'A política só pode ser definida pela transição formal de submissão.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_ai_quota(_user_id uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _role app_role;
  _monthly_limit integer;
  _is_unlimited boolean;
  _used integer;
BEGIN
  SELECT role INTO _role FROM public.user_roles WHERE user_id = _user_id LIMIT 1;
  IF _role IS NULL THEN
    RETURN jsonb_build_object('allowed', false, 'used', 0, 'limit', 0, 'remaining', 0, 'reason', 'no_role');
  END IF;

  SELECT monthly_limit, is_unlimited INTO _monthly_limit, _is_unlimited
  FROM public.ai_usage_quotas WHERE role = _role;

  IF _is_unlimited THEN
    SELECT count(*) INTO _used FROM public.ai_usage_logs
    WHERE user_id = _user_id AND created_at >= date_trunc('month', now()) AND status IN ('success', 'pending');
    RETURN jsonb_build_object('allowed', true, 'used', _used, 'limit', -1, 'remaining', -1, 'unlimited', true);
  END IF;

  SELECT count(*) INTO _used FROM public.ai_usage_logs
  WHERE user_id = _user_id AND created_at >= date_trunc('month', now()) AND status IN ('success', 'pending');

  RETURN jsonb_build_object(
    'allowed', _used < _monthly_limit,
    'used', _used,
    'limit', _monthly_limit,
    'remaining', GREATEST(_monthly_limit - _used, 0),
    'unlimited', false
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_hardening_status()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _is_admin boolean;
  _private_buckets int;
  _sensitive_realtime int;
  _pg_trgm_in_extensions boolean;
  _cleanup_job_active boolean;
BEGIN
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin'
  ) INTO _is_admin;

  IF NOT _is_admin THEN
    RAISE EXCEPTION 'Admin only';
  END IF;

  SELECT count(*) INTO _private_buckets
  FROM storage.buckets
  WHERE id IN ('personalization-images','product-videos','supplier-logos','component-media')
    AND public = false;

  SELECT count(*) INTO _sensitive_realtime
  FROM pg_publication_tables
  WHERE pubname = 'supabase_realtime'
    AND schemaname = 'public'
    AND tablename IN ('discount_approval_requests','kit_variants','kit_comments');

  SELECT EXISTS (
    SELECT 1 FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pg_trgm' AND n.nspname = 'extensions'
  ) INTO _pg_trgm_in_extensions;

  SELECT EXISTS (
    SELECT 1 FROM cron.job WHERE jobname = 'cleanup-security-logs-daily' AND active = true
  ) INTO _cleanup_job_active;

  RETURN jsonb_build_object(
    'private_buckets_count', _private_buckets,
    'private_buckets_ok', _private_buckets = 4,
    'sensitive_realtime_count', _sensitive_realtime,
    'realtime_isolation_ok', _sensitive_realtime = 0,
    'pg_trgm_in_extensions', _pg_trgm_in_extensions,
    'cleanup_job_active', _cleanup_job_active,
    'mfa_enforced_in_app', true,
    'checked_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.check_mcp_abuse_threshold(_user_id uuid, _ip text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_window INTERVAL := INTERVAL '10 minutes';
  v_threshold INTEGER := 5;
  v_count_user INTEGER := 0;
  v_count_ip INTEGER := 0;
  v_admin RECORD;
  v_already_alerted BOOLEAN := false;
BEGIN
  -- Conta violações na janela
  IF _user_id IS NOT NULL THEN
    SELECT COUNT(*) INTO v_count_user
    FROM public.mcp_access_violations
    WHERE user_id = _user_id
      AND created_at >= now() - v_window;
  END IF;

  IF _ip IS NOT NULL AND _ip <> '' THEN
    SELECT COUNT(*) INTO v_count_ip
    FROM public.mcp_access_violations
    WHERE ip_address = _ip
      AND created_at >= now() - v_window;
  END IF;

  IF v_count_user < v_threshold AND v_count_ip < v_threshold THEN
    RETURN;
  END IF;

  -- Evita disparos duplicados: se já houver alerta nos últimos 10min para mesmo user/ip, sai
  SELECT EXISTS (
    SELECT 1 FROM public.admin_audit_log
    WHERE action = 'mcp_abuse_detected'
      AND created_at >= now() - v_window
      AND (
        (details->>'user_id') = _user_id::text
        OR (details->>'ip_address') = _ip
      )
  ) INTO v_already_alerted;

  IF v_already_alerted THEN
    RETURN;
  END IF;

  -- Registra evento de auditoria
  INSERT INTO public.admin_audit_log (
    user_id, action, resource_type, resource_id,
    ip_address, details, source, status
  ) VALUES (
    COALESCE(_user_id, '00000000-0000-0000-0000-000000000000'::uuid),
    'mcp_abuse_detected',
    'mcp_api_keys',
    NULL,
    _ip,
    jsonb_build_object(
      'user_id', _user_id,
      'ip_address', _ip,
      'window_minutes', 10,
      'threshold', v_threshold,
      'violations_user', v_count_user,
      'violations_ip', v_count_ip
    ),
    'mcp_abuse_detector',
    'denied'
  );

  -- Notifica admins
  FOR v_admin IN
    SELECT user_id FROM public.user_roles WHERE role = 'admin'::public.app_role
  LOOP
    INSERT INTO public.workspace_notifications (
      user_id, title, message, type, category, action_url, metadata
    ) VALUES (
      v_admin.user_id,
      'Possível abuso em chaves MCP',
      format(
        'Detectadas %s tentativas bloqueadas em 10 min%s.',
        GREATEST(v_count_user, v_count_ip),
        CASE WHEN _ip IS NOT NULL THEN ' (IP: ' || _ip || ')' ELSE '' END
      ),
      'warning',
      'security',
      '/admin/seguranca',
      jsonb_build_object(
        'event', 'mcp_abuse_detected',
        'user_id', _user_id,
        'ip_address', _ip,
        'violations_user', v_count_user,
        'violations_ip', v_count_ip
      )
    );
  END LOOP;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_order_constraints_trigger()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    v_verba_total NUMERIC;
    v_verba_consumida NUMERIC;
    v_limite_alcada NUMERIC;
BEGIN
    -- Só validamos quando o pedido muda para um status que consome orçamento ou requer aprovação final
    IF (NEW.status IN ('confirmed', 'waiting_approval')) AND (OLD.status = 'draft' OR OLD.status = 'waiting_approval') THEN

        -- Buscar dados de orçamento do PA para o mês/ano atual
        SELECT verba_total, verba_consumida, limite_alcada 
        INTO v_verba_total, v_verba_consumida, v_limite_alcada
        FROM public.pa_budgets
        WHERE pa_id = NEW.pa_id
        AND ano = EXTRACT(YEAR FROM NEW.created_at)
        AND mes = EXTRACT(MONTH FROM NEW.created_at)
        LIMIT 1;

        -- 1. Validar existência de orçamento
        IF NOT FOUND THEN
            RAISE EXCEPTION 'Orçamento não configurado para o PA % neste período.', NEW.pa_id;
        END IF;

        -- 2. Validar se o valor total do pedido cabe no orçamento restante
        IF NEW.status = 'confirmed' AND (v_verba_consumida + NEW.total_amount) > v_verba_total THEN
            RAISE EXCEPTION 'Saldo de orçamento insuficiente. Disponível: %, Solicitado: %', 
                (v_verba_total - v_verba_consumida), NEW.total_amount;
        END IF;

        -- 3. Validar alçada: se exceder o limite e tentar confirmar sem aprovação, bloqueia
        -- (Pedidos 'confirmed' vindo de 'waiting_approval' com aprovador setado são permitidos)
        IF NEW.status = 'confirmed' AND NEW.total_amount > v_limite_alcada AND NEW.approved_by IS NULL THEN
            RAISE EXCEPTION 'Este pedido excede a alçada de % e requer aprovação formal.', v_limite_alcada;
        END IF;

        -- 4. Atualizar verba consumida automaticamente se o pedido for confirmado agora
        IF NEW.status = 'confirmed' AND OLD.status <> 'confirmed' THEN
            UPDATE public.pa_budgets
            SET verba_consumida = verba_consumida + NEW.total_amount,
                updated_at = now()
            WHERE pa_id = NEW.pa_id
            AND ano = EXTRACT(YEAR FROM NEW.created_at)
            AND mes = EXTRACT(MONTH FROM NEW.created_at);
        END IF;

    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.check_order_sla()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NEW.sla_deadline IS NOT NULL THEN
        IF NEW.sla_deadline < now() THEN
            NEW.sla_status := 'critical';
        ELSIF NEW.sla_deadline < now() + interval '2 hours' THEN
            NEW.sla_status := 'warning';
        ELSE
            NEW.sla_status := 'normal';
        END IF;
    END IF;
    RETURN NEW;
END;
$function$

