CREATE OR REPLACE FUNCTION public.check_telemetry_regression()
 RETURNS jsonb
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  current_window_start timestamptz := now() - interval '2 hours';
  baseline_window_start timestamptz := now() - interval '26 hours';
  baseline_window_end timestamptz := now() - interval '24 hours';

  cur_samples int := 0;
  cur_p95 numeric := 0;
  cur_avg numeric := 0;
  cur_errors int := 0;
  cur_very_slow int := 0;
  cur_error_rate numeric := 0;

  base_samples int := 0;
  base_p95 numeric := 0;
  base_error_rate numeric := 0;
  base_very_slow int := 0;

  p95_delta_pct numeric := 0;
  error_rate_delta_pp numeric := 0;
  very_slow_ratio numeric := 1;

  status text := 'ok';
  reasons jsonb := '[]'::jsonb;
BEGIN
  -- Apenas admins podem consultar
  IF NOT public.has_role(auth.uid(), 'admin'::app_role) THEN
    RETURN jsonb_build_object('error', 'forbidden');
  END IF;

  -- Janela atual (somente queries não-cache para medir performance real)
  SELECT
    count(*),
    COALESCE(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms), 0),
    COALESCE(AVG(duration_ms), 0),
    count(*) FILTER (WHERE severity = 'error'),
    count(*) FILTER (WHERE severity = 'very_slow')
  INTO cur_samples, cur_p95, cur_avg, cur_errors, cur_very_slow
  FROM public.query_telemetry
  WHERE created_at >= current_window_start
    AND cache_hit = false;

  cur_error_rate := CASE WHEN cur_samples > 0
    THEN ROUND(100.0 * cur_errors / cur_samples, 2)
    ELSE 0 END;

  -- Janela baseline (24-48h atrás)
  SELECT
    count(*),
    COALESCE(PERCENTILE_CONT(0.95) WITHIN GROUP (ORDER BY duration_ms), 0),
    CASE WHEN count(*) > 0
      THEN ROUND(100.0 * count(*) FILTER (WHERE severity = 'error') / count(*), 2)
      ELSE 0 END,
    count(*) FILTER (WHERE severity = 'very_slow')
  INTO base_samples, base_p95, base_error_rate, base_very_slow
  FROM public.query_telemetry
  WHERE created_at >= baseline_window_start
    AND created_at < baseline_window_end
    AND cache_hit = false;

  -- Sem amostras suficientes → status 'insufficient_data'
  IF cur_samples < 5 OR base_samples < 5 THEN
    RETURN jsonb_build_object(
      'status', 'insufficient_data',
      'reasons', jsonb_build_array(format('Amostras insuficientes (atual=%s, baseline=%s)', cur_samples, base_samples)),
      'current', jsonb_build_object('samples', cur_samples, 'p95_ms', cur_p95, 'error_rate_pct', cur_error_rate, 'very_slow', cur_very_slow),
      'baseline', jsonb_build_object('samples', base_samples, 'p95_ms', base_p95, 'error_rate_pct', base_error_rate, 'very_slow', base_very_slow),
      'checked_at', now()
    );
  END IF;

  -- Calcula deltas
  p95_delta_pct := CASE WHEN base_p95 > 0
    THEN ROUND(100.0 * (cur_p95 - base_p95) / base_p95, 1)
    ELSE 0 END;
  error_rate_delta_pp := ROUND(cur_error_rate - base_error_rate, 2);
  very_slow_ratio := CASE WHEN base_very_slow > 0
    THEN ROUND(cur_very_slow::numeric / base_very_slow, 2)
    ELSE CASE WHEN cur_very_slow > 0 THEN 999 ELSE 1 END END;

  -- Avaliação de regressão
  -- REGRESSION (crítico): qualquer um abaixo
  IF p95_delta_pct > 50 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Latência P95 piorou %s%% (atual %sms vs baseline %sms)', p95_delta_pct, ROUND(cur_p95)::int, ROUND(base_p95)::int));
  END IF;
  IF error_rate_delta_pp > 5 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Taxa de erro subiu %spp (atual %s%% vs baseline %s%%)', error_rate_delta_pp, cur_error_rate, base_error_rate));
  END IF;
  IF very_slow_ratio > 2 AND cur_very_slow >= 3 THEN
    status := 'regression';
    reasons := reasons || jsonb_build_array(format('Queries muito lentas (>8s) %sx baseline (%s vs %s)', very_slow_ratio, cur_very_slow, base_very_slow));
  END IF;

  -- WARNING (moderado) — só promove se ainda não é regression
  IF status = 'ok' THEN
    IF p95_delta_pct > 25 THEN
      status := 'warning';
      reasons := reasons || jsonb_build_array(format('Latência P95 subiu %s%% (atual %sms vs baseline %sms)', p95_delta_pct, ROUND(cur_p95)::int, ROUND(base_p95)::int));
    END IF;
    IF error_rate_delta_pp > 2 THEN
      status := 'warning';
      reasons := reasons || jsonb_build_array(format('Taxa de erro subiu %spp (atual %s%% vs baseline %s%%)', error_rate_delta_pp, cur_error_rate, base_error_rate));
    END IF;
  END IF;

  RETURN jsonb_build_object(
    'status', status,
    'reasons', reasons,
    'current', jsonb_build_object(
      'samples', cur_samples,
      'p95_ms', ROUND(cur_p95)::int,
      'avg_ms', ROUND(cur_avg)::int,
      'error_rate_pct', cur_error_rate,
      'very_slow', cur_very_slow
    ),
    'baseline', jsonb_build_object(
      'samples', base_samples,
      'p95_ms', ROUND(base_p95)::int,
      'error_rate_pct', base_error_rate,
      'very_slow', base_very_slow
    ),
    'deltas', jsonb_build_object(
      'p95_delta_pct', p95_delta_pct,
      'error_rate_delta_pp', error_rate_delta_pp,
      'very_slow_ratio', very_slow_ratio
    ),
    'checked_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.claim_next_optimization()
 RETURNS optimization_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  claimed public.optimization_queue;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  -- Bloqueia se já existe um running
  IF EXISTS (SELECT 1 FROM public.optimization_queue WHERE status = 'running') THEN
    RETURN NULL;
  END IF;

  UPDATE public.optimization_queue
     SET status = 'running', started_at = now()
   WHERE id = (
     SELECT id FROM public.optimization_queue
      WHERE status = 'pending'
      ORDER BY priority ASC, created_at ASC
      LIMIT 1
      FOR UPDATE SKIP LOCKED
   )
   RETURNING * INTO claimed;

  RETURN claimed;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_discount_test_data()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _seller_id uuid;
  _admin_id uuid;
  _quotes_deleted int := 0;
  _requests_deleted int := 0;
  _notifs_deleted int := 0;
BEGIN
  SELECT user_id INTO _seller_id FROM public.profiles WHERE email = 'seller-test@discount-approval.test' LIMIT 1;
  SELECT user_id INTO _admin_id FROM public.profiles WHERE email = 'admin-test@discount-approval.test' LIMIT 1;

  IF _seller_id IS NULL THEN
    RETURN jsonb_build_object('ok', true, 'note', 'no test seller found, nothing to clean');
  END IF;

  -- Delete approval requests for seller-test quotes
  WITH deleted AS (
    DELETE FROM public.discount_approval_requests
    WHERE seller_id = _seller_id
    RETURNING 1
  ) SELECT count(*) INTO _requests_deleted FROM deleted;

  -- Delete quotes from test seller
  WITH deleted AS (
    DELETE FROM public.quotes
    WHERE seller_id = _seller_id
    RETURNING 1
  ) SELECT count(*) INTO _quotes_deleted FROM deleted;

  -- Delete test notifications
  WITH deleted AS (
    DELETE FROM public.workspace_notifications
    WHERE user_id IN (_seller_id, _admin_id)
      AND category IN ('discount', 'quotes')
    RETURNING 1
  ) SELECT count(*) INTO _notifs_deleted FROM deleted;

  RETURN jsonb_build_object(
    'ok', true,
    'requests_deleted', _requests_deleted,
    'quotes_deleted', _quotes_deleted,
    'notifications_deleted', _notifs_deleted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_expired_collection_trash()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _deleted INTEGER;
BEGIN
  DELETE FROM public.collection_items_trash WHERE expires_at < now();
  GET DIAGNOSTICS _deleted = ROW_COUNT;
  RETURN _deleted;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_expired_favorite_trash()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _deleted INTEGER;
BEGIN
  DELETE FROM public.favorite_items_trash WHERE expires_at < now();
  GET DIAGNOSTICS _deleted = ROW_COUNT;
  RETURN _deleted;
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_security_logs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _token_failures_deleted int := 0;
  _bot_log_deleted int := 0;
  _audit_log_deleted int := 0;
  _ip_expired_deleted int := 0;
BEGIN
  WITH d AS (DELETE FROM public.public_token_failures WHERE created_at < now() - INTERVAL '90 days' RETURNING 1)
  SELECT count(*) INTO _token_failures_deleted FROM d;

  WITH d AS (DELETE FROM public.bot_detection_log WHERE created_at < now() - INTERVAL '90 days' RETURNING 1)
  SELECT count(*) INTO _bot_log_deleted FROM d;

  WITH d AS (DELETE FROM public.admin_audit_log WHERE created_at < now() - INTERVAL '365 days' RETURNING 1)
  SELECT count(*) INTO _audit_log_deleted FROM d;

  WITH d AS (
    DELETE FROM public.ip_access_control
    WHERE expires_at IS NOT NULL AND expires_at < now() - INTERVAL '30 days'
    RETURNING 1
  )
  SELECT count(*) INTO _ip_expired_deleted FROM d;

  RETURN jsonb_build_object(
    'ok', true,
    'ran_at', now(),
    'public_token_failures_deleted', _token_failures_deleted,
    'bot_detection_log_deleted', _bot_log_deleted,
    'admin_audit_log_deleted', _audit_log_deleted,
    'ip_access_control_expired_deleted', _ip_expired_deleted
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.cleanup_webhook_logs()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_deleted_outbound int;
  v_deleted_inbound int;
BEGIN
  WITH del AS (
    DELETE FROM public.webhook_deliveries
    WHERE delivered_at < now() - interval '90 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_deleted_outbound FROM del;

  WITH del AS (
    DELETE FROM public.inbound_webhook_events
    WHERE received_at < now() - interval '90 days'
    RETURNING 1
  )
  SELECT count(*) INTO v_deleted_inbound FROM del;

  RETURN jsonb_build_object(
    'ok', true,
    'deleted_outbound', v_deleted_outbound,
    'deleted_inbound', v_deleted_inbound,
    'ran_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.complete_optimization(_id uuid, _status text, _notes text DEFAULT NULL::text, _guardrail_status text DEFAULT NULL::text, _result jsonb DEFAULT NULL::jsonb, _error text DEFAULT NULL::text)
 RETURNS optimization_queue
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  updated public.optimization_queue;
  duration int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF _status NOT IN ('done','failed','skipped','blocked') THEN
    RAISE EXCEPTION 'invalid status: %', _status;
  END IF;

  UPDATE public.optimization_queue
     SET status = _status,
         finished_at = now(),
         result = COALESCE(_result, result),
         error = _error,
         guardrail_status = COALESCE(_guardrail_status, guardrail_status)
   WHERE id = _id
   RETURNING * INTO updated;

  IF updated.id IS NULL THEN
    RAISE EXCEPTION 'optimization not found';
  END IF;

  duration := EXTRACT(EPOCH FROM (updated.finished_at - COALESCE(updated.started_at, updated.finished_at))) * 1000;

  INSERT INTO public.optimization_queue_runs (queue_id, status, notes, guardrail_status, duration_ms, executed_by)
  VALUES (_id, _status, _notes, _guardrail_status, duration, auth.uid());

  RETURN updated;
END;
$function$

CREATE OR REPLACE FUNCTION public.confirm_sicoob_order(p_order_id uuid, p_expected_status text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
  v_limit numeric;
  v_policy record;
  v_initial_status text;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária.';
  END IF;

  SELECT * INTO v_order FROM public.sicoob_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Pedido não encontrado.';
  END IF;
  IF v_order.status IS DISTINCT FROM p_expected_status
     OR v_order.status NOT IN ('pending', 'waiting_approval') THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'O pedido mudou; atualize a página antes de confirmar.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sicoob_approval_requests WHERE order_id = v_order.id AND status = 'pending') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O pedido possui solicitação de aprovação pendente.';
  END IF;

  PERFORM public.assert_sicoob_approval_actor(v_actor_id, v_order.id, NULL, false);

  SELECT limite_alcada INTO v_limit
    FROM public.pa_budgets
   WHERE pa_id = v_order.pa_id
     AND ano = EXTRACT(YEAR FROM v_order.created_at)::integer
     AND mes = EXTRACT(MONTH FROM v_order.created_at)::integer;
  IF v_limit IS NULL OR v_order.total_amount > v_limit THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O pedido requer solicitação formal de aprovação.';
  END IF;

  SELECT * INTO v_policy FROM public.get_sicoob_order_approval_policy(v_order.id);
  v_initial_status := v_order.status;

  IF v_order.status = 'pending' THEN
    PERFORM set_config('app.sicoob_approval_operation', 'prepare', true);
    PERFORM set_config('app.sicoob_order_status_comment', 'Preparado para confirmação dentro da alçada.', true);
    UPDATE public.sicoob_orders
       SET status = 'waiting_approval',
           approval_policy_id = COALESCE(v_order.approval_policy_id, v_policy.policy_id),
           approval_policy_version = COALESCE(v_order.approval_policy_version, v_policy.policy_version),
           updated_at = now()
     WHERE id = v_order.id;
  END IF;

  PERFORM set_config('app.sicoob_approval_operation', 'confirm', true);
  PERFORM set_config('app.sicoob_order_status_comment', 'Confirmado dentro da alçada.', true);
  UPDATE public.sicoob_orders
     SET status = 'confirmed',
         approved_by = v_actor_id,
         approved_at = now(),
         approval_policy_id = COALESCE(v_order.approval_policy_id, v_policy.policy_id),
         approval_policy_version = COALESCE(v_order.approval_policy_version, v_policy.policy_version),
         updated_at = now()
   WHERE id = v_order.id;

  INSERT INTO public.sicoob_manager_audit (manager_id, order_id, action, details)
  VALUES (v_actor_id, v_order.id, 'confirm_within_limit', jsonb_build_object('previous_status', v_initial_status, 'policy_version', v_policy.policy_version));
END;
$function$

CREATE OR REPLACE FUNCTION public.consolidate_sicoob_quotes(p_singular_id uuid, p_quote_ids uuid[], p_notes text DEFAULT NULL::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_expected integer;
  v_locked integer;
  v_updated integer;
  v_consolidation public.quote_consolidations%ROWTYPE;
BEGIN
  v_expected := COALESCE(cardinality(ARRAY(SELECT DISTINCT unnest(p_quote_ids))), 0);
  IF v_actor IS NULL OR p_singular_id IS NULL OR v_expected = 0 OR v_expected > 500 THEN
    RAISE EXCEPTION 'Ator, Singular e de 1 a 500 orçamentos são obrigatórios.' USING ERRCODE = '22023';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE (p.user_id = v_actor OR p.id = v_actor)
      AND p.is_active IS TRUE AND p.deleted_at IS NULL
      AND EXISTS (
        SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id=v_actor
          AND ur.role::text IN ('gestor_compras','comprador_singular','admin','dev')
          AND (ur.role::text IN ('admin','dev') OR p.cooperativa_id=p_singular_id)
      )
  ) THEN
    RAISE EXCEPTION 'Usuário fora da alçada da Singular.' USING ERRCODE = '42501';
  END IF;

  PERFORM id FROM public.quotes
  WHERE id = ANY(p_quote_ids)
  ORDER BY id
  FOR UPDATE;
  GET DIAGNOSTICS v_locked = ROW_COUNT;
  IF v_locked <> v_expected OR EXISTS (
    SELECT 1 FROM public.quotes q
    WHERE q.id = ANY(p_quote_ids)
      AND (q.singular_id IS DISTINCT FROM p_singular_id
        OR q.status <> 'approved_singular'
        OR q.consolidation_id IS NOT NULL)
  ) THEN
    RAISE EXCEPTION 'Orçamentos inexistentes, fora da Singular, inelegíveis ou já consolidados.' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.quote_consolidations(consolidated_by, singular_id, status, notes)
  VALUES (v_actor, p_singular_id, 'pending', NULLIF(btrim(p_notes), ''))
  RETURNING * INTO v_consolidation;

  UPDATE public.quotes
  SET consolidation_id = v_consolidation.id, updated_at = clock_timestamp()
  WHERE id = ANY(p_quote_ids)
    AND singular_id = p_singular_id
    AND status = 'approved_singular'
    AND consolidation_id IS NULL;
  GET DIAGNOSTICS v_updated = ROW_COUNT;
  IF v_updated <> v_expected THEN
    RAISE EXCEPTION 'Concorrência detectada ao consolidar orçamentos.' USING ERRCODE = '40001';
  END IF;

  RETURN to_jsonb(v_consolidation);
END;
$function$

CREATE OR REPLACE FUNCTION public.consume_step_up_token(_token text, _expected_action step_up_action, _expected_target text DEFAULT NULL::text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid UUID := auth.uid();
  _token_h TEXT;
  _row RECORD;
BEGIN
  IF _uid IS NULL THEN RETURN false; END IF;
  IF _token IS NULL OR length(_token) < 32 THEN RETURN false; END IF;

  -- Re-checagem crítica: usuário ainda precisa ser dev no momento do consumo
  IF NOT public.is_dev(_uid) THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'unauthorized', '{"reason":"role_lost_at_consume"}'::jsonb);
    RETURN false;
  END IF;

  _token_h := encode(extensions.digest(_token, 'sha256'), 'hex');

  SELECT * INTO _row FROM public.step_up_tokens
  WHERE token_hash = _token_h AND user_id = _uid AND consumed = false AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', '{"reason":"token_invalid_or_expired"}'::jsonb);
    RETURN false;
  END IF;

  IF _row.action <> _expected_action THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', _row.id, jsonb_build_object('reason','action_mismatch','expected',_expected_action,'got',_row.action));
    RETURN false;
  END IF;

  IF _expected_target IS NOT NULL AND _row.target_ref IS DISTINCT FROM _expected_target THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id, metadata)
    VALUES (_uid, _expected_action, _expected_target, 'failed', _row.id, '{"reason":"target_mismatch"}'::jsonb);
    RETURN false;
  END IF;

  UPDATE public.step_up_tokens SET consumed = true, consumed_at = now() WHERE id = _row.id;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, token_id)
  VALUES (_uid, _expected_action, _expected_target, 'token_consumed', _row.id);

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.convert_quote_to_sicoob_order(p_quote_id uuid)
 RETURNS TABLE(id uuid, order_number text, status text, total_amount numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_quote public.quotes%ROWTYPE;
  v_order public.sicoob_orders%ROWTYPE;
  v_pa_id uuid;
  v_cooperative_id uuid;
  v_requires_artwork boolean;
  v_merchandise numeric(14,2);
  v_personalization numeric(14,2);
  v_base numeric(14,2);
  v_markup_percent numeric(5,2);
  v_markup_amount numeric(14,2);
  v_commercial_subtotal numeric(14,2);
  v_discount_amount numeric(14,2);
  v_shipping_amount numeric(14,2);
  v_expected_total numeric(14,2);
BEGIN
  IF v_actor IS NULL OR p_quote_id IS NULL THEN
    RAISE EXCEPTION 'Usuário autenticado e orçamento são obrigatórios.' USING ERRCODE = '42501';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles p
    WHERE (p.user_id=v_actor OR p.id=v_actor)
      AND p.is_active IS TRUE AND p.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION 'O perfil do usuário está inativo ou indisponível.' USING ERRCODE='42501';
  END IF;

  SELECT * INTO v_quote
  FROM public.quotes
  WHERE quotes.id = p_quote_id
  FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Orçamento não encontrado.' USING ERRCODE = 'P0002';
  END IF;

  IF v_quote.seller_id IS DISTINCT FROM v_actor AND NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_actor
      AND ur.role::text IN ('admin', 'manager', 'supervisor', 'dev')
  ) THEN
    RAISE EXCEPTION 'Usuário sem permissão para converter este orçamento.' USING ERRCODE = '42501';
  END IF;

  SELECT o.* INTO v_order
  FROM public.sicoob_orders o
  WHERE o.source_quote_id = p_quote_id;
  IF FOUND THEN
    RETURN QUERY SELECT v_order.id, v_order.order_number, v_order.status, v_order.total_amount;
    RETURN;
  END IF;

  IF v_quote.status NOT IN ('approved', 'approved_singular') THEN
    RAISE EXCEPTION 'Apenas orçamentos aprovados podem ser convertidos.' USING ERRCODE = '23514';
  END IF;
  IF v_quote.total IS NULL OR v_quote.total < 0 THEN
    RAISE EXCEPTION 'Total do orçamento inválido.' USING ERRCODE = '23514';
  END IF;
  IF NOT EXISTS (SELECT 1 FROM public.quote_items qi WHERE qi.quote_id = p_quote_id) THEN
    RAISE EXCEPTION 'O orçamento não possui itens.' USING ERRCODE = '23514';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.quote_items qi
    WHERE qi.quote_id = p_quote_id
      AND (qi.quantity <= 0 OR qi.unit_price <= 0 OR qi.product_name IS NULL OR btrim(qi.product_name) = '')
  ) THEN
    RAISE EXCEPTION 'O orçamento possui item com quantidade, nome ou preço inválido.' USING ERRCODE = '23514';
  END IF;

  SELECT COALESCE(v_quote.pa_id, p.pa_id),
         COALESCE(v_quote.singular_id, p.cooperativa_id, p.singular_id)
  INTO v_pa_id, v_cooperative_id
  FROM (SELECT 1) seed
  LEFT JOIN LATERAL (
    SELECT profile.pa_id, profile.cooperativa_id, profile.singular_id
    FROM public.profiles profile
    WHERE profile.user_id = v_quote.seller_id OR profile.id = v_quote.seller_id
    ORDER BY (profile.user_id = v_quote.seller_id) DESC NULLS LAST
    LIMIT 1
  ) p ON true;

  IF v_pa_id IS NULL OR v_cooperative_id IS NULL OR NOT EXISTS (
    SELECT 1 FROM public.postos_atendimento pa
    WHERE pa.id = v_pa_id AND pa.cooperativa_id = v_cooperative_id AND pa.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION 'Hierarquia PA/Cooperativa inválida para o orçamento.' USING ERRCODE = '23514';
  END IF;

  SELECT EXISTS (
    SELECT 1
    FROM public.quote_items qi
    JOIN public.quote_item_personalizations qip ON qip.quote_item_id = qi.id
    WHERE qi.quote_id = p_quote_id
  ) INTO v_requires_artwork;

  SELECT
    COALESCE(sum(round((qi.quantity * qi.unit_price)::numeric, 2)), 0),
    COALESCE(sum((
      SELECT COALESCE(sum(round(COALESCE(qip.total_cost, 0)::numeric, 2)), 0)
      FROM public.quote_item_personalizations qip
      WHERE qip.quote_item_id = qi.id
    )), 0)
  INTO v_merchandise, v_personalization
  FROM public.quote_items qi
  WHERE qi.quote_id = p_quote_id;

  v_base := round(v_merchandise + v_personalization, 2);
  v_markup_percent := COALESCE(v_quote.negotiation_markup_percent, 0);
  IF v_markup_percent < 0 OR v_markup_percent > 50 THEN
    RAISE EXCEPTION 'Markup do orçamento fora do intervalo permitido.' USING ERRCODE = '23514';
  END IF;
  v_markup_amount := round(v_base * v_markup_percent / 100, 2);
  v_commercial_subtotal := round(v_base + v_markup_amount, 2);

  IF COALESCE(v_quote.discount_percent, 0) < 0 OR COALESCE(v_quote.discount_percent, 0) > 100 THEN
    RAISE EXCEPTION 'Percentual de desconto do orçamento inválido.' USING ERRCODE = '23514';
  END IF;
  v_discount_amount := CASE
    WHEN COALESCE(v_quote.discount_percent, 0) > 0
      THEN round(v_commercial_subtotal * v_quote.discount_percent / 100, 2)
    ELSE round(COALESCE(v_quote.discount_amount, 0), 2)
  END;
  IF v_discount_amount < 0 OR v_discount_amount > v_commercial_subtotal THEN
    RAISE EXCEPTION 'Desconto do orçamento excede o subtotal comercial.' USING ERRCODE = '23514';
  END IF;

  v_shipping_amount := CASE
    WHEN v_quote.shipping_type IN ('fob', 'fob_pre') THEN round(COALESCE(v_quote.shipping_cost, 0), 2)
    ELSE 0
  END;
  IF v_shipping_amount < 0 THEN
    RAISE EXCEPTION 'Frete do orçamento inválido.' USING ERRCODE = '23514';
  END IF;
  v_expected_total := round(v_commercial_subtotal - v_discount_amount + v_shipping_amount, 2);

  IF abs(COALESCE(v_quote.real_subtotal, v_base) - v_base) > 0.01
     OR abs(COALESCE(v_quote.subtotal, v_commercial_subtotal) - v_commercial_subtotal) > 0.01
     OR abs(COALESCE(v_quote.discount_amount, v_discount_amount) - v_discount_amount) > 0.01
     OR abs(COALESCE(v_quote.total, v_expected_total) - v_expected_total) > 0.01 THEN
    RAISE EXCEPTION 'Totais persistidos do orçamento divergem da fórmula comercial brl-v1.' USING ERRCODE = '23514';
  END IF;

  INSERT INTO public.sicoob_orders(
    cooperative_id, pa_id, created_by, status, total_amount, notes,
    source_quote_id, source_quote_snapshot, requires_artwork,
    merchandise_amount, personalization_amount, negotiation_markup_amount,
    commercial_subtotal_amount, discount_amount, shipping_amount, pricing_formula_version
  ) VALUES (
    v_cooperative_id, v_pa_id, v_actor, 'pending', v_expected_total, v_quote.notes,
    p_quote_id,
    jsonb_build_object(
      'quote_number', v_quote.quote_number,
      'client_id', v_quote.client_id,
      'client_name', v_quote.client_name,
      'client_email', v_quote.client_email,
      'client_phone', v_quote.client_phone,
      'client_company', v_quote.client_company,
      'client_cnpj', v_quote.client_cnpj,
      'subtotal', v_quote.subtotal,
      'real_subtotal', v_quote.real_subtotal,
      'discount_percent', v_quote.discount_percent,
      'discount_amount', v_quote.discount_amount,
      'negotiation_markup_percent', v_quote.negotiation_markup_percent,
      'shipping_cost', v_quote.shipping_cost,
      'shipping_type', v_quote.shipping_type,
      'payment_terms', v_quote.payment_terms,
      'delivery_time', v_quote.delivery_time,
      'pricing_formula_version', 'brl-v1',
      'converted_at', clock_timestamp()
    ),
    v_requires_artwork,
    v_merchandise, v_personalization, v_markup_amount,
    v_commercial_subtotal, v_discount_amount, v_shipping_amount, 'brl-v1'
  ) RETURNING * INTO v_order;

  INSERT INTO public.sicoob_order_items(
    order_id, product_id, product_name, product_sku, product_image_url,
    variant_id, variant_sku, color_name, color_hex, size_code,
    personalization_snapshot, quantity, unit_price, total_price, personalization_amount
  )
  SELECT v_order.id,
    CASE WHEN qi.product_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN qi.product_id::uuid END,
    qi.product_name, qi.product_sku, qi.product_image_url,
    CASE WHEN qi.source_variant_id ~* '^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$' THEN qi.source_variant_id::uuid END,
    qi.source_variant_sku, qi.color_name, qi.color_hex, qi.size_code,
    jsonb_build_object(
      'source_quote_item_id', qi.id,
      'source_product_id', qi.product_id,
      'notes', qi.notes,
      'personalizations', COALESCE((
        SELECT jsonb_agg(to_jsonb(qip) - 'quote_item_id' ORDER BY qip.created_at, qip.id)
        FROM public.quote_item_personalizations qip
        WHERE qip.quote_item_id = qi.id
      ), '[]'::jsonb)
    ),
    qi.quantity, qi.unit_price, round((qi.quantity * qi.unit_price)::numeric, 2),
    (SELECT COALESCE(sum(round(COALESCE(qip.total_cost, 0)::numeric, 2)), 0)
     FROM public.quote_item_personalizations qip WHERE qip.quote_item_id = qi.id)
  FROM public.quote_items qi
  WHERE qi.quote_id = p_quote_id
  ORDER BY COALESCE(qi.display_order, qi.sort_order, 0), qi.id;

  INSERT INTO public.sicoob_order_history(order_id, user_id, previous_status, new_status, comment)
  VALUES (v_order.id, v_actor, NULL, 'pending', 'Pedido criado a partir de orçamento aprovado.');

  UPDATE public.quotes
  SET status = 'converted', updated_at = clock_timestamp()
  WHERE quotes.id = p_quote_id;

  RETURN QUERY SELECT v_order.id, v_order.order_number, v_order.status, v_order.total_amount;
END;
$function$

CREATE OR REPLACE FUNCTION public.copy_group_personalization_to_product(p_membership_id uuid)
 RETURNS integer
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_catalog'
AS $function$
DECLARE
  v_member record;
  v_group_component record;
  v_group_location record;
  v_group_technique record;
  v_component_id uuid;
  v_location_id uuid;
  v_copied integer := 0;
BEGIN
  IF COALESCE(auth.role(), '') <> 'service_role'
     AND (auth.uid() IS NULL OR NOT COALESCE(public.has_role(auth.uid(), 'admin'::public.app_role), false)) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Apenas administradores podem copiar regras.';
  END IF;

  SELECT id, product_id, product_group_id INTO v_member
    FROM public.product_group_members WHERE id = p_membership_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Associação de produto não encontrada.';
  END IF;
  PERFORM pg_advisory_xact_lock(hashtextextended(v_member.product_id, 0));
  IF NOT EXISTS (SELECT 1 FROM public.product_group_components
                 WHERE product_group_id = v_member.product_group_id) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Grupo sem componentes.';
  END IF;

  DELETE FROM public.product_component_location_techniques pt
  USING public.product_component_locations pl, public.product_components pc
  WHERE pt.component_location_id = pl.id AND pl.component_id = pc.id
    AND pc.product_id = v_member.product_id;
  DELETE FROM public.product_component_locations pl
  USING public.product_components pc
  WHERE pl.component_id = pc.id AND pc.product_id = v_member.product_id;
  DELETE FROM public.product_components WHERE product_id = v_member.product_id;

  FOR v_group_component IN
    SELECT * FROM public.product_group_components
    WHERE product_group_id = v_member.product_group_id ORDER BY sort_order, id
  LOOP
    INSERT INTO public.product_components
      (product_id, component_code, component_name, is_personalizable, is_active, sort_order)
    VALUES (v_member.product_id, v_group_component.component_code,
      v_group_component.component_name, v_group_component.is_personalizable,
      v_group_component.is_active, v_group_component.sort_order)
    RETURNING id INTO v_component_id;
    v_copied := v_copied + 1;

    FOR v_group_location IN
      SELECT * FROM public.product_group_locations
      WHERE group_component_id = v_group_component.id ORDER BY id
    LOOP
      INSERT INTO public.product_component_locations
        (component_id, location_code, location_name, max_width_cm,
         max_height_cm, max_area_cm2, area_image_url, is_active)
      VALUES (v_component_id, v_group_location.location_code,
        v_group_location.location_name, v_group_location.max_width_cm,
        v_group_location.max_height_cm, v_group_location.max_area_cm2,
        v_group_location.area_image_url, v_group_location.is_active)
      RETURNING id INTO v_location_id;

      FOR v_group_technique IN
        SELECT * FROM public.product_group_location_techniques
        WHERE group_location_id = v_group_location.id ORDER BY id
      LOOP
        INSERT INTO public.product_component_location_techniques
          (component_location_id, technique_id, composed_code, max_colors,
           is_default, is_active)
        VALUES (v_location_id, v_group_technique.technique_id,
          concat_ws('-', v_group_component.component_code,
            v_group_location.location_code, v_group_technique.technique_code),
          v_group_technique.max_colors, v_group_technique.is_default,
          v_group_technique.is_active);
      END LOOP;
    END LOOP;
  END LOOP;

  UPDATE public.product_group_members SET use_group_rules = false
  WHERE id = v_member.id;
  RETURN v_copied;
END; $function$

CREATE OR REPLACE FUNCTION public.create_sicoob_approval_delegation(p_delegate_id uuid, p_competencies text[], p_starts_at timestamp with time zone, p_ends_at timestamp with time zone, p_reason text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_profile public.profiles%ROWTYPE;
  v_delegate_profile public.profiles%ROWTYPE;
  v_cooperative_id uuid;
  v_pa_id uuid;
  v_id uuid;
BEGIN
  IF v_actor IS NULL OR p_delegate_id IS NULL OR p_delegate_id = v_actor THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Delegante e substituto devem ser usuários distintos.';
  END IF;
  IF p_starts_at < statement_timestamp() - interval '1 minute'
     OR p_ends_at <= p_starts_at
     OR p_ends_at > p_starts_at + interval '90 days' THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='A vigência deve começar agora ou no futuro e durar no máximo 90 dias.';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10
     OR cardinality(p_competencies) = 0
     OR NOT p_competencies <@ ARRAY['approve_order', 'reject_order']::text[] THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Informe motivo e competências delegáveis válidas.';
  END IF;

  SELECT * INTO v_actor_profile FROM public.profiles
  WHERE (user_id=v_actor OR id=v_actor) AND is_active IS TRUE AND deleted_at IS NULL;
  SELECT * INTO v_delegate_profile FROM public.profiles
  WHERE (user_id=p_delegate_id OR id=p_delegate_id) AND is_active IS TRUE AND deleted_at IS NULL;
  IF v_actor_profile.id IS NULL OR v_delegate_profile.id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Delegante e substituto precisam de vínculo ativo.';
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id=v_actor AND role::text IN ('gestor_compras', 'comprador_singular')
  ) THEN
    v_cooperative_id := v_actor_profile.cooperativa_id;
    v_pa_id := NULL;
    IF v_cooperative_id IS NULL OR v_delegate_profile.cooperativa_id IS DISTINCT FROM v_cooperative_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='O substituto deve pertencer à mesma cooperativa.';
    END IF;
  ELSIF EXISTS (
    SELECT 1 FROM public.user_roles WHERE user_id=v_actor AND role::text='gerente_pa'
  ) THEN
    v_cooperative_id := v_actor_profile.cooperativa_id;
    v_pa_id := v_actor_profile.pa_id;
    IF v_cooperative_id IS NULL OR v_pa_id IS NULL
       OR v_delegate_profile.cooperativa_id IS DISTINCT FROM v_cooperative_id
       OR v_delegate_profile.pa_id IS DISTINCT FROM v_pa_id THEN
      RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='O substituto deve pertencer ao mesmo PA.';
    END IF;
  ELSE
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='O papel atual não permite conceder delegações.';
  END IF;

  -- Serializa concessões do substituto e impede corrida de sobreposição/ciclo.
  PERFORM pg_advisory_xact_lock(hashtextextended(p_delegate_id::text, 73421));
  IF EXISTS (
    SELECT 1 FROM public.sicoob_approval_delegations delegation
    WHERE delegation.revoked_at IS NULL
      AND delegation.delegate_id = p_delegate_id
      AND delegation.cooperative_id = v_cooperative_id
      AND delegation.pa_id IS NOT DISTINCT FROM v_pa_id
      AND delegation.competencies && p_competencies
      AND tstzrange(delegation.starts_at, delegation.ends_at, '[)')
          && tstzrange(p_starts_at, p_ends_at, '[)')
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23P01', MESSAGE='Já existe delegação sobreposta para o substituto e competência.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.sicoob_approval_delegations reciprocal
    WHERE reciprocal.revoked_at IS NULL
      AND reciprocal.delegator_id = p_delegate_id
      AND reciprocal.delegate_id = v_actor
      AND tstzrange(reciprocal.starts_at, reciprocal.ends_at, '[)')
          && tstzrange(p_starts_at, p_ends_at, '[)')
  ) THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Delegação circular não é permitida.';
  END IF;

  INSERT INTO public.sicoob_approval_delegations (
    delegator_id, delegate_id, cooperative_id, pa_id,
    competencies, starts_at, ends_at, reason
  ) VALUES (
    v_actor, p_delegate_id, v_cooperative_id, v_pa_id,
    ARRAY(SELECT DISTINCT value FROM unnest(p_competencies) value ORDER BY value),
    p_starts_at, p_ends_at, btrim(p_reason)
  ) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_sicoob_kit_quote(p_kit jsonb, p_items jsonb, p_personalizations jsonb, p_idempotency_key text, p_actor_id uuid, p_request_hash text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_profile public.profiles%ROWTYPE;
  v_organization_id uuid;
  v_existing public.sicoob_kit_quote_requests%ROWTYPE;
  v_item jsonb;
  v_personalization jsonb;
  v_quote_id uuid;
  v_quote_number text;
  v_quote_item_id uuid;
  v_group_id uuid := gen_random_uuid();
  v_sort_order integer := 0;
  v_product_total numeric(14,2) := 0;
  v_personalization_total numeric(14,2) := 0;
  v_total numeric(14,2);
  v_checked_at timestamptz;
  v_payload_hash text;
  v_kit_name text := NULLIF(trim(p_kit ->> 'name'), '');
  v_kit_type text := NULLIF(trim(p_kit ->> 'type'), '');
  v_kit_quantity integer;
  v_identity_tag text := NULLIF(trim(p_kit ->> 'identity_tag'), '');
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária para criar o orçamento.';
  END IF;
  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) NOT BETWEEN 8 AND 128 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Chave de idempotência inválida.';
  END IF;
  IF COALESCE(p_request_hash, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Identidade da requisição de kit inválida.';
  END IF;
  IF jsonb_typeof(p_kit) IS DISTINCT FROM 'object'
     OR v_kit_name IS NULL OR length(v_kit_name) > 120
     OR v_kit_type NOT IN ('montado', 'original', 'simples')
     OR COALESCE(length(v_identity_tag), 0) > 60 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Identificação do kit inválida.';
  END IF;

  BEGIN
    v_kit_quantity := (p_kit ->> 'quantity')::integer;
  EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Quantidade de kits inválida.';
  END;
  IF v_kit_quantity IS NULL OR v_kit_quantity NOT BETWEEN 1 AND 100000 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A quantidade de kits deve estar entre 1 e 100.000.';
  END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) NOT BETWEEN 2 AND 50
     OR jsonb_typeof(p_personalizations) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_personalizations) > jsonb_array_length(p_items) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Composição do kit inválida.';
  END IF;
  IF (SELECT count(*) FROM jsonb_array_elements(p_items) source(item) WHERE item ->> 'kind' = 'box') <> 1
     OR jsonb_array_length(p_items) <> (
       SELECT count(DISTINCT item ->> 'line_id')::integer FROM jsonb_array_elements(p_items) source(item)
     )
     OR jsonb_array_length(p_personalizations) <> (
       SELECT count(DISTINCT item ->> 'line_id')::integer FROM jsonb_array_elements(p_personalizations) source(item)
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Linhas de kit duplicadas ou embalagem inválida.';
  END IF;

  SELECT * INTO v_profile
    FROM public.profiles
   WHERE user_id = p_actor_id
     AND is_active IS TRUE
     AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O usuário não possui perfil ativo.';
  END IF;

  SELECT om.organization_id INTO v_organization_id
    FROM public.organization_members om
   WHERE om.user_id = p_actor_id
   ORDER BY om.created_at ASC, om.id ASC
   LIMIT 1;

  v_payload_hash := p_request_hash;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_actor_id::text || ':' || trim(p_idempotency_key), 0));
  SELECT * INTO v_existing
    FROM public.sicoob_kit_quote_requests
   WHERE actor_id = p_actor_id
     AND idempotency_key = trim(p_idempotency_key);
  IF FOUND THEN
    IF v_existing.payload_hash IS DISTINCT FROM v_payload_hash THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com conteúdo diferente.';
    END IF;
    SELECT quote_number, total INTO v_quote_number, v_total
      FROM public.quotes WHERE id = v_existing.quote_id;
    RETURN jsonb_build_object('quote_id', v_existing.quote_id, 'quote_number', v_quote_number, 'total', v_total);
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    IF COALESCE(length(v_item ->> 'line_id'), 0) NOT BETWEEN 1 AND 64
       OR v_item ->> 'kind' NOT IN ('box', 'item')
       OR NULLIF(v_item ->> 'product_id', '') IS NULL
       OR NULLIF(trim(v_item ->> 'product_name'), '') IS NULL
       OR COALESCE((v_item ->> 'quantity')::integer, 0) <= 0
       OR COALESCE((v_item ->> 'unit_price')::numeric, 0) <= 0
       OR COALESCE((v_item ->> 'minimum_quantity')::integer, 1) <= 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Item verificado do kit inválido.';
    END IF;

    v_checked_at := NULLIF(v_item ->> 'catalog_checked_at', '')::timestamptz;
    IF v_checked_at IS NULL
       OR v_checked_at < now() - interval '5 minutes'
       OR v_checked_at > now() + interval '1 minute' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Preço e estoque precisam ser consultados novamente.';
    END IF;
    v_product_total := v_product_total
      + ((v_item ->> 'quantity')::integer * (v_item ->> 'unit_price')::numeric);
  END LOOP;

  -- MOQ é uma regra do produto, portanto duas linhas/variantes do mesmo produto
  -- devem ser avaliadas pela demanda total. Também recusamos snapshots que
  -- atribuam mínimos divergentes ao mesmo produto.
  IF EXISTS (
    SELECT 1
      FROM (
        SELECT item ->> 'product_id' AS product_id,
               sum((item ->> 'quantity')::integer) AS total_quantity,
               min(COALESCE((item ->> 'minimum_quantity')::integer, 1)) AS minimum_quantity,
               max(COALESCE((item ->> 'minimum_quantity')::integer, 1)) AS maximum_quantity
          FROM jsonb_array_elements(p_items) source(item)
         GROUP BY item ->> 'product_id'
      ) demand
     WHERE demand.minimum_quantity IS DISTINCT FROM demand.maximum_quantity
        OR demand.total_quantity < demand.minimum_quantity
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Quantidade abaixo do mínimo vigente do produto.';
  END IF;

  FOR v_personalization IN SELECT value FROM jsonb_array_elements(p_personalizations)
  LOOP
    IF NOT EXISTS (
         SELECT 1 FROM jsonb_array_elements(p_items) source(item)
          WHERE item ->> 'line_id' = v_personalization ->> 'line_id'
       )
       OR NULLIF(v_personalization ->> 'technique_id', '') IS NULL
       OR NULLIF(trim(v_personalization ->> 'technique_name'), '') IS NULL
       OR COALESCE((v_personalization ->> 'colors_count')::integer, 0) <= 0
       OR COALESCE((v_personalization ->> 'personalized_quantity')::integer, 0) <= 0
       OR COALESCE((v_personalization ->> 'unit_cost')::numeric, 0) <= 0
       OR COALESCE((v_personalization ->> 'setup_cost')::numeric, 0) < 0
       OR COALESCE((v_personalization ->> 'total_cost')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Personalização verificada do kit inválida.';
    END IF;
    IF (v_personalization ->> 'personalized_quantity')::integer IS DISTINCT FROM (
         SELECT (item ->> 'quantity')::integer
           FROM jsonb_array_elements(p_items) source(item)
          WHERE item ->> 'line_id' = v_personalization ->> 'line_id'
       ) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A personalização não corresponde à quantidade do item.';
    END IF;

    v_checked_at := NULLIF(v_personalization ->> 'catalog_checked_at', '')::timestamptz;
    IF v_checked_at IS NULL
       OR v_checked_at < now() - interval '5 minutes'
       OR v_checked_at > now() + interval '1 minute' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O preço da personalização precisa ser consultado novamente.';
    END IF;
    v_personalization_total := v_personalization_total + (v_personalization ->> 'total_cost')::numeric;
  END LOOP;

  v_total := round(v_product_total + v_personalization_total, 2);
  INSERT INTO public.quotes (
    client_id, client_name, seller_id, status, subtotal, total, notes,
    internal_notes, organization_id, pa_id, singular_id
  ) VALUES (
    NULL,
    'Unidade Sicoob',
    p_actor_id,
    'draft',
    v_total,
    v_total,
    format('Kit "%s" (%sx) — tipo: %s. Catálogo consultado na criação; estoque não reservado.',
      v_kit_name, v_kit_quantity, v_kit_type),
    CASE WHEN v_identity_tag IS NOT NULL THEN format('Identidade do kit: %s', v_identity_tag) ELSE NULL END,
    v_organization_id,
    v_profile.pa_id,
    v_profile.cooperativa_id
  ) RETURNING id, quote_number INTO v_quote_id, v_quote_number;

  FOR v_item IN
    SELECT value
      FROM jsonb_array_elements(p_items)
     ORDER BY CASE WHEN value ->> 'kind' = 'box' THEN 0 ELSE 1 END, value ->> 'line_id'
  LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, color_name, color_hex, size_code, notes, sort_order,
      kit_group_id, kit_name, source_variant_id, source_variant_sku, catalog_checked_at
    ) VALUES (
      v_quote_id,
      v_item ->> 'product_id',
      v_item ->> 'product_name',
      NULLIF(v_item ->> 'product_sku', ''),
      NULLIF(v_item ->> 'product_image_url', ''),
      (v_item ->> 'quantity')::integer,
      (v_item ->> 'unit_price')::numeric,
      NULLIF(v_item ->> 'color_name', ''),
      NULLIF(v_item ->> 'color_hex', ''),
      NULLIF(v_item ->> 'size_code', ''),
      CASE WHEN v_item ->> 'kind' = 'box' THEN 'Embalagem do kit' ELSE NULL END,
      v_sort_order,
      v_group_id::text,
      v_kit_name,
      NULLIF(v_item ->> 'source_variant_id', ''),
      NULLIF(v_item ->> 'source_variant_sku', ''),
      (v_item ->> 'catalog_checked_at')::timestamptz
    ) RETURNING id INTO v_quote_item_id;

    SELECT value INTO v_personalization
      FROM jsonb_array_elements(p_personalizations)
     WHERE value ->> 'line_id' = v_item ->> 'line_id';
    IF FOUND THEN
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name, colors_count,
        width_cm, height_cm, personalized_quantity, unit_cost,
        setup_cost, total_cost, notes, catalog_checked_at
      ) VALUES (
        v_quote_item_id,
        v_personalization ->> 'technique_id',
        v_personalization ->> 'technique_name',
        (v_personalization ->> 'colors_count')::integer,
        NULLIF(v_personalization ->> 'width_cm', '')::numeric,
        NULLIF(v_personalization ->> 'height_cm', '')::numeric,
        (v_personalization ->> 'personalized_quantity')::integer,
        (v_personalization ->> 'unit_cost')::numeric,
        (v_personalization ->> 'setup_cost')::numeric,
        (v_personalization ->> 'total_cost')::numeric,
        CASE WHEN NULLIF(v_personalization ->> 'position', '') IS NOT NULL
          THEN format('Posição: %s', v_personalization ->> 'position') ELSE NULL END,
        (v_personalization ->> 'catalog_checked_at')::timestamptz
      );
    END IF;
    v_sort_order := v_sort_order + 1;
  END LOOP;

  INSERT INTO public.sicoob_kit_quote_requests (
    actor_id, idempotency_key, payload_hash, quote_id
  ) VALUES (
    p_actor_id, trim(p_idempotency_key), v_payload_hash, v_quote_id
  );

  RETURN jsonb_build_object('quote_id', v_quote_id, 'quote_number', v_quote_number, 'total', v_total);
END;
$function$

CREATE OR REPLACE FUNCTION public.create_sicoob_order_artwork_version(p_actor_id uuid, p_order_id uuid, p_file_path text, p_file_sha256 text, p_identity_snapshot jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_artwork_id uuid;
  v_existing public.sicoob_order_artwork_versions%ROWTYPE;
  v_version integer;
  v_order_status text;
BEGIN
  IF auth.jwt() ->> 'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O registro da arte exige o verificador interno.';
  END IF;
  IF p_actor_id IS NULL OR NOT public.sicoob_actor_can_manage_fulfillment(p_actor_id, p_order_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode enviar arte para este pedido.';
  END IF;
  IF p_file_path NOT LIKE p_order_id::text || '/artwork/%'
     OR p_file_sha256 !~ '^[0-9a-f]{64}$'
     OR jsonb_typeof(p_identity_snapshot) IS DISTINCT FROM 'object'
     OR p_identity_snapshot ->> 'bucket' IS DISTINCT FROM 'sicoob-order-documents'
     OR p_identity_snapshot ->> 'path' IS DISTINCT FROM p_file_path
     OR p_identity_snapshot ->> 'sha256' IS DISTINCT FROM p_file_sha256
     OR p_identity_snapshot ->> 'verifier' IS DISTINCT FROM 'sicoob-artwork-register'
     OR COALESCE(p_identity_snapshot ->> 'byte_size', '') !~ '^[1-9][0-9]*$'
     OR COALESCE(p_identity_snapshot ->> 'verified_at', '') = '' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Arquivo, hash ou fotografia de identidade inválidos.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_order_id::text || ':artwork', 0));
  SELECT * INTO v_existing
    FROM public.sicoob_order_artwork_versions
   WHERE order_id = p_order_id AND file_path = p_file_path
   FOR UPDATE;
  IF FOUND THEN
    IF v_existing.file_sha256 IS DISTINCT FROM p_file_sha256
       OR v_existing.created_by IS DISTINCT FROM p_actor_id THEN
      RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'O caminho da arte já foi registrado com outra identidade.';
    END IF;
    RETURN v_existing.id;
  END IF;

  SELECT status INTO v_order_status FROM public.sicoob_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Pedido não encontrado.'; END IF;
  IF v_order_status NOT IN ('draft', 'pending', 'waiting_approval', 'escalated_to_board', 'confirmed') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A arte não pode ser substituída após o início da produção ou logística.';
  END IF;
  SELECT COALESCE(max(version), 0) + 1 INTO v_version
    FROM public.sicoob_order_artwork_versions WHERE order_id = p_order_id;
  PERFORM set_config('app.sicoob_artwork_operation', 'version', true);
  UPDATE public.sicoob_order_artwork_versions SET is_latest = false
   WHERE order_id = p_order_id AND is_latest;

  INSERT INTO public.sicoob_order_artwork_versions (
    order_id, version, file_path, file_sha256, identity_snapshot, created_by
  ) VALUES (
    p_order_id, v_version, p_file_path, p_file_sha256, p_identity_snapshot, p_actor_id
  ) RETURNING id INTO v_artwork_id;
  RETURN v_artwork_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.create_sicoob_order_consolidation(p_order_ids uuid[], p_seller_id uuid, p_idempotency_key uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_consolidation_id uuid;
  v_existing_group public.order_consolidations%ROWTYPE;
  v_cooperative_id uuid;
  v_count integer;
  v_total numeric;
BEGIN
  IF v_actor_id IS NULL
     OR p_idempotency_key IS NULL
     OR p_seller_id IS NULL
     OR p_order_ids IS NULL
     OR cardinality(p_order_ids) = 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Pedidos, vendedor e chave de idempotência são obrigatórios.';
  END IF;
  IF cardinality(p_order_ids) <> (SELECT count(DISTINCT id) FROM unnest(p_order_ids) id) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A lista de pedidos contém duplicidades ou valor nulo.';
  END IF;

  -- Serializa a intenção antes de consultar a chave. Assim, uma repetição que
  -- chegou enquanto a primeira transação ainda gravava o lote relê o resultado
  -- confirmado, em vez de falhar por pedido já vinculado ou índice único.
  PERFORM pg_advisory_xact_lock(
    hashtextextended('sicoob-order-consolidation:' || p_idempotency_key::text, 0)
  );

  SELECT * INTO v_existing_group
    FROM public.order_consolidations WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_group.consolidated_by IS DISTINCT FROM v_actor_id
       OR v_existing_group.vendedor_id IS DISTINCT FROM p_seller_id
       OR (SELECT count(*) FROM public.order_consolidation_orders co
            WHERE co.consolidation_id = v_existing_group.id) <> cardinality(p_order_ids)
       OR EXISTS (
         SELECT 1 FROM public.order_consolidation_orders co
          WHERE co.consolidation_id = v_existing_group.id
            AND NOT (co.order_id = ANY(p_order_ids))
       ) THEN
      RAISE EXCEPTION USING
        ERRCODE = '22023',
        MESSAGE = 'A chave de idempotência já foi usada por outro usuário ou conteúdo.';
    END IF;
    RETURN v_existing_group.id;
  END IF;

  PERFORM 1 FROM public.sicoob_orders WHERE id = ANY(p_order_ids) FOR UPDATE;
  SELECT cooperative_id INTO v_cooperative_id
    FROM public.sicoob_orders
   WHERE id = ANY(p_order_ids)
   LIMIT 1;
  SELECT count(*), sum(total_amount)
    INTO v_count, v_total
    FROM public.sicoob_orders
   WHERE id = ANY(p_order_ids)
     AND cooperative_id IS NOT NULL
     AND pa_id IS NOT NULL
     AND total_amount IS NOT NULL
     AND total_amount >= 0
     AND status = 'confirmed'
     AND consolidation_id IS NULL;
  IF v_count <> cardinality(p_order_ids)
     OR EXISTS (
       SELECT 1 FROM public.sicoob_orders
        WHERE id = ANY(p_order_ids) AND cooperative_id IS DISTINCT FROM v_cooperative_id
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Pedidos precisam estar confirmados, livres, com total válido e na mesma Singular.';
  END IF;
  IF NOT public.sicoob_actor_can_manage_consolidation(v_actor_id, v_cooperative_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário fora do escopo da consolidação.';
  END IF;
  IF NOT EXISTS (
    SELECT 1
    FROM public.profiles p
    WHERE (p.user_id = p_seller_id OR p.id = p_seller_id)
      AND p.cooperativa_id = v_cooperative_id
      AND p.is_active IS TRUE
      AND p.deleted_at IS NULL
      AND EXISTS (
        SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id = p_seller_id AND ur.role::text = 'vendedor'
      )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'Vendedor informado não possui vínculo ativo nesta Singular.';
  END IF;

  PERFORM set_config('app.sicoob_consolidation_operation', 'create', true);
  INSERT INTO public.order_consolidations (
    singular_id, vendedor_id, status, total_value, order_count, consolidated_by, idempotency_key
  ) VALUES (
    v_cooperative_id, p_seller_id, 'pending_seller', v_total, v_count, v_actor_id, p_idempotency_key
  ) RETURNING id INTO v_consolidation_id;

  INSERT INTO public.order_consolidation_orders (consolidation_id, order_id, order_total_snapshot)
  SELECT v_consolidation_id, id, total_amount
    FROM public.sicoob_orders WHERE id = ANY(p_order_ids);
  UPDATE public.sicoob_orders SET consolidation_id = v_consolidation_id
   WHERE id = ANY(p_order_ids);
  PERFORM public.allocate_sicoob_consolidation_by_order_pa(v_consolidation_id);
  RETURN v_consolidation_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.decide_sicoob_order_artwork(p_artwork_id uuid, p_status text, p_feedback text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_artwork public.sicoob_order_artwork_versions%ROWTYPE;
BEGIN
  IF p_status NOT IN ('approved', 'rejected', 'revision') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Decisão de arte inválida.';
  END IF;
  IF p_status <> 'approved' AND length(trim(COALESCE(p_feedback, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe um feedback com ao menos 10 caracteres.';
  END IF;

  SELECT * INTO v_artwork FROM public.sicoob_order_artwork_versions
   WHERE id = p_artwork_id FOR UPDATE;
  IF NOT FOUND OR NOT v_artwork.is_latest OR v_artwork.status <> 'pending' THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'A versão de arte mudou; atualize a página.';
  END IF;
  PERFORM public.assert_sicoob_approval_actor(v_actor_id, v_artwork.order_id, v_artwork.created_by, false);

  PERFORM set_config('app.sicoob_artwork_operation', 'decide', true);
  UPDATE public.sicoob_order_artwork_versions
     SET status = p_status,
         feedback = NULLIF(trim(p_feedback), ''),
         decided_by = v_actor_id,
         decided_at = now()
   WHERE id = v_artwork.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.determine_sicoob_order_flow_status()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
    v_coop_threshold DECIMAL(12,2);
    v_pa_budget_available DECIMAL(12,2);
BEGIN
    -- Se o status for alterado para 'pending', avaliar o próximo passo
    IF NEW.status = 'pending' THEN
        -- Buscar limite da cooperativa
        SELECT alcada_superior_threshold INTO v_coop_threshold 
        FROM public.cooperativas 
        WHERE id = NEW.cooperative_id;

        -- Se o valor exceder o threshold da cooperativa, vai para a diretoria
        IF NEW.total_amount > v_coop_threshold THEN
            NEW.status := 'escalated_to_board';
        ELSE
            NEW.status := 'waiting_approval';
        END IF;
    END IF;

    -- Atualizar SLA inicial (48h úteis como padrão para análise)
    IF NEW.status IN ('waiting_approval', 'escalated_to_board') AND (OLD.status IS NULL OR OLD.status != NEW.status) THEN
        NEW.sla_deadline := now() + interval '48 hours';
        NEW.sla_status := 'normal';
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_quote_webhook_event()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'extensions', 'pg_temp'
AS $function$
DECLARE
  v_event text;
  v_payload jsonb;
  v_project_url text := 'https://cfmzkthhgliqelozlmwu.supabase.co';
BEGIN
  IF TG_TABLE_NAME = 'quotes' THEN
    IF TG_OP = 'INSERT' THEN
      v_event := 'quote.created';
    ELSIF TG_OP = 'UPDATE' AND OLD.status IS DISTINCT FROM NEW.status THEN
      v_event := 'quote.' || NEW.status;
    ELSE
      RETURN NEW;
    END IF;
    v_payload := jsonb_build_object(
      'id', NEW.id,
      'quote_number', NEW.quote_number,
      'status', NEW.status,
      'client_name', NEW.client_name,
      'client_email', NEW.client_email,
      'total', NEW.total,
      'seller_id', NEW.seller_id,
      'updated_at', NEW.updated_at
    );

  ELSIF TG_TABLE_NAME = 'orders' THEN
    -- A duplicação só se torna um pedido operacional depois de sair do
    -- rascunho. Não publique order.created antes de itens e auditoria existirem.
    IF NEW.status = 'rascunho' AND NEW.order_number LIKE 'RE-%' THEN
      RETURN NEW;
    END IF;
    IF TG_OP = 'INSERT' THEN
      v_event := 'order.created';
    ELSE
      RETURN NEW;
    END IF;
    v_payload := jsonb_build_object(
      'id', NEW.id,
      'order_number', NEW.order_number,
      'status', NEW.status,
      'client_name', NEW.client_name,
      'total', NEW.total,
      'seller_id', NEW.seller_id
    );

  ELSIF TG_TABLE_NAME = 'discount_approval_requests' THEN
    IF TG_OP = 'INSERT' THEN
      v_event := 'discount.requested';
    ELSIF TG_OP = 'UPDATE'
          AND OLD.status IS DISTINCT FROM NEW.status
          AND NEW.status IN ('approved', 'rejected') THEN
      v_event := 'discount.' || NEW.status;
    ELSE
      RETURN NEW;
    END IF;
    v_payload := jsonb_build_object(
      'id', NEW.id,
      'quote_id', NEW.quote_id,
      'requested_discount_percent', NEW.requested_discount_percent,
      'status', NEW.status,
      'seller_id', NEW.seller_id
    );

  ELSIF TG_TABLE_NAME = 'kit_share_tokens' THEN
    IF TG_OP = 'INSERT' THEN
      v_event := 'kit.shared';
    ELSE
      RETURN NEW;
    END IF;
    v_payload := jsonb_build_object(
      'id', NEW.id,
      'kit_id', NEW.kit_id,
      'token', NEW.token,
      'client_name', NEW.client_name,
      'seller_id', NEW.seller_id
    );

  ELSE
    RETURN NEW;
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.outbound_webhooks
     WHERE active = true AND v_event = ANY(events)
  ) THEN
    RETURN NEW;
  END IF;

  PERFORM extensions.http_post(
    url := v_project_url || '/functions/v1/webhook-dispatcher',
    body := jsonb_build_object('event', v_event, 'payload', v_payload)::text,
    params := '{}'::jsonb,
    headers := jsonb_build_object('Content-Type', 'application/json'),
    timeout_milliseconds := 5000
  );

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  -- Integração externa nunca invalida a transação comercial.
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.dispatch_sicoob_approval_worker()
 RETURNS bigint
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'vault', 'net'
AS $function$
DECLARE v_project_url text; v_worker_secret text; v_request_id bigint;
BEGIN
  SELECT decrypted_secret INTO v_project_url FROM vault.decrypted_secrets
  WHERE name='sicoob_project_url' ORDER BY updated_at DESC LIMIT 1;
  SELECT decrypted_secret INTO v_worker_secret FROM vault.decrypted_secrets
  WHERE name='sicoob_approval_worker_secret' ORDER BY updated_at DESC LIMIT 1;
  v_project_url:=rtrim(COALESCE(v_project_url,''),'/');
  IF v_project_url !~ '^https://[a-z0-9-]+[.]supabase[.]co$'
     OR length(COALESCE(v_worker_secret,'')) NOT BETWEEN 32 AND 512 THEN
    RAISE WARNING 'Worker de aprovações não configurado no Vault';
    RETURN NULL;
  END IF;
  SELECT net.http_post(
    url:=v_project_url||'/functions/v1/sicoob-approval-notifications',
    headers:=jsonb_build_object('Content-Type','application/json','Authorization','Bearer '||v_worker_secret),
    body:='{"action":"process_queue"}'::jsonb,timeout_milliseconds:=40000
  ) INTO v_request_id;
  INSERT INTO public.sicoob_approval_worker_dispatches(request_id) VALUES(v_request_id);
  RETURN v_request_id;
END;
$function$

