CREATE OR REPLACE FUNCTION public.is_dnd_active()
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  dnd_enabled BOOLEAN;
  dnd_start TIME;
  dnd_end TIME;
  current_t TIME;
BEGIN
  SELECT 
    COALESCE((preferences->>'dnd_enabled')::boolean, false),
    (preferences->>'dnd_start')::time,
    (preferences->>'dnd_end')::time
  INTO dnd_enabled, dnd_start, dnd_end
  FROM public.profiles
  WHERE user_id = auth.uid();

  IF NOT dnd_enabled OR dnd_start IS NULL OR dnd_end IS NULL THEN
    RETURN FALSE;
  END IF;

  current_t := LOCALTIME;

  IF dnd_start <= dnd_end THEN
    RETURN current_t BETWEEN dnd_start AND dnd_end;
  ELSE
    RETURN current_t >= dnd_start OR current_t <= dnd_end;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.is_singular_buyer_for_quote(user_id uuid, quote_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    user_singular_id UUID;
    quote_singular_id UUID;
    user_role public.app_role;
BEGIN
    -- Get user singular_id and role
    SELECT cooperativa_id, role::public.app_role INTO user_singular_id, user_role 
    FROM public.profiles 
    WHERE profiles.user_id = $1;

    -- Get quote singular_id
    SELECT singular_id INTO quote_singular_id 
    FROM public.quotes 
    WHERE id = $2;

    RETURN (user_role = 'comprador_singular' OR user_role = 'admin') AND user_singular_id = quote_singular_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.issue_sicoob_invitation(p_email text, p_cooperative_id uuid, p_pa_id uuid, p_role app_role, p_expires_in_hours integer, p_idempotency_key uuid)
 RETURNS TABLE(invitation_id uuid, invitation_token text, invitation_expires_at timestamp with time zone, reused boolean)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_email text := lower(trim(p_email));
  v_token text;
  v_invitation public.sicoob_invitations%ROWTYPE;
  v_superseded_id uuid;
BEGIN
  IF v_actor_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ator e chave de idempotência são obrigatórios.';
  END IF;
  IF v_email IS NULL OR v_email !~ '^[^@[:space:]]+@[^@[:space:]]+$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe um email institucional válido.';
  END IF;
  IF p_expires_in_hours IS NULL OR p_expires_in_hours < 1 OR p_expires_in_hours > 168 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A validade deve ficar entre 1 e 168 horas.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.cooperativas c
     WHERE c.id = p_cooperative_id AND c.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'A cooperativa informada não está ativa.';
  END IF;
  IF p_role IN ('gerente_pa'::public.app_role, 'comprador_pac'::public.app_role) AND p_pa_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O papel informado exige um PA.';
  END IF;
  IF p_role IN (
    'gestor_compras'::public.app_role,
    'comprador_singular'::public.app_role,
    'supervisor'::public.app_role,
    'manager'::public.app_role
  ) AND p_pa_id IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O papel informado pertence à Singular e não aceita PA.';
  END IF;
  IF p_pa_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.postos_atendimento pa
     WHERE pa.id = p_pa_id
       AND pa.cooperativa_id = p_cooperative_id
       AND pa.is_active IS TRUE
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'O PA não pertence à cooperativa ou está inativo.';
  END IF;
  IF NOT public.sicoob_inviter_can_issue(v_actor_id, p_cooperative_id, p_role) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode conceder este papel neste escopo.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'sicoob-invitation-idempotency:' || v_actor_id::text || ':' || p_idempotency_key::text, 0
  ));
  SELECT * INTO v_invitation
    FROM public.sicoob_invitations i
   WHERE i.invited_by = v_actor_id
     AND i.idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_invitation.email IS DISTINCT FROM v_email
       OR v_invitation.cooperative_id IS DISTINCT FROM p_cooperative_id
       OR v_invitation.pa_id IS DISTINCT FROM p_pa_id
       OR v_invitation.role IS DISTINCT FROM p_role THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com outro conteúdo.';
    END IF;
    RETURN QUERY SELECT v_invitation.id, NULL::text, v_invitation.expires_at, true;
    RETURN;
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    'sicoob-invitation-scope:' || v_email || ':' || p_cooperative_id::text || ':'
      || COALESCE(p_pa_id::text, '-') || ':' || p_role::text, 0
  ));

  IF EXISTS (
    SELECT 1
      FROM auth.users u
      JOIN public.profiles p ON p.user_id = u.id
     WHERE lower(u.email) = v_email
       AND p.is_active IS TRUE
       AND p.deleted_at IS NULL
       AND (
         (p.cooperativa_id IS NOT NULL AND p.cooperativa_id IS DISTINCT FROM p_cooperative_id)
         OR (p.pa_id IS NOT NULL AND p.pa_id IS DISTINCT FROM p_pa_id)
       )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O usuário já possui vínculo ativo em outro escopo.';
  END IF;
  IF EXISTS (
    SELECT 1
      FROM auth.users u
      JOIN public.profiles p ON p.user_id = u.id
      JOIN public.user_roles ur ON ur.user_id = u.id AND ur.role = p_role
     WHERE lower(u.email) = v_email
       AND p.cooperativa_id = p_cooperative_id
       AND p.pa_id IS NOT DISTINCT FROM p_pa_id
       AND p.is_active IS TRUE
       AND p.deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23505', MESSAGE = 'O usuário já possui este vínculo e papel.';
  END IF;

  FOR v_superseded_id IN
    UPDATE public.sicoob_invitations i
       SET status = 'superseded', updated_at = now()
     WHERE i.email = v_email
       AND i.cooperative_id = p_cooperative_id
       AND i.pa_id IS NOT DISTINCT FROM p_pa_id
       AND i.role = p_role
       AND i.status = 'pending'
    RETURNING i.id
  LOOP
    INSERT INTO public.sicoob_invitation_events (
      invitation_id, cooperative_id, action, actor_id, details
    ) VALUES (
      v_superseded_id, p_cooperative_id, 'superseded', v_actor_id,
      jsonb_build_object('reason', 'reissued')
    );
  END LOOP;

  v_token := encode(extensions.gen_random_bytes(32), 'hex');
  INSERT INTO public.sicoob_invitations (
    token_hash, email, cooperative_id, pa_id, role, expires_at, invited_by, idempotency_key
  ) VALUES (
    extensions.digest(v_token, 'sha256'), v_email, p_cooperative_id, p_pa_id, p_role,
    now() + make_interval(hours => p_expires_in_hours), v_actor_id, p_idempotency_key
  ) RETURNING * INTO v_invitation;

  UPDATE public.sicoob_invitations
     SET superseded_by = v_invitation.id
   WHERE id = v_superseded_id;

  INSERT INTO public.sicoob_invitation_events (
    invitation_id, cooperative_id, action, actor_id,
    details
  ) VALUES (
    v_invitation.id, p_cooperative_id, 'issued', v_actor_id,
    jsonb_build_object('role', p_role::text, 'pa_id', p_pa_id, 'expires_at', v_invitation.expires_at)
  );

  RETURN QUERY SELECT v_invitation.id, v_token, v_invitation.expires_at, false;
END;
$function$

CREATE OR REPLACE FUNCTION public.list_sicoob_approval_delegate_candidates()
 RETURNS TABLE(user_id uuid, full_name text, email text, cooperativa_id uuid, pa_id uuid)
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_profile public.profiles%ROWTYPE;
  v_cooperative_scope boolean;
  v_pa_scope boolean;
BEGIN
  SELECT * INTO v_profile FROM public.profiles
  WHERE (profiles.user_id=v_actor OR profiles.id=v_actor)
    AND profiles.is_active IS TRUE AND profiles.deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Vínculo ativo obrigatório.';
  END IF;

  SELECT
    EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_roles.user_id=v_actor
        AND role::text IN ('gestor_compras', 'comprador_singular')
    ),
    EXISTS (
      SELECT 1 FROM public.user_roles
      WHERE user_roles.user_id=v_actor AND role::text='gerente_pa'
    )
  INTO v_cooperative_scope, v_pa_scope;
  IF NOT v_cooperative_scope AND NOT v_pa_scope THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Ator sem autoridade para conceder delegações.';
  END IF;

  RETURN QUERY
  SELECT candidate.user_id, candidate.full_name, candidate.email,
         candidate.cooperativa_id, candidate.pa_id
  FROM public.profiles candidate
  WHERE candidate.user_id<>v_actor
    AND candidate.is_active IS TRUE
    AND candidate.deleted_at IS NULL
    AND candidate.cooperativa_id=v_profile.cooperativa_id
    AND (v_cooperative_scope OR candidate.pa_id=v_profile.pa_id)
    AND EXISTS (
      SELECT 1 FROM public.user_roles candidate_role
      WHERE candidate_role.user_id=candidate.user_id
        AND candidate_role.role::text='comprador_pac'
    )
  ORDER BY candidate.full_name NULLS LAST, candidate.email NULLS LAST, candidate.user_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_admin_action()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    audit_action TEXT;
BEGIN
    IF (TG_OP = 'INSERT') THEN audit_action := 'CREATE';
    ELSIF (TG_OP = 'UPDATE') THEN audit_action := 'UPDATE';
    ELSIF (TG_OP = 'DELETE') THEN audit_action := 'DELETE';
    END IF;

    INSERT INTO public.admin_audit_log (user_id, action, entity_type, entity_id, old_data, new_data)
    VALUES (
        auth.uid(), 
        audit_action, 
        TG_TABLE_NAME, 
        CASE 
            WHEN TG_OP = 'DELETE' THEN OLD.id::text 
            ELSE NEW.id::text 
        END,
        CASE WHEN TG_OP IN ('UPDATE', 'DELETE') THEN to_jsonb(OLD) ELSE NULL END,
        CASE WHEN TG_OP IN ('INSERT', 'UPDATE') THEN to_jsonb(NEW) ELSE NULL END
    );
    RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_mockup_prompt_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'UPDATE' AND (OLD.prompt_text IS DISTINCT FROM NEW.prompt_text OR OLD.ai_model IS DISTINCT FROM NEW.ai_model) THEN
    NEW.version := OLD.version + 1;
    INSERT INTO public.mockup_prompt_history (
      config_id, config_key, old_prompt, new_prompt, ai_model, version, changed_by
    ) VALUES (
      NEW.id, NEW.config_key, OLD.prompt_text, NEW.prompt_text, NEW.ai_model, NEW.version, auth.uid()
    );
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_order_audit_event(p_order_id uuid, p_event_type text, p_description text, p_metadata jsonb DEFAULT '{}'::jsonb, p_created_by uuid DEFAULT auth.uid(), p_created_by_name text DEFAULT NULL::text, p_category text DEFAULT 'general'::text, p_observations text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_actor_name text;
  v_actor_role text;
  v_event_category text;
  v_id uuid;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '28000', MESSAGE = 'Autenticação obrigatória.';
  END IF;

  IF p_created_by IS NOT NULL AND p_created_by <> v_actor AND auth.role() <> 'service_role' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Ator de auditoria inválido.';
  END IF;

  IF NOT EXISTS (
    SELECT 1
      FROM public.orders o
     WHERE o.id = p_order_id
       AND (
         o.seller_id = v_actor
         OR public.can_view_all_sales(v_actor)
         OR (
           public.has_role(v_actor, 'supervisor'::public.app_role)
           AND (o.organization_id IS NULL OR o.organization_id IN (
             SELECT public.get_user_org_ids(v_actor)
           ))
         )
       )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Pedido inexistente ou sem acesso.';
  END IF;

  SELECT COALESCE(p_created_by_name, p.full_name, p.email, 'Usuário'), p.role
    INTO v_actor_name, v_actor_role
    FROM public.profiles p
   WHERE p.user_id = v_actor
   LIMIT 1;

  v_actor_name := COALESCE(v_actor_name, p_created_by_name, 'Usuário');
  v_event_category := CASE
    WHEN p_category IN ('status', 'logistics', 'invoice', 'payment', 'pilot', 'comment', 'system')
      THEN p_category
    WHEN p_event_type IN ('status_change', 'status_changed') THEN 'status'
    ELSE 'system'
  END;

  INSERT INTO public.order_audit_events (
    order_id, event_type, event_category, actor_id, actor_name, actor_role,
    description, metadata, created_by_name, category, observations
  ) VALUES (
    p_order_id, p_event_type, v_event_category, v_actor, v_actor_name, v_actor_role,
    p_description, COALESCE(p_metadata, '{}'::jsonb), v_actor_name,
    p_category, p_observations
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.log_rls_denial(p_table_name text, p_operation text, p_endpoint text DEFAULT NULL::text, p_query_summary text DEFAULT NULL::text, p_target_id uuid DEFAULT NULL::uuid, p_target_seller_id uuid DEFAULT NULL::uuid, p_policy_hint text DEFAULT NULL::text, p_error_code text DEFAULT NULL::text, p_error_message text DEFAULT NULL::text, p_user_agent text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_uid UUID := auth.uid();
  v_email TEXT;
  v_role TEXT;
  v_id UUID;
BEGIN
  IF v_uid IS NULL THEN
    RAISE EXCEPTION 'unauthenticated';
  END IF;

  IF p_operation NOT IN ('SELECT','INSERT','UPDATE','DELETE') THEN
    RAISE EXCEPTION 'invalid_operation';
  END IF;

  -- enriquece com email + papel principal (best-effort)
  SELECT email, role INTO v_email, v_role
  FROM public.profiles
  WHERE user_id = v_uid
  LIMIT 1;

  INSERT INTO public.rls_denial_log (
    user_id, user_email, user_role, table_name, operation,
    endpoint, query_summary, target_id, target_seller_id,
    policy_hint, error_code, error_message, user_agent
  ) VALUES (
    v_uid, v_email, v_role, p_table_name, p_operation,
    p_endpoint, p_query_summary, p_target_id, p_target_seller_id,
    p_policy_hint, p_error_code, p_error_message, p_user_agent
  )
  RETURNING id INTO v_id;

  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_overdue_sicoob_payments()
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE v_count integer;
BEGIN
  PERFORM set_config('app.sicoob_payment_operation', 'overdue', true);
  UPDATE public.sicoob_order_payments
     SET status = 'overdue', updated_at = clock_timestamp()
   WHERE status = 'pending'
     AND due_date < (clock_timestamp() AT TIME ZONE 'America/Sao_Paulo')::date;
  GET DIAGNOSTICS v_count = ROW_COUNT;
  RETURN v_count;
END;
$function$

CREATE OR REPLACE FUNCTION public.mark_step_up_password_verified(_challenge_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid UUID := auth.uid();
  _row RECORD;
BEGIN
  SELECT * INTO _row FROM public.step_up_challenges
  WHERE id = _challenge_id AND user_id = _uid AND consumed = false AND expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    RETURN false;
  END IF;

  UPDATE public.step_up_challenges SET password_verified = true WHERE id = _challenge_id;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id)
  VALUES (_uid, _row.action, _row.target_ref, 'password_verified', _challenge_id);

  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.mcp_audit_actor(_fallback uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  jwt_sub text;
  header_actor text;
BEGIN
  -- Header customizado setado pelas edge functions (set_config('request.jwt.claim.sub', ...))
  BEGIN
    header_actor := current_setting('request.mcp_actor', true);
  EXCEPTION WHEN OTHERS THEN
    header_actor := NULL;
  END;
  IF header_actor IS NOT NULL AND header_actor <> '' THEN
    RETURN header_actor::uuid;
  END IF;

  -- JWT padrão Supabase
  IF auth.uid() IS NOT NULL THEN
    RETURN auth.uid();
  END IF;

  BEGIN
    jwt_sub := current_setting('request.jwt.claims', true)::jsonb->>'sub';
  EXCEPTION WHEN OTHERS THEN
    jwt_sub := NULL;
  END;
  IF jwt_sub IS NOT NULL AND jwt_sub <> '' THEN
    RETURN jwt_sub::uuid;
  END IF;

  RETURN _fallback;
END;
$function$

CREATE OR REPLACE FUNCTION public.move_collection_item_to_trash()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _user_id UUID;
BEGIN
  SELECT user_id INTO _user_id FROM public.collections WHERE id = OLD.collection_id;
  IF _user_id IS NULL THEN
    RETURN OLD;
  END IF;

  INSERT INTO public.collection_items_trash (
    original_id, collection_id, user_id, product_id,
    color_name, color_hex, thumbnail_url, notes, sort_order
  ) VALUES (
    OLD.id, OLD.collection_id, _user_id, OLD.product_id,
    OLD.color_name, OLD.color_hex, OLD.thumbnail_url, OLD.notes, OLD.sort_order
  );
  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.mutate_sicoob_order_item(p_order_id uuid, p_action text, p_item_id uuid DEFAULT NULL::uuid, p_product_id uuid DEFAULT NULL::uuid, p_product_name text DEFAULT NULL::text, p_quantity integer DEFAULT NULL::integer, p_unit_price numeric DEFAULT NULL::numeric)
 RETURNS numeric
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
  v_total numeric;
BEGIN
  IF v_actor IS NULL THEN
    RAISE EXCEPTION 'Usuário autenticado obrigatório.' USING ERRCODE = '42501';
  END IF;
  IF p_action NOT IN ('add', 'remove') THEN
    RAISE EXCEPTION 'Ação de item inválida.' USING ERRCODE = '22023';
  END IF;

  SELECT * INTO v_order FROM public.sicoob_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'Pedido não encontrado.' USING ERRCODE = 'P0002';
  END IF;
  IF v_order.created_by IS DISTINCT FROM v_actor AND NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
    WHERE ur.user_id = v_actor AND ur.role::text IN ('admin', 'manager', 'supervisor', 'dev')
  ) THEN
    RAISE EXCEPTION 'Usuário sem permissão para alterar itens deste pedido.' USING ERRCODE = '42501';
  END IF;
  IF v_order.status <> 'draft' THEN
    RAISE EXCEPTION 'Itens só podem ser alterados enquanto o pedido está em rascunho.' USING ERRCODE = '23514';
  END IF;
  IF v_order.source_quote_id IS NOT NULL THEN
    RAISE EXCEPTION 'Itens de pedido convertido são imutáveis; altere o orçamento de origem antes da conversão.' USING ERRCODE = '23514';
  END IF;

  IF p_action = 'add' THEN
    IF p_product_id IS NULL OR p_product_name IS NULL OR btrim(p_product_name) = ''
       OR length(p_product_name) > 300 OR p_quantity IS NULL OR p_quantity <= 0
       OR p_unit_price IS NULL OR p_unit_price <= 0 THEN
      RAISE EXCEPTION 'Produto, nome, quantidade e preço válidos são obrigatórios.' USING ERRCODE = '23514';
    END IF;
    INSERT INTO public.sicoob_order_items(
      order_id, product_id, product_name, quantity, unit_price, total_price
    ) VALUES (
      p_order_id, p_product_id, btrim(p_product_name), p_quantity, p_unit_price,
      p_quantity * p_unit_price
    );
  ELSE
    IF p_item_id IS NULL THEN
      RAISE EXCEPTION 'Item obrigatório para remoção.' USING ERRCODE = '22023';
    END IF;
    DELETE FROM public.sicoob_order_items
    WHERE id = p_item_id AND order_id = p_order_id;
    IF NOT FOUND THEN
      RAISE EXCEPTION 'Item não encontrado neste pedido.' USING ERRCODE = 'P0002';
    END IF;
  END IF;

  SELECT COALESCE(sum(line_total_amount), 0) INTO v_total
  FROM public.sicoob_order_items
  WHERE order_id = p_order_id;

  UPDATE public.sicoob_orders
  SET merchandise_amount = v_total,
      personalization_amount = 0,
      negotiation_markup_amount = 0,
      commercial_subtotal_amount = v_total,
      discount_amount = 0,
      shipping_amount = 0,
      pricing_formula_version = 'brl-v1',
      total_amount = v_total,
      updated_at = clock_timestamp()
  WHERE id = p_order_id;
  RETURN v_total;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_discount_approval_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  seller_name TEXT;
  quote_num TEXT;
  admin_user RECORD;
BEGIN
  -- Only on new pending requests
  IF TG_OP = 'INSERT' AND NEW.status = 'pending' THEN
    SELECT full_name INTO seller_name FROM public.profiles WHERE user_id = NEW.seller_id;
    SELECT quote_number INTO quote_num FROM public.quotes WHERE id = NEW.quote_id;

    -- Notify all admins
    FOR admin_user IN SELECT ur.user_id FROM public.user_roles ur WHERE ur.role = 'admin' LOOP
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
      VALUES (
        admin_user.user_id,
        '⚠️ Desconto acima do limite',
        COALESCE(seller_name, 'Vendedor') || ' solicitou ' || NEW.requested_discount_percent || '% de desconto no orçamento ' || COALESCE(quote_num, '') || ' (limite: ' || NEW.max_allowed_percent || '%).',
        'warning',
        'quotes',
        '/admin/aprovacoes-desconto'
      );
    END LOOP;
  END IF;

  -- Notify seller on approval/rejection
  IF TG_OP = 'UPDATE' AND OLD.status = 'pending' AND NEW.status IN ('approved', 'rejected') THEN
    SELECT quote_number INTO quote_num FROM public.quotes WHERE id = NEW.quote_id;

    IF NEW.status = 'approved' THEN
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
      VALUES (
        NEW.seller_id,
        '✅ Desconto aprovado!',
        'Seu desconto de ' || NEW.requested_discount_percent || '% no orçamento ' || COALESCE(quote_num, '') || ' foi aprovado.',
        'success',
        'quotes',
        '/orcamentos'
      );
    ELSE
      INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
      VALUES (
        NEW.seller_id,
        '❌ Desconto recusado',
        'Seu desconto de ' || NEW.requested_discount_percent || '% no orçamento ' || COALESCE(quote_num, '') || ' foi recusado.' || COALESCE(' Motivo: ' || NEW.admin_notes, ''),
        'warning',
        'quotes',
        '/orcamentos'
      );
    END IF;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_hardening_regression()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _private_buckets int;
  _sensitive_realtime int;
  _pg_trgm_in_extensions boolean;
  _cleanup_job_active boolean;
  _failures text[] := ARRAY[]::text[];
  _score int := 0;
  _max int := 5;
  _admin record;
  _notified int := 0;
  _msg text;
BEGIN
  SELECT count(*) INTO _private_buckets
  FROM storage.buckets
  WHERE id IN ('personalization-images','product-videos','supplier-logos','component-media')
    AND public = false;
  IF _private_buckets = 4 THEN _score := _score + 1;
  ELSE _failures := _failures || format('Buckets privados: %s/4', _private_buckets); END IF;

  SELECT count(*) INTO _sensitive_realtime
  FROM pg_publication_tables
  WHERE pubname = 'supabase_realtime'
    AND schemaname = 'public'
    AND tablename IN ('discount_approval_requests','kit_variants','kit_comments');
  IF _sensitive_realtime = 0 THEN _score := _score + 1;
  ELSE _failures := _failures || format('Tabelas sensíveis em realtime: %s', _sensitive_realtime); END IF;

  SELECT EXISTS (
    SELECT 1 FROM pg_extension e
    JOIN pg_namespace n ON n.oid = e.extnamespace
    WHERE e.extname = 'pg_trgm' AND n.nspname = 'extensions'
  ) INTO _pg_trgm_in_extensions;
  IF _pg_trgm_in_extensions THEN _score := _score + 1;
  ELSE _failures := _failures || ARRAY['pg_trgm fora do schema extensions']; END IF;

  SELECT EXISTS (
    SELECT 1 FROM cron.job WHERE jobname = 'cleanup-security-logs-daily' AND active = true
  ) INTO _cleanup_job_active;
  IF _cleanup_job_active THEN _score := _score + 1;
  ELSE _failures := _failures || ARRAY['Job cleanup-security-logs-daily inativo']; END IF;

  -- MFA enforced em app — assumido sempre true (controlado em código, não DB)
  _score := _score + 1;

  IF _score >= _max THEN
    RETURN jsonb_build_object('ok', true, 'score', _score, 'max', _max, 'notified', 0);
  END IF;

  _msg := format(
    'Saúde do hardening caiu para %s/%s. Falhas: %s. Acesse /admin/seguranca-acesso.',
    _score, _max, array_to_string(_failures, '; ')
  );

  FOR _admin IN
    SELECT user_id FROM public.user_roles WHERE role = 'admin'
  LOOP
    IF NOT EXISTS (
      SELECT 1 FROM public.workspace_notifications
      WHERE user_id = _admin.user_id
        AND category = 'security'
        AND title = '⚠️ Regressão de hardening detectada'
        AND created_at > now() - interval '20 hours'
    ) THEN
      INSERT INTO public.workspace_notifications (
        user_id, title, message, type, category, action_url, metadata
      ) VALUES (
        _admin.user_id,
        '⚠️ Regressão de hardening detectada',
        _msg,
        'warning',
        'security',
        '/admin/seguranca-acesso',
        jsonb_build_object('score', _score, 'max', _max, 'failures', _failures)
      );
      _notified := _notified + 1;
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'score', _score,
    'max', _max,
    'failures', _failures,
    'notified', _notified
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_order_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    target_user_id UUID;
    v_title TEXT;
    v_message TEXT;
    v_action_url TEXT;
    v_type TEXT := 'info';
    v_coop_nome TEXT;
    v_pa_nome TEXT;
BEGIN
    -- Busca nomes para mensagens mais ricas
    SELECT nome INTO v_coop_nome FROM public.cooperativas WHERE id = NEW.cooperative_id;
    SELECT nome INTO v_pa_nome FROM public.postos_atendimento WHERE id = NEW.pa_id;

    -- Lógica de Notificação por Status BPMN
    IF NEW.status = 'pending' THEN
        -- Notifica Supervisor/Gestor sobre novo pedido
        v_title := 'Novo Pedido Pendente';
        v_message := format('O %s (%s) enviou o pedido #%s para análise.', v_pa_nome, v_coop_nome, NEW.order_number);
        v_action_url := '/sicoob/pedidos/' || NEW.id;
        v_type := 'info';
    ELSIF NEW.status = 'waiting_approval' THEN
        -- Notifica Gestores sobre pedido aguardando aprovação de alçada
        v_title := 'Aprovação de Alçada Requerida';
        v_message := format('Pedido #%s (%s) aguarda aprovação de alçada (R$ %s).', NEW.order_number, v_pa_nome, NEW.total_amount);
        v_action_url := '/sicoob/pedidos/' || NEW.id;
        v_type := 'warning';
    ELSIF NEW.status = 'escalated_to_board' THEN
        -- Notifica Diretoria
        v_title := 'Escalação para Diretoria';
        v_message := format('Pedido #%s escalado para Alçada Superior (Board).', NEW.order_number);
        v_action_url := '/sicoob/pedidos/' || NEW.id;
        v_type := 'warning';
    ELSIF NEW.status = 'confirmed' THEN
        -- Notifica Criador que o pedido foi confirmado
        v_title := 'Pedido Confirmado';
        v_message := format('Seu pedido #%s foi aprovado e seguiu para processamento.', NEW.order_number);
        v_action_url := '/sicoob/pedidos/' || NEW.id;
        v_type := 'success';
    ELSIF NEW.status = 'rejected' THEN
        -- Notifica Criador sobre rejeição
        v_title := 'Pedido Rejeitado';
        v_message := format('O pedido #%s foi rejeitado. Verifique as observações.', NEW.order_number);
        v_action_url := '/sicoob/pedidos/' || NEW.id;
        v_type := 'error';
    END IF;

    -- Inserção na tabela de notificações (Workspace Notifications)
    -- Para simplificar, notificamos o criador em mudanças de status final e gestores em mudanças de entrada
    -- Em um cenário real, buscaríamos os user_ids dos gestores da cooperativa

    -- Notifica o criador (quem criou o pedido)
    IF NEW.status IN ('confirmed', 'rejected', 'logistic', 'completed') THEN
        INSERT INTO public.workspace_notifications (
            user_id, title, message, type, category, action_url, metadata
        ) VALUES (
            NEW.created_by, v_title, v_message, v_type, 'pedidos', v_action_url, 
            jsonb_build_object('order_id', NEW.id, 'status', NEW.status)
        );
    END IF;

    -- Alerta de SLA Crítico
    IF NEW.sla_status = 'critical' AND (OLD.sla_status IS NULL OR OLD.sla_status != 'critical') THEN
        INSERT INTO public.workspace_notifications (
            user_id, title, message, type, category, action_url, metadata
        ) VALUES (
            NEW.created_by, 'ALERTA: SLA Crítico', 
            format('O pedido #%s atingiu nível crítico de SLA.', NEW.order_number), 
            'error', 'pedidos', v_action_url,
            jsonb_build_object('order_id', NEW.id, 'sla', 'critical')
        );
    END IF;

    RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_quote_client_response()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  notif_title TEXT;
  notif_message TEXT;
  notif_type TEXT;
BEGIN
  -- Only trigger when responded_at changes from null
  IF OLD.responded_at IS NOT NULL OR NEW.responded_at IS NULL THEN
    RETURN NEW;
  END IF;

  IF NEW.response = 'approved' THEN
    notif_title := '🎉 Cliente aprovou o orçamento!';
    notif_message := COALESCE(NEW.client_name, 'O cliente') || ' aprovou o orçamento via link de aprovação.';
    notif_type := 'success';
  ELSIF NEW.response = 'rejected' THEN
    notif_title := '😔 Cliente recusou o orçamento';
    notif_message := COALESCE(NEW.client_name, 'O cliente') || ' recusou o orçamento via link de aprovação.';
    notif_type := 'warning';
  ELSE
    RETURN NEW;
  END IF;

  INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
  VALUES (NEW.seller_id, notif_title, notif_message, notif_type, 'quotes', '/orcamentos');

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.notify_quote_status_change()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  notif_title TEXT;
  notif_message TEXT;
  notif_type TEXT;
  notif_category TEXT;
  notif_url TEXT;
BEGIN
  -- Only trigger on status changes
  IF OLD.status IS NOT DISTINCT FROM NEW.status THEN
    RETURN NEW;
  END IF;

  notif_category := 'quotes';
  notif_url := '/orcamentos';

  CASE NEW.status
    WHEN 'approved' THEN
      notif_title := '✅ Orçamento aprovado!';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi aprovado!';
      notif_type := 'success';
    WHEN 'rejected' THEN
      notif_title := '❌ Orçamento recusado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' foi recusado.';
      notif_type := 'warning';
    WHEN 'sent' THEN
      notif_title := '📤 Orçamento enviado';
      notif_message := 'O orçamento ' || NEW.quote_number || ' foi marcado como enviado.';
      notif_type := 'info';
    WHEN 'expired' THEN
      notif_title := '⏰ Orçamento expirado';
      notif_message := 'O orçamento ' || NEW.quote_number || COALESCE(' de ' || NEW.client_name, '') || ' expirou.';
      notif_type := 'warning';
    ELSE
      RETURN NEW;
  END CASE;

  INSERT INTO public.workspace_notifications (user_id, title, message, type, category, action_url)
  VALUES (NEW.seller_id, notif_title, notif_message, notif_type, notif_category, notif_url);

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.prepare_sicoob_order_confirmation(p_order_id uuid, p_expected_status text, p_comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
  v_limit numeric;
  v_policy record;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário não autenticado.';
  END IF;

  SELECT * INTO v_order
    FROM public.sicoob_orders
   WHERE id = p_order_id
   FOR UPDATE;

  IF NOT FOUND OR v_order.status IS DISTINCT FROM p_expected_status OR v_order.status <> 'pending' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'O pedido mudou ou não está disponível para preparação.';
  END IF;
  IF NOT public.sicoob_actor_can_request_approval(v_actor_id, v_order.id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário fora do escopo do pedido.';
  END IF;

  SELECT limite_alcada INTO v_limit
    FROM public.pa_budgets
   WHERE pa_id = v_order.pa_id
     AND ano = EXTRACT(YEAR FROM v_order.created_at)::integer
     AND mes = EXTRACT(MONTH FROM v_order.created_at)::integer;

  IF v_limit IS NULL OR COALESCE(v_order.total_amount, 0) > v_limit THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O pedido requer solicitação formal de aprovação.';
  END IF;

  SELECT * INTO v_policy FROM public.get_sicoob_order_approval_policy(v_order.id);
  PERFORM set_config('app.sicoob_approval_operation', 'prepare', true);
  PERFORM set_config('app.sicoob_order_status_comment', COALESCE(p_comment, 'Preparado para confirmação dentro da alçada.'), true);

  UPDATE public.sicoob_orders
     SET status = 'waiting_approval',
         approval_policy_id = COALESCE(v_order.approval_policy_id, v_policy.policy_id),
         approval_policy_version = COALESCE(v_order.approval_policy_version, v_policy.policy_version),
         updated_at = now()
   WHERE id = v_order.id;
END;
$function$

