CREATE OR REPLACE FUNCTION public.protect_latest_quote_version_deletion()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_root_id uuid := COALESCE(OLD.parent_quote_id, OLD.id);
BEGIN
  IF TG_OP = 'UPDATE' AND NOT (OLD.deleted_at IS NULL AND NEW.deleted_at IS NOT NULL) THEN
    RETURN NEW;
  END IF;

  IF OLD.is_latest_version
     AND EXISTS (
       SELECT 1 FROM public.quotes q
       WHERE q.id <> OLD.id
         AND (q.id = v_root_id OR q.parent_quote_id = v_root_id)
         AND q.deleted_at IS NULL
     ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'A versão vigente não pode ser excluída enquanto a família possuir outras versões.';
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_sicoob_approval_delegation()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Delegações não podem ser excluídas.';
  END IF;
  IF current_setting('app.sicoob_delegation_operation', true) <> 'revoke' THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Delegação só pode ser alterada pela revogação formal.';
  END IF;
  IF NEW.id IS DISTINCT FROM OLD.id
     OR NEW.delegator_id IS DISTINCT FROM OLD.delegator_id
     OR NEW.delegate_id IS DISTINCT FROM OLD.delegate_id
     OR NEW.cooperative_id IS DISTINCT FROM OLD.cooperative_id
     OR NEW.pa_id IS DISTINCT FROM OLD.pa_id
     OR NEW.competencies IS DISTINCT FROM OLD.competencies
     OR NEW.starts_at IS DISTINCT FROM OLD.starts_at
     OR NEW.ends_at IS DISTINCT FROM OLD.ends_at
     OR NEW.reason IS DISTINCT FROM OLD.reason
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='O escopo de uma delegação é imutável.';
  END IF;
  IF OLD.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Delegação já revogada.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_sicoob_approval_request()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_operation text := current_setting('app.sicoob_approval_operation', true);
BEGIN
  IF NEW.order_id IS DISTINCT FROM OLD.order_id
     OR NEW.requester_id IS DISTINCT FROM OLD.requester_id
     OR NEW.request_reason IS DISTINCT FROM OLD.request_reason
     OR NEW.amount_at_request IS DISTINCT FROM OLD.amount_at_request
     OR NEW.threshold_at_request IS DISTINCT FROM OLD.threshold_at_request THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Os dados submetidos para aprovação são imutáveis.';
  END IF;

  IF NEW.metadata IS DISTINCT FROM OLD.metadata AND v_operation IS DISTINCT FROM 'escalate' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Os metadados da solicitação não podem ser alterados fora da escalação formal.';
  END IF;

  IF NEW.status IS DISTINCT FROM OLD.status THEN
    IF NEW.status = 'pending'
       OR (NEW.status = 'approved' AND v_operation IS DISTINCT FROM 'approve')
       OR (NEW.status = 'rejected' AND v_operation IS DISTINCT FROM 'reject') THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O resultado da aprovação exige RPC de decisão formal.';
    END IF;
  END IF;

  IF NEW.approver_id IS DISTINCT FROM OLD.approver_id
     AND v_operation IS DISTINCT FROM 'approve'
     AND v_operation IS DISTINCT FROM 'reject' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O aprovador só pode ser definido na decisão formal.';
  END IF;

  IF NEW.rejection_reason IS DISTINCT FROM OLD.rejection_reason
     AND v_operation IS DISTINCT FROM 'reject' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O motivo de rejeição só pode ser definido na decisão formal.';
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_sicoob_consolidation_records()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_operation text := current_setting('app.sicoob_consolidation_operation', true);
BEGIN
  IF TG_TABLE_NAME = 'sicoob_delivery_receipt_events' AND TG_OP <> 'INSERT' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Eventos de recebimento são imutáveis.';
  END IF;
  IF COALESCE(v_operation, '') NOT IN ('create', 'allocate', 'dispatch', 'receive') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Consolidação só pode ser alterada pelo fluxo transacional.';
  END IF;
  RETURN COALESCE(NEW, OLD);
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_sicoob_order_artwork_version()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Versões de arte não podem ser excluídas.';
  END IF;
  IF NEW.order_id IS DISTINCT FROM OLD.order_id
     OR NEW.version IS DISTINCT FROM OLD.version
     OR NEW.file_path IS DISTINCT FROM OLD.file_path
     OR NEW.file_sha256 IS DISTINCT FROM OLD.file_sha256
     OR NEW.identity_snapshot IS DISTINCT FROM OLD.identity_snapshot
     OR NEW.created_by IS DISTINCT FROM OLD.created_by
     OR NEW.created_at IS DISTINCT FROM OLD.created_at THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A versão de arte é imutável.';
  END IF;
  IF NEW.is_latest IS DISTINCT FROM OLD.is_latest
     AND current_setting('app.sicoob_artwork_operation', true) IS DISTINCT FROM 'version' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Somente uma nova versão pode substituir a arte vigente.';
  END IF;
  IF (NEW.status IS DISTINCT FROM OLD.status
      OR NEW.feedback IS DISTINCT FROM OLD.feedback
      OR NEW.decided_by IS DISTINCT FROM OLD.decided_by
      OR NEW.decided_at IS DISTINCT FROM OLD.decided_at)
     AND current_setting('app.sicoob_artwork_operation', true) IS DISTINCT FROM 'decide' THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'A decisão exige o fluxo formal de aprovação da arte.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.protect_sicoob_order_payment()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF COALESCE(current_setting('app.sicoob_payment_operation', true), '')
     NOT IN ('record', 'refund', 'overdue') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Pagamentos só podem ser alterados pelo fluxo financeiro formal.';
  END IF;
  IF TG_OP = 'DELETE' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Registros financeiros não podem ser excluídos.';
  END IF;
  IF TG_OP = 'UPDATE' AND (
    NEW.order_id IS DISTINCT FROM OLD.order_id
    OR NEW.installment_number IS DISTINCT FROM OLD.installment_number
    OR NEW.created_by IS DISTINCT FROM OLD.created_by
    OR NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Identidade da parcela financeira é imutável.';
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.qa_preflight_check()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
    result JSONB;
    users_ok BOOLEAN;
    pas_ok BOOLEAN;
    budgets_ok BOOLEAN;
    coupons_ok BOOLEAN;
    orders_ok BOOLEAN;
BEGIN
    SELECT count(*) > 0 INTO users_ok FROM auth.users WHERE email LIKE 'qa+%';
    SELECT count(*) > 0 INTO pas_ok FROM public.postos_atendimento WHERE is_active IS TRUE;
    SELECT count(*) > 0 INTO budgets_ok FROM public.pa_budgets;
    SELECT count(*) > 0 INTO coupons_ok FROM public.coupons;
    SELECT count(*) > 0 INTO orders_ok FROM public.orders;

    result := jsonb_build_object(
        'users', users_ok,
        'pas', pas_ok,
        'budgets', budgets_ok,
        'coupons', coupons_ok,
        'orders', orders_ok,
        'timestamp', now()
    );

    RETURN result;
END;
$function$

CREATE OR REPLACE FUNCTION public.reconcile_sicoob_approval_delivery(p_delivery_id uuid, p_resolution text, p_provider_id text DEFAULT NULL::text, p_reason text DEFAULT NULL::text, p_operator text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_delivery public.sicoob_approval_deliveries%ROWTYPE;
  v_new_id uuid;
  v_setting public.pa_notification_settings%ROWTYPE;
  v_expected_destination text;
BEGIN
  IF p_resolution NOT IN ('delivered','requeue')
     OR length(btrim(COALESCE(p_reason,''))) NOT BETWEEN 10 AND 500
     OR length(btrim(COALESCE(p_operator,''))) NOT BETWEEN 3 AND 200
     OR length(p_provider_id) > 200
     OR (p_resolution='delivered' AND NULLIF(btrim(p_provider_id),'') IS NULL) THEN
    RAISE EXCEPTION 'Reconciliação inválida.' USING ERRCODE='22023';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_delivery_id::text || ':reconcile',0));
  SELECT * INTO v_delivery FROM public.sicoob_approval_deliveries
   WHERE id=p_delivery_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'Entrega não encontrada.' USING ERRCODE='P0002'; END IF;
  IF v_delivery.state NOT IN ('uncertain','failed') OR v_delivery.reconciliation IS NOT NULL THEN
    RAISE EXCEPTION 'A entrega não está disponível para reconciliação.' USING ERRCODE='23514';
  END IF;

  IF p_resolution='delivered' THEN
    UPDATE public.sicoob_approval_deliveries SET
      state='delivered', provider_id=btrim(p_provider_id), delivered_at=clock_timestamp(),
      last_error_code=NULL, updated_at=clock_timestamp(),
      reconciliation=jsonb_build_object(
        'resolution','delivered','reason',btrim(p_reason),'operator',btrim(p_operator),
        'provider_id',btrim(p_provider_id),'reconciled_at',clock_timestamp()
      )
    WHERE id=p_delivery_id;
    RETURN p_delivery_id;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.sicoob_approval_deliveries newer
    WHERE newer.request_id=v_delivery.request_id AND newer.event_kind=v_delivery.event_kind
      AND newer.channel=v_delivery.channel AND newer.generation>v_delivery.generation
      AND newer.state<>'cancelled'
  ) THEN
    RAISE EXCEPTION 'Já existe geração posterior para esta entrega.' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.sicoob_approval_requests r
    WHERE r.id=v_delivery.request_id AND r.status='pending'
  ) THEN
    RAISE EXCEPTION 'A solicitação não está mais pendente.' USING ERRCODE='23514';
  END IF;
  SELECT * INTO v_setting FROM public.pa_notification_settings s
   WHERE s.id=v_delivery.setting_id AND s.is_active IS TRUE AND s.channel=v_delivery.channel;
  IF NOT FOUND THEN
    RAISE EXCEPTION 'A configuração do destino não está ativa.' USING ERRCODE='23514';
  END IF;
  v_expected_destination := CASE v_setting.channel
    WHEN 'slack' THEN COALESCE(v_setting.webhook_url,'')
    ELSE COALESCE(v_setting.recipient_email,'') END;
  UPDATE public.sicoob_approval_deliveries SET
    reconciliation=jsonb_build_object(
      'resolution','requeue','reason',btrim(p_reason),'operator',btrim(p_operator),
      'reconciled_at',clock_timestamp()
    ), updated_at=clock_timestamp()
  WHERE id=p_delivery_id;

  INSERT INTO public.sicoob_approval_deliveries(
    request_id,setting_id,channel,destination,payload,event_kind,generation,supersedes_delivery_id
  ) VALUES (
    v_delivery.request_id,v_setting.id,v_delivery.channel,v_expected_destination,
    v_delivery.payload || jsonb_build_object(
      'reconciliation_reason',btrim(p_reason),'reconciliation_operator',btrim(p_operator)
    ),
    v_delivery.event_kind,v_delivery.generation+1,v_delivery.id
  ) RETURNING id INTO v_new_id;
  RETURN v_new_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_mcp_access_violation(_user_id uuid, _reason text, _source text, _operation text DEFAULT NULL::text, _target_key_id uuid DEFAULT NULL::uuid, _ip text DEFAULT NULL::text, _user_agent text DEFAULT NULL::text, _request_id text DEFAULT NULL::text, _details jsonb DEFAULT '{}'::jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_id UUID;
BEGIN
  INSERT INTO public.mcp_access_violations (
    user_id, reason, source, operation, target_key_id,
    ip_address, user_agent, request_id, details
  ) VALUES (
    _user_id, _reason, _source, _operation, _target_key_id,
    _ip, _user_agent, _request_id, COALESCE(_details, '{}'::jsonb)
  )
  RETURNING id INTO v_id;

  PERFORM public.check_mcp_abuse_threshold(_user_id, _ip);

  RETURN v_id;
EXCEPTION WHEN OTHERS THEN
  -- Nunca derruba a operação chamadora
  RAISE WARNING 'record_mcp_access_violation failed: %', SQLERRM;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_public_token_failure(_resource_type text, _resource_id text, _attempted_token text, _ip text, _ua text, _reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _recent_failures int;
BEGIN
  INSERT INTO public.public_token_failures (
    resource_type, resource_id, attempted_token, ip_address, user_agent, reason
  ) VALUES (
    _resource_type, _resource_id, _attempted_token, _ip, _ua, _reason
  );

  IF _resource_id IS NULL THEN
    RETURN;
  END IF;

  SELECT count(*) INTO _recent_failures
  FROM public.public_token_failures
  WHERE resource_type = _resource_type
    AND resource_id = _resource_id
    AND created_at > now() - interval '1 hour';

  IF _recent_failures >= 5 THEN
    IF _resource_type = 'quote' THEN
      UPDATE public.quote_approval_tokens
      SET status = 'expired', updated_at = now()
      WHERE quote_id = _resource_id AND status = 'active';
    ELSIF _resource_type = 'kit' THEN
      UPDATE public.kit_share_tokens
      SET status = 'expired', updated_at = now()
      WHERE kit_id::text = _resource_id AND status = 'active';
    END IF;
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_sicoob_delivery_receipt(p_allocation_id uuid, p_idempotency_key uuid, p_received_quantity integer DEFAULT 0, p_damaged_quantity integer DEFAULT 0, p_missing_quantity integer DEFAULT 0, p_notes text DEFAULT NULL::text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_allocation public.sicoob_delivery_allocations%ROWTYPE;
  v_group public.order_consolidations%ROWTYPE;
  v_event_id uuid;
  v_has_issues boolean;
  v_all_complete boolean;
  v_destination_pa_id uuid;
  v_existing_event public.sicoob_delivery_receipt_events%ROWTYPE;
BEGIN
  IF p_idempotency_key IS NULL
     OR p_received_quantity < 0 OR p_damaged_quantity < 0 OR p_missing_quantity < 0
     OR p_received_quantity + p_damaged_quantity + p_missing_quantity <= 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe ao menos uma quantidade positiva.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended('sicoob-delivery-receipt:' || p_idempotency_key::text, 0));
  SELECT * INTO v_existing_event
    FROM public.sicoob_delivery_receipt_events
   WHERE idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF v_existing_event.allocation_id IS DISTINCT FROM p_allocation_id
       OR v_existing_event.received_quantity IS DISTINCT FROM p_received_quantity
       OR v_existing_event.damaged_quantity IS DISTINCT FROM p_damaged_quantity
       OR v_existing_event.missing_quantity IS DISTINCT FROM p_missing_quantity
       OR v_existing_event.notes IS DISTINCT FROM NULLIF(trim(p_notes), '')
       OR v_existing_event.received_by IS DISTINCT FROM v_actor_id THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com outro recebimento.';
    END IF;
    RETURN v_existing_event.id;
  END IF;
  IF p_damaged_quantity + p_missing_quantity > 0
     AND length(trim(COALESCE(p_notes, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Descreva a divergência com ao menos 10 caracteres.';
  END IF;

  SELECT a.* INTO v_allocation
  FROM public.sicoob_delivery_allocations a WHERE a.id = p_allocation_id FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Alocação não encontrada.'; END IF;
  SELECT c.* INTO v_group
  FROM public.sicoob_delivery_destinations d
  JOIN public.order_consolidations c ON c.id = d.consolidation_id
  WHERE d.id = v_allocation.destination_id FOR UPDATE OF c;
  SELECT pa_id INTO v_destination_pa_id
  FROM public.sicoob_delivery_destinations WHERE id = v_allocation.destination_id;
  IF v_group.status NOT IN ('sent', 'partially_received') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Recebimento permitido somente após o despacho.';
  END IF;
  IF NOT public.sicoob_actor_can_manage_consolidation(v_actor_id, v_group.singular_id)
     AND NOT EXISTS (
       SELECT 1 FROM public.profiles p
       WHERE (p.user_id = v_actor_id OR p.id = v_actor_id)
         AND p.pa_id = v_destination_pa_id
         AND p.is_active IS TRUE
         AND p.deleted_at IS NULL
         AND EXISTS (
           SELECT 1 FROM public.user_roles ur
           WHERE ur.user_id = v_actor_id AND ur.role::text IN ('gerente_pa', 'comprador_pac')
         )
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário fora do escopo da consolidação.';
  END IF;
  IF v_allocation.received_quantity + v_allocation.damaged_quantity + v_allocation.missing_quantity
     + p_received_quantity + p_damaged_quantity + p_missing_quantity > v_allocation.quantity THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O recebimento supera a quantidade destinada.';
  END IF;

  PERFORM set_config('app.sicoob_consolidation_operation', 'receive', true);
  INSERT INTO public.sicoob_delivery_receipt_events (
    idempotency_key, allocation_id, received_quantity, damaged_quantity, missing_quantity, notes, received_by
  ) VALUES (
    p_idempotency_key, p_allocation_id, p_received_quantity, p_damaged_quantity, p_missing_quantity,
    NULLIF(trim(p_notes), ''), v_actor_id
  ) RETURNING id INTO v_event_id;
  UPDATE public.sicoob_delivery_allocations SET
    received_quantity = received_quantity + p_received_quantity,
    damaged_quantity = damaged_quantity + p_damaged_quantity,
    missing_quantity = missing_quantity + p_missing_quantity,
    updated_at = now()
  WHERE id = p_allocation_id;

  SELECT bool_and(a.received_quantity + a.damaged_quantity + a.missing_quantity = a.quantity),
         bool_or(a.damaged_quantity > 0 OR a.missing_quantity > 0)
    INTO v_all_complete, v_has_issues
    FROM public.sicoob_delivery_allocations a
    JOIN public.sicoob_delivery_destinations d ON d.id = a.destination_id
   WHERE d.consolidation_id = v_group.id;
  UPDATE public.order_consolidations SET
    status = CASE
      WHEN v_all_complete AND v_has_issues THEN 'received_with_issues'
      WHEN v_all_complete THEN 'received'
      ELSE 'partially_received'
    END,
    received_at = CASE WHEN v_all_complete THEN now() ELSE NULL END,
    updated_at = now()
  WHERE id = v_group.id;
  -- Quantidades avariadas ou faltantes encerram a conferência física do lote,
  -- mas não caracterizam entrega concluída. O pedido permanece em logística
  -- até que a divergência seja resolvida pelo fluxo operacional.
  IF v_all_complete AND NOT v_has_issues THEN
    PERFORM set_config('app.sicoob_order_status_comment', 'Recebimento integral do lote consolidado ' || v_group.id::text || '.', true);
    UPDATE public.sicoob_orders o
       SET status = 'completed', updated_at = now()
      FROM public.order_consolidation_orders co
     WHERE co.consolidation_id = v_group.id
       AND co.order_id = o.id
       AND o.status = 'logistic';
    IF NOT FOUND OR EXISTS (
      SELECT 1
        FROM public.order_consolidation_orders co
        JOIN public.sicoob_orders o ON o.id = co.order_id
       WHERE co.consolidation_id = v_group.id
         AND o.status <> 'completed'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Um pedido do lote mudou; atualize a página.';
    END IF;
  END IF;
  RETURN v_event_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.record_sicoob_order_payment(p_order_id uuid, p_installment_number integer, p_amount numeric, p_due_date date, p_status text DEFAULT 'pending'::text, p_invoice_id uuid DEFAULT NULL::uuid, p_payment_method text DEFAULT NULL::text, p_external_reference text DEFAULT NULL::text, p_expected_updated_at timestamp with time zone DEFAULT NULL::timestamp with time zone)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
  v_existing public.sicoob_order_payments%ROWTYPE;
  v_payment_id uuid;
  v_active_total numeric;
BEGIN
  IF v_actor_id IS NULL OR NOT public.sicoob_actor_can_manage_finance(v_actor_id, p_order_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode registrar pagamentos neste pedido.';
  END IF;
  IF p_installment_number <= 0 OR p_amount <= 0 OR p_due_date IS NULL
     OR p_status NOT IN ('pending', 'paid', 'cancelled') THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Dados da parcela são inválidos.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(p_order_id::text || ':finance', 0));
  SELECT * INTO v_order FROM public.sicoob_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Pedido não encontrado.';
  END IF;
  IF v_order.status NOT IN ('confirmed', 'logistic', 'in_production', 'in_separation', 'in_transit', 'delivered', 'completed') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O pedido precisa estar confirmado para receber parcelas.';
  END IF;
  IF p_invoice_id IS NOT NULL AND NOT EXISTS (
    SELECT 1 FROM public.sicoob_order_invoices
     WHERE id = p_invoice_id AND order_id = p_order_id
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23503', MESSAGE = 'A nota fiscal não pertence ao pedido.';
  END IF;

  SELECT * INTO v_existing
    FROM public.sicoob_order_payments
   WHERE order_id = p_order_id AND installment_number = p_installment_number
   FOR UPDATE;
  IF FOUND AND p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'A parcela já existe; informe a versão atual antes de alterar.';
  END IF;
  IF FOUND AND p_expected_updated_at IS NOT NULL
     AND v_existing.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'A parcela mudou; atualize a página antes de salvar.';
  END IF;
  IF FOUND AND v_existing.status IN ('paid', 'refunded')
     AND (
       v_existing.invoice_id IS DISTINCT FROM p_invoice_id
       OR v_existing.amount IS DISTINCT FROM p_amount
       OR v_existing.due_date IS DISTINCT FROM p_due_date
       OR v_existing.status IS DISTINCT FROM p_status
       OR v_existing.payment_method IS DISTINCT FROM NULLIF(trim(p_payment_method), '')
       OR v_existing.external_reference IS DISTINCT FROM NULLIF(trim(p_external_reference), '')
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Parcela liquidada exige estorno formal antes de outra alteração.';
  END IF;

  SELECT COALESCE(sum(amount), 0) INTO v_active_total
    FROM public.sicoob_order_payments
   WHERE order_id = p_order_id
     AND installment_number <> p_installment_number
     AND status IN ('pending', 'paid', 'overdue');
  IF p_status IN ('pending', 'paid') AND v_active_total + p_amount > v_order.total_amount THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A soma das parcelas supera o valor do pedido.';
  END IF;

  PERFORM set_config('app.sicoob_payment_operation', 'record', true);
  INSERT INTO public.sicoob_order_payments (
    order_id, invoice_id, installment_number, amount, due_date, paid_at,
    payment_method, external_reference, status, created_by, updated_by
  ) VALUES (
    p_order_id, p_invoice_id, p_installment_number, p_amount, p_due_date,
    CASE WHEN p_status = 'paid' THEN now() ELSE NULL END,
    NULLIF(trim(p_payment_method), ''), NULLIF(trim(p_external_reference), ''),
    p_status, v_actor_id, v_actor_id
  )
  ON CONFLICT (order_id, installment_number) DO UPDATE SET
    invoice_id = EXCLUDED.invoice_id,
    amount = EXCLUDED.amount,
    due_date = EXCLUDED.due_date,
    paid_at = CASE
      WHEN EXCLUDED.status = 'paid' THEN COALESCE(public.sicoob_order_payments.paid_at, now())
      ELSE NULL
    END,
    payment_method = EXCLUDED.payment_method,
    external_reference = EXCLUDED.external_reference,
    status = EXCLUDED.status,
    updated_by = v_actor_id,
    updated_at = now()
  RETURNING id INTO v_payment_id;
  RETURN v_payment_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.refresh_sicoob_reorder_quote(p_quote_id uuid, p_items jsonb, p_actor_id uuid)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_quote public.quotes%ROWTYPE;
  v_item jsonb;
  v_source_item_id uuid;
  v_target_item public.quote_items%ROWTYPE;
  v_personalization jsonb;
  v_total numeric(14,2) := 0;
  v_sort_order integer := 0;
  v_valid_until timestamptz;
BEGIN
  IF p_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária.';
  END IF;
  v_valid_until := public.sicoob_assert_current_reorder_items(p_items);
  SELECT * INTO v_quote FROM public.quotes q WHERE q.id = p_quote_id FOR UPDATE;
  IF NOT FOUND OR (v_quote.reorder_source_order_id IS NULL AND v_quote.reorder_source_quote_id IS NULL) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Orçamento de recompra não encontrado.';
  END IF;
  IF v_quote.status::text NOT IN ('draft', 'revision', 'rejected', 'rejected_singular') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A recompra não pode mais ser revalidada neste estado.';
  END IF;
  IF v_quote.seller_id IS DISTINCT FROM p_actor_id
     AND NOT public.can_manage_quote_scope(p_actor_id, p_quote_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode revalidar esta recompra.';
  END IF;
  IF jsonb_array_length(p_items) IS DISTINCT FROM (
       SELECT count(*)::integer FROM public.quote_items WHERE quote_id = p_quote_id
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A quantidade de itens mudou; crie uma nova recompra.';
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    v_source_item_id := (v_item ->> 'source_order_item_id')::uuid;
    IF v_quote.reorder_source_order_id IS NOT NULL THEN
      IF NOT EXISTS (
        SELECT 1 FROM public.sicoob_order_items source_item
        WHERE source_item.id = v_source_item_id
          AND source_item.order_id = v_quote.reorder_source_order_id
          AND source_item.product_id::text = v_item ->> 'product_id'
          AND source_item.quantity = (v_item ->> 'quantity')::integer
      ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Item divergente do pedido de origem.';
      END IF;
    ELSE
      IF NOT EXISTS (
        SELECT 1 FROM public.quote_items source_item
        WHERE source_item.id = v_source_item_id
          AND source_item.quote_id = v_quote.reorder_source_quote_id
          AND source_item.product_id = v_item ->> 'product_id'
          AND source_item.quantity = (v_item ->> 'quantity')::integer
      ) THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Item divergente do orçamento de origem.';
      END IF;
    END IF;

    SELECT * INTO v_target_item FROM public.quote_items qi
    WHERE qi.quote_id = p_quote_id AND COALESCE(qi.sort_order, 0) = v_sort_order
    FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Item de destino não encontrado.';
    END IF;

    UPDATE public.quote_items qi
    SET product_id = v_item ->> 'product_id',
        product_name = v_item ->> 'product_name',
        product_sku = NULLIF(v_item ->> 'product_sku', ''),
        product_image_url = NULLIF(v_item ->> 'product_image_url', ''),
        quantity = (v_item ->> 'quantity')::integer,
        unit_price = (v_item ->> 'unit_price')::numeric,
        color_name = NULLIF(v_item ->> 'color_name', ''),
        color_hex = NULLIF(v_item ->> 'color_hex', ''),
        size_code = NULLIF(v_item ->> 'size_code', ''),
        source_variant_id = NULLIF(v_item ->> 'source_variant_id', ''),
        source_variant_sku = NULLIF(v_item ->> 'source_variant_sku', ''),
        catalog_checked_at = (v_item ->> 'catalog_checked_at')::timestamptz,
        catalog_available_stock = (v_item ->> 'available_stock')::integer,
        catalog_minimum_quantity = (v_item ->> 'minimum_quantity')::integer,
        catalog_valid_until = (v_item ->> 'catalog_valid_until')::timestamptz,
        historical_unit_price = NULLIF(v_item ->> 'historical_unit_price', '')::numeric,
        price_changed = COALESCE((v_item ->> 'price_changed')::boolean, false),
        catalog_stock_is_reserved = false,
        updated_at = statement_timestamp()
    WHERE qi.id = v_target_item.id;

    DELETE FROM public.quote_item_personalizations WHERE quote_item_id = v_target_item.id;
    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name, colors_count, width_cm, height_cm,
        personalized_quantity, unit_cost, setup_cost, total_cost, notes, catalog_checked_at
      ) VALUES (
        v_target_item.id, v_personalization ->> 'technique_id', v_personalization ->> 'technique_name',
        (v_personalization ->> 'colors_count')::integer,
        NULLIF(v_personalization ->> 'width_cm', '')::numeric,
        NULLIF(v_personalization ->> 'height_cm', '')::numeric,
        (v_personalization ->> 'personalized_quantity')::integer,
        (v_personalization ->> 'unit_cost')::numeric,
        (v_personalization ->> 'setup_cost')::numeric,
        (v_personalization ->> 'total_cost')::numeric,
        'Arte histórica copiada como referência; exige nova validação de marca.',
        (v_personalization ->> 'catalog_checked_at')::timestamptz
      );
      v_total := v_total + (v_personalization ->> 'total_cost')::numeric;
    END LOOP;
    v_total := v_total + (v_item ->> 'quantity')::integer * (v_item ->> 'unit_price')::numeric;
    v_sort_order := v_sort_order + 1;
  END LOOP;

  PERFORM set_config('app.quote_governance_write', 'true', true);
  UPDATE public.quotes q
  SET subtotal = v_total,
      total = v_total,
      catalog_revalidated_at = statement_timestamp(),
      catalog_valid_until = v_valid_until,
      catalog_stock_is_reserved = false,
      reorder_price_changed_items = (
        SELECT count(*) FROM jsonb_array_elements(p_items) source(item)
        WHERE COALESCE((item ->> 'price_changed')::boolean, false)
      ),
      row_version = q.row_version + 1,
      updated_at = statement_timestamp()
  WHERE q.id = p_quote_id;

  INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
  VALUES (
    p_quote_id, p_actor_id, 'updated', 'Preço, mínimo e estoque reconsultados para a recompra.',
    jsonb_build_object(
      'catalog_valid_until', v_valid_until,
      'price_changed_items', (
        SELECT count(*) FROM jsonb_array_elements(p_items) source(item)
        WHERE COALESCE((item ->> 'price_changed')::boolean, false)
      ),
      'stock_is_reserved', false
    )
  );
  RETURN p_quote_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.refund_sicoob_order_payment(p_payment_id uuid, p_reason text, p_expected_updated_at timestamp with time zone)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order_id uuid;
  v_payment public.sicoob_order_payments%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL OR length(trim(COALESCE(p_reason, ''))) < 10 OR p_expected_updated_at IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Motivo e versão atual da parcela são obrigatórios para o estorno.';
  END IF;
  SELECT order_id INTO v_order_id FROM public.sicoob_order_payments WHERE id = p_payment_id;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Parcela não encontrada.'; END IF;
  IF NOT public.sicoob_actor_can_manage_finance(v_actor_id, v_order_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode estornar pagamentos deste pedido.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(v_order_id::text || ':finance', 0));
  SELECT * INTO v_payment FROM public.sicoob_order_payments WHERE id = p_payment_id FOR UPDATE;
  IF v_payment.updated_at IS DISTINCT FROM p_expected_updated_at THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'A parcela mudou; atualize a página antes de estornar.';
  END IF;
  IF v_payment.status <> 'paid' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Somente uma parcela paga pode ser estornada.';
  END IF;

  PERFORM set_config('app.sicoob_payment_operation', 'refund', true);
  UPDATE public.sicoob_order_payments
     SET status = 'refunded',
         refunded_at = now(),
         refunded_by = v_actor_id,
         refund_reason = trim(p_reason),
         updated_by = v_actor_id,
         updated_at = now()
   WHERE id = p_payment_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.register_sicoob_clean_document(p_document_id uuid, p_actor_id uuid, p_order_id uuid, p_purpose text, p_quarantine_path text, p_final_path text, p_sha256 text, p_detected_mime text, p_byte_size bigint, p_scanner_name text, p_scanner_version text, p_scan_evidence jsonb)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF auth.jwt()->>'role' IS DISTINCT FROM 'service_role' THEN
    RAISE EXCEPTION 'O registro exige o verificador interno.' USING ERRCODE='42501';
  END IF;
  IF p_document_id IS NULL OR p_actor_id IS NULL
     OR NOT public.sicoob_actor_can_manage_fulfillment(p_actor_id,p_order_id) THEN
    RAISE EXCEPTION 'Ator sem acesso ao pedido.' USING ERRCODE='42501';
  END IF;
  IF p_purpose NOT IN ('invoice_pdf','invoice_xml','delivery_proof')
     OR p_quarantine_path NOT LIKE p_actor_id::text||'/'||p_order_id::text||'/%'
     OR p_final_path NOT LIKE p_order_id::text||'/%'
     OR p_sha256 !~ '^[0-9a-f]{64}$'
     OR p_byte_size < 1 OR p_byte_size > 10485760
     OR nullif(btrim(p_scanner_name),'') IS NULL
     OR jsonb_typeof(p_scan_evidence) IS DISTINCT FROM 'object'
     OR p_scan_evidence->>'clean' IS DISTINCT FROM 'true'
     OR p_scan_evidence->>'engine' IS DISTINCT FROM p_scanner_name THEN
    RAISE EXCEPTION 'Evidência de inspeção inválida.' USING ERRCODE='22023';
  END IF;
  IF (p_purpose='invoice_pdf' AND (p_detected_mime<>'application/pdf' OR p_final_path NOT LIKE p_order_id::text||'/invoices/%.pdf'))
     OR (p_purpose='invoice_xml' AND (p_detected_mime<>'application/xml' OR p_final_path NOT LIKE p_order_id::text||'/invoices/%.xml'))
     OR (p_purpose='delivery_proof' AND (p_detected_mime NOT IN ('image/jpeg','image/png','image/webp') OR p_final_path NOT LIKE p_order_id::text||'/delivery/%')) THEN
    RAISE EXCEPTION 'Tipo detectado, finalidade e caminho final divergem.' USING ERRCODE='23514';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM storage.objects object
    WHERE object.bucket_id='sicoob-document-quarantine' AND object.name=p_quarantine_path
  ) OR NOT EXISTS (
    SELECT 1 FROM storage.objects object
    WHERE object.bucket_id='sicoob-order-documents' AND object.name=p_final_path
      AND lower(COALESCE(object.metadata->>'mimetype',''))=p_detected_mime
      AND COALESCE(object.metadata->>'size','')=p_byte_size::text
  ) THEN
    RAISE EXCEPTION 'Os objetos de quarentena e promoção não correspondem à evidência.' USING ERRCODE='23514';
  END IF;

  INSERT INTO public.sicoob_document_registry(
    id,order_id,purpose,quarantine_path,final_path,status,uploaded_by,
    sha256,detected_mime,byte_size,scanner_name,scanner_version,scan_evidence
  ) VALUES (
    p_document_id,p_order_id,p_purpose,p_quarantine_path,p_final_path,'clean',p_actor_id,
    p_sha256,p_detected_mime,p_byte_size,btrim(p_scanner_name),nullif(btrim(p_scanner_version),''),p_scan_evidence
  );
  RETURN p_document_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_sicoob_order(p_request_id uuid, p_order_id uuid, p_manager_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_request public.sicoob_approval_requests%ROWTYPE;
  v_order public.sicoob_orders%ROWTYPE;
  v_authority record;
BEGIN
  IF v_actor_id IS NULL OR p_manager_id IS DISTINCT FROM v_actor_id THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Identidade do aprovador inválida.';
  END IF;
  IF length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Informe um motivo de rejeição com ao menos 10 caracteres.';
  END IF;
  SELECT * INTO v_order FROM public.sicoob_orders WHERE id=p_order_id FOR UPDATE;
  SELECT * INTO v_request FROM public.sicoob_approval_requests WHERE id=p_request_id FOR UPDATE;
  IF NOT FOUND OR v_order.id IS NULL OR v_request.order_id <> v_order.id THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Solicitação ou pedido não encontrado.';
  END IF;
  IF v_request.status <> 'pending' OR v_order.status NOT IN ('waiting_approval', 'escalated_to_board') THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Solicitação ou pedido não está disponível para rejeição.';
  END IF;
  SELECT * INTO STRICT v_authority FROM public.resolve_sicoob_approval_authority(
    v_actor_id, v_order.id, v_request.requester_id,
    v_order.status='escalated_to_board', 'reject_order'
  );
  PERFORM set_config('app.sicoob_approval_operation', 'reject', true);
  PERFORM set_config('app.sicoob_order_status_comment', btrim(p_reason), true);
  UPDATE public.sicoob_approval_requests SET
    status='rejected', approver_id=v_actor_id, rejection_reason=btrim(p_reason),
    approval_delegation_id=v_authority.delegation_id,
    authority_delegator_id=CASE WHEN v_authority.delegation_id IS NULL THEN NULL ELSE v_authority.authority_delegator_id END,
    updated_at=clock_timestamp()
  WHERE id=v_request.id;
  UPDATE public.sicoob_orders SET status='rejected', updated_at=clock_timestamp()
  WHERE id=v_order.id;
  INSERT INTO public.sicoob_manager_audit(manager_id, order_id, action, details)
  VALUES (v_actor_id, v_order.id, 'reject', jsonb_build_object(
    'request_id', v_request.id,
    'reason', btrim(p_reason),
    'policy_version', v_order.approval_policy_version,
    'authority_source', CASE WHEN v_authority.delegation_id IS NULL THEN 'direct' ELSE 'delegated' END,
    'delegation_id', v_authority.delegation_id,
    'authority_delegator_id', CASE WHEN v_authority.delegation_id IS NULL THEN NULL ELSE v_authority.authority_delegator_id END
  ));
END;
$function$

CREATE OR REPLACE FUNCTION public.reject_sicoob_order_without_approval(p_order_id uuid, p_expected_status text, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária.';
  END IF;
  IF length(trim(COALESCE(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe um motivo de rejeição com ao menos 10 caracteres.';
  END IF;

  SELECT * INTO v_order FROM public.sicoob_orders WHERE id = p_order_id FOR UPDATE;
  IF NOT FOUND OR v_order.status IS DISTINCT FROM p_expected_status OR v_order.status <> 'waiting_approval' THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'O pedido mudou ou não está disponível para rejeição.';
  END IF;
  IF EXISTS (SELECT 1 FROM public.sicoob_approval_requests WHERE order_id = v_order.id AND status = 'pending') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Use a rejeição vinculada à solicitação de aprovação pendente.';
  END IF;

  PERFORM public.assert_sicoob_approval_actor(v_actor_id, v_order.id, NULL, false);
  PERFORM set_config('app.sicoob_approval_operation', 'reject', true);
  PERFORM set_config('app.sicoob_order_status_comment', trim(p_reason), true);

  UPDATE public.sicoob_orders
     SET status = 'rejected', updated_at = now()
   WHERE id = v_order.id;

  INSERT INTO public.sicoob_manager_audit (manager_id, order_id, action, details)
  VALUES (v_actor_id, v_order.id, 'reject_without_formal_request', jsonb_build_object('reason', trim(p_reason), 'policy_version', v_order.approval_policy_version));
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_sicoob_order_as_quote_legacy_20260927(p_order_id uuid, p_items jsonb, p_idempotency_key text, p_actor_id uuid, p_request_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := p_actor_id;
  v_order public.sicoob_orders%ROWTYPE;
  v_profile public.profiles%ROWTYPE;
  v_organization_id uuid;
  v_existing public.sicoob_reorder_requests%ROWTYPE;
  v_item jsonb;
  v_personalization jsonb;
  v_source_item public.sicoob_order_items%ROWTYPE;
  v_payload_hash text;
  v_quote_id uuid;
  v_quote_item_id uuid;
  v_sort_order integer := 0;
  v_total numeric(14,2) := 0;
  v_checked_at timestamptz;
  v_pa_name text;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária para refazer o pedido.';
  END IF;

  IF p_idempotency_key IS NULL OR length(trim(p_idempotency_key)) NOT BETWEEN 8 AND 128 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Chave de idempotência inválida.';
  END IF;
  IF COALESCE(p_request_hash, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Identidade da requisição de recompra inválida.';
  END IF;

  IF jsonb_typeof(p_items) IS DISTINCT FROM 'array'
     OR jsonb_array_length(p_items) = 0
     OR jsonb_array_length(p_items) > 100 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A recompra deve conter entre 1 e 100 itens.';
  END IF;

  SELECT * INTO v_order
    FROM public.sicoob_orders
   WHERE id = p_order_id
   FOR SHARE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Pedido de origem não encontrado.';
  END IF;
  IF v_order.status IS DISTINCT FROM 'completed' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Somente pedidos concluídos podem ser refeitos.';
  END IF;

  IF jsonb_array_length(p_items) IS DISTINCT FROM (
       SELECT count(*)::integer FROM public.sicoob_order_items WHERE order_id = v_order.id
     )
     OR jsonb_array_length(p_items) IS DISTINCT FROM (
       SELECT count(DISTINCT item ->> 'source_order_item_id')::integer
         FROM jsonb_array_elements(p_items) AS source(item)
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A recompra deve representar cada item do pedido uma única vez.';
  END IF;

  SELECT * INTO v_profile
    FROM public.profiles
   WHERE user_id = v_actor_id
     AND is_active IS TRUE
     AND deleted_at IS NULL;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O usuário não possui perfil ativo.';
  END IF;

  SELECT om.organization_id INTO v_organization_id
    FROM public.organization_members om
   WHERE om.user_id = v_actor_id
   ORDER BY om.created_at ASC, om.id ASC
   LIMIT 1;

  IF v_order.created_by IS DISTINCT FROM v_actor_id
     AND NOT EXISTS (
       SELECT 1 FROM public.user_roles ur
        WHERE ur.user_id = v_actor_id
          AND ur.role::text IN ('admin', 'dev', 'supervisor')
     )
     AND NOT (
       v_profile.pa_id IS NOT NULL
       AND v_profile.pa_id = v_order.pa_id
       AND EXISTS (
         SELECT 1 FROM public.user_roles ur
          WHERE ur.user_id = v_actor_id
            AND ur.role::text IN ('gerente_pa', 'comprador_pac', 'gestor_compras')
       )
     )
     AND NOT (
       v_profile.cooperativa_id IS NOT NULL
       AND v_profile.cooperativa_id = v_order.cooperative_id
       AND EXISTS (
         SELECT 1 FROM public.user_roles ur
          WHERE ur.user_id = v_actor_id
            AND ur.role::text IN ('comprador_singular', 'gestor_compras')
       )
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode refazer este pedido.';
  END IF;

  v_payload_hash := p_request_hash;
  PERFORM pg_advisory_xact_lock(
    hashtextextended(v_actor_id::text || ':' || p_order_id::text || ':' || trim(p_idempotency_key), 0)
  );

  SELECT * INTO v_existing
    FROM public.sicoob_reorder_requests
   WHERE actor_id = v_actor_id
     AND source_order_id = p_order_id
     AND idempotency_key = trim(p_idempotency_key);
  IF FOUND THEN
    IF v_existing.payload_hash IS DISTINCT FROM v_payload_hash THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com conteúdo diferente.';
    END IF;
    RETURN v_existing.quote_id;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    IF NULLIF(v_item ->> 'source_order_item_id', '') IS NULL
       OR NULLIF(v_item ->> 'product_id', '') IS NULL
       OR NULLIF(trim(v_item ->> 'product_name'), '') IS NULL
       OR COALESCE((v_item ->> 'quantity')::integer, 0) <= 0
       OR COALESCE((v_item ->> 'unit_price')::numeric, 0) <= 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Item de recompra inválido.';
    END IF;

    SELECT * INTO v_source_item
      FROM public.sicoob_order_items
     WHERE id = (v_item ->> 'source_order_item_id')::uuid
       AND order_id = v_order.id;
    IF NOT FOUND
       OR v_source_item.product_id::text IS DISTINCT FROM (v_item ->> 'product_id')
       OR v_source_item.quantity IS DISTINCT FROM (v_item ->> 'quantity')::integer THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O item não corresponde ao pedido de origem.';
    END IF;

    v_checked_at := NULLIF(v_item ->> 'catalog_checked_at', '')::timestamptz;
    IF v_checked_at IS NULL
       OR v_checked_at < now() - interval '5 minutes'
       OR v_checked_at > now() + interval '1 minute' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Preço e estoque precisam ser consultados novamente.';
    END IF;

    IF COALESCE((v_item ->> 'minimum_quantity')::integer, 1) > (v_item ->> 'quantity')::integer THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Quantidade abaixo do mínimo vigente do produto.';
    END IF;

    IF v_source_item.variant_id IS NOT NULL
       AND v_source_item.variant_id IS DISTINCT FROM NULLIF(v_item ->> 'source_variant_id', '')::uuid THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A variante não corresponde ao pedido de origem.';
    END IF;

    v_total := v_total + ((v_item ->> 'quantity')::integer * (v_item ->> 'unit_price')::numeric);
    IF jsonb_typeof(COALESCE(v_item -> 'personalizations', '[]'::jsonb)) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Personalização revalidada inválida.';
    END IF;
    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      IF NULLIF(v_personalization ->> 'technique_id', '') IS NULL
         OR NULLIF(trim(v_personalization ->> 'technique_name'), '') IS NULL
         OR COALESCE((v_personalization ->> 'colors_count')::integer, 0) <= 0
         OR (v_personalization ->> 'personalized_quantity')::integer IS DISTINCT FROM (v_item ->> 'quantity')::integer
         OR COALESCE((v_personalization ->> 'unit_cost')::numeric, 0) <= 0
         OR COALESCE((v_personalization ->> 'setup_cost')::numeric, 0) < 0
         OR COALESCE((v_personalization ->> 'total_cost')::numeric, 0) <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Personalização revalidada inválida.';
      END IF;
      v_checked_at := NULLIF(v_personalization ->> 'catalog_checked_at', '')::timestamptz;
      IF v_checked_at IS NULL
         OR v_checked_at < now() - interval '5 minutes'
         OR v_checked_at > now() + interval '1 minute' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O preço da personalização precisa ser consultado novamente.';
      END IF;
      v_total := v_total + (v_personalization ->> 'total_cost')::numeric;
    END LOOP;
  END LOOP;

  SELECT nome INTO v_pa_name
    FROM public.postos_atendimento
   WHERE id = v_order.pa_id;

  PERFORM set_config('app.sicoob_reorder_operation', 'create', true);
  INSERT INTO public.quotes (
    client_id, client_name, seller_id, status, subtotal, total, notes,
    organization_id, pa_id, singular_id
  ) VALUES (
    NULL,
    COALESCE(v_pa_name, 'Unidade Sicoob'),
    v_actor_id,
    'draft',
    v_total,
    v_total,
    format('Recompra do pedido Sicoob #%s. Preço e estoque revalidados antes da criação.', COALESCE(v_order.id::text, '')),
    v_organization_id,
    v_order.pa_id,
    v_order.cooperative_id
  )
  RETURNING id INTO v_quote_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, color_name, color_hex, size_code,
      source_variant_id, source_variant_sku, catalog_checked_at, sort_order
    ) VALUES (
      v_quote_id,
      v_item ->> 'product_id',
      v_item ->> 'product_name',
      NULLIF(v_item ->> 'product_sku', ''),
      NULLIF(v_item ->> 'product_image_url', ''),
      (v_item ->> 'quantity')::integer,
      (v_item ->> 'unit_price')::numeric,
      NULLIF(v_item ->> 'color_name', ''),
      NULLIF(v_item ->> 'color_hex', ''),
      NULLIF(v_item ->> 'size_code', ''),
      NULLIF(v_item ->> 'source_variant_id', ''),
      NULLIF(v_item ->> 'source_variant_sku', ''),
      (v_item ->> 'catalog_checked_at')::timestamptz,
      v_sort_order
    ) RETURNING id INTO v_quote_item_id;

    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name, colors_count,
        width_cm, height_cm, personalized_quantity, unit_cost,
        setup_cost, total_cost, notes, catalog_checked_at
      ) VALUES (
        v_quote_item_id,
        v_personalization ->> 'technique_id',
        v_personalization ->> 'technique_name',
        (v_personalization ->> 'colors_count')::integer,
        NULLIF(v_personalization ->> 'width_cm', '')::numeric,
        NULLIF(v_personalization ->> 'height_cm', '')::numeric,
        (v_personalization ->> 'personalized_quantity')::integer,
        (v_personalization ->> 'unit_cost')::numeric,
        (v_personalization ->> 'setup_cost')::numeric,
        (v_personalization ->> 'total_cost')::numeric,
        concat_ws(' ',
          CASE WHEN NULLIF(v_personalization ->> 'position', '') IS NOT NULL
            THEN format('Posição: %s.', v_personalization ->> 'position') END,
          'Arte precisa ser reenviada e aprovada para esta recompra.'
        ),
        (v_personalization ->> 'catalog_checked_at')::timestamptz
      );
    END LOOP;
    v_sort_order := v_sort_order + 1;
  END LOOP;

  INSERT INTO public.sicoob_reorder_requests (
    actor_id, source_order_id, idempotency_key, payload_hash, quote_id
  ) VALUES (
    v_actor_id, p_order_id, trim(p_idempotency_key), v_payload_hash, v_quote_id
  );

  RETURN v_quote_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.reorder_sicoob_quote_as_quote(p_quote_id uuid, p_items jsonb, p_idempotency_key text, p_actor_id uuid, p_request_hash text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_source public.quotes%ROWTYPE;
  v_existing public.sicoob_quote_reorder_requests%ROWTYPE;
  v_item jsonb;
  v_source_item public.quote_items%ROWTYPE;
  v_quote_id uuid;
  v_quote_item_id uuid;
  v_personalization jsonb;
  v_total numeric(14,2) := 0;
  v_sort_order integer := 0;
  v_valid_until timestamptz;
BEGIN
  IF p_actor_id IS NULL OR p_quote_id IS NULL
     OR length(trim(COALESCE(p_idempotency_key, ''))) NOT BETWEEN 8 AND 128
     OR COALESCE(p_request_hash, '') !~ '^[0-9a-f]{64}$' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Parâmetros de recompra inválidos.';
  END IF;
  v_valid_until := public.sicoob_assert_current_reorder_items(p_items);

  SELECT * INTO v_source FROM public.quotes q WHERE q.id = p_quote_id FOR SHARE;
  IF NOT FOUND OR v_source.status::text NOT IN ('approved', 'approved_singular', 'converted')
     OR COALESCE(v_source.is_latest_version, true) IS NOT TRUE
     OR v_source.deleted_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Somente orçamento aprovado e vigente pode iniciar uma recompra.';
  END IF;
  IF v_source.seller_id IS DISTINCT FROM p_actor_id
     AND NOT public.can_manage_quote_scope(p_actor_id, p_quote_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode refazer este orçamento.';
  END IF;
  IF NOT EXISTS (
    SELECT 1 FROM public.profiles
    WHERE user_id = p_actor_id AND is_active IS TRUE AND deleted_at IS NULL
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O usuário não possui perfil ativo.';
  END IF;
  IF jsonb_array_length(p_items) IS DISTINCT FROM (
       SELECT count(*)::integer FROM public.quote_items WHERE quote_id = p_quote_id
     ) OR jsonb_array_length(p_items) IS DISTINCT FROM (
       SELECT count(DISTINCT item ->> 'source_order_item_id')::integer
       FROM jsonb_array_elements(p_items) source(item)
     ) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A recompra deve representar cada item do orçamento uma única vez.';
  END IF;

  PERFORM pg_advisory_xact_lock(hashtextextended(
    p_actor_id::text || ':' || p_quote_id::text || ':' || trim(p_idempotency_key), 0
  ));
  SELECT * INTO v_existing FROM public.sicoob_quote_reorder_requests
  WHERE actor_id = p_actor_id AND source_quote_id = p_quote_id
    AND idempotency_key = trim(p_idempotency_key);
  IF FOUND THEN
    IF v_existing.payload_hash IS DISTINCT FROM p_request_hash THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com conteúdo diferente.';
    END IF;
    RETURN v_existing.quote_id;
  END IF;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    SELECT * INTO v_source_item FROM public.quote_items
    WHERE id = (v_item ->> 'source_order_item_id')::uuid AND quote_id = p_quote_id;
    IF NOT FOUND
       OR v_source_item.product_id IS DISTINCT FROM (v_item ->> 'product_id')
       OR v_source_item.quantity IS DISTINCT FROM (v_item ->> 'quantity')::integer
       OR NULLIF(v_source_item.source_variant_id, '') IS DISTINCT FROM NULLIF(v_item ->> 'source_variant_id', '') THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O item não corresponde ao orçamento de origem.';
    END IF;
    v_total := v_total + (v_item ->> 'quantity')::integer * (v_item ->> 'unit_price')::numeric;
    SELECT v_total + COALESCE(sum((personalization ->> 'total_cost')::numeric), 0)
      INTO v_total
      FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb)) source(personalization);
  END LOOP;

  PERFORM set_config('app.sicoob_reorder_operation', 'create', true);
  INSERT INTO public.quotes (
    client_id, client_name, client_email, client_phone, client_company, client_cnpj,
    seller_id, status, subtotal, total, notes, organization_id, pa_id, singular_id,
    payment_terms, delivery_time, shipping_type, shipping_cost, valid_until,
    reorder_source_quote_id, catalog_revalidated_at, catalog_valid_until,
    catalog_stock_is_reserved, reorder_price_changed_items
  ) VALUES (
    v_source.client_id, v_source.client_name, v_source.client_email, v_source.client_phone,
    v_source.client_company, v_source.client_cnpj, p_actor_id, 'draft', v_total, v_total,
    format('Recompra do orçamento Sicoob #%s. Preço, mínimo e estoque reconsultados; disponibilidade não reservada.', v_source.quote_number),
    v_source.organization_id, v_source.pa_id, v_source.singular_id,
    v_source.payment_terms, v_source.delivery_time, v_source.shipping_type, v_source.shipping_cost,
    CURRENT_DATE + 7, p_quote_id, statement_timestamp(), v_valid_until, false,
    (SELECT count(*) FROM jsonb_array_elements(p_items) source(item)
     WHERE COALESCE((item ->> 'price_changed')::boolean, false))
  ) RETURNING id INTO v_quote_id;

  FOR v_item IN SELECT value FROM jsonb_array_elements(p_items)
  LOOP
    INSERT INTO public.quote_items (
      quote_id, product_id, product_name, product_sku, product_image_url,
      quantity, unit_price, color_name, color_hex, size_code,
      source_variant_id, source_variant_sku, catalog_checked_at, sort_order,
      catalog_available_stock, catalog_minimum_quantity, catalog_valid_until,
      historical_unit_price, price_changed, catalog_stock_is_reserved
    ) VALUES (
      v_quote_id, v_item ->> 'product_id', v_item ->> 'product_name',
      NULLIF(v_item ->> 'product_sku', ''), NULLIF(v_item ->> 'product_image_url', ''),
      (v_item ->> 'quantity')::integer, (v_item ->> 'unit_price')::numeric,
      NULLIF(v_item ->> 'color_name', ''), NULLIF(v_item ->> 'color_hex', ''),
      NULLIF(v_item ->> 'size_code', ''), NULLIF(v_item ->> 'source_variant_id', ''),
      NULLIF(v_item ->> 'source_variant_sku', ''), (v_item ->> 'catalog_checked_at')::timestamptz,
      v_sort_order, (v_item ->> 'available_stock')::integer,
      (v_item ->> 'minimum_quantity')::integer, (v_item ->> 'catalog_valid_until')::timestamptz,
      NULLIF(v_item ->> 'historical_unit_price', '')::numeric,
      COALESCE((v_item ->> 'price_changed')::boolean, false), false
    ) RETURNING id INTO v_quote_item_id;

    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name, colors_count, width_cm, height_cm,
        personalized_quantity, unit_cost, setup_cost, total_cost, notes, catalog_checked_at
      ) VALUES (
        v_quote_item_id, v_personalization ->> 'technique_id', v_personalization ->> 'technique_name',
        (v_personalization ->> 'colors_count')::integer,
        NULLIF(v_personalization ->> 'width_cm', '')::numeric,
        NULLIF(v_personalization ->> 'height_cm', '')::numeric,
        (v_personalization ->> 'personalized_quantity')::integer,
        (v_personalization ->> 'unit_cost')::numeric,
        (v_personalization ->> 'setup_cost')::numeric,
        (v_personalization ->> 'total_cost')::numeric,
        'Arte histórica copiada como referência; exige nova validação de marca.',
        (v_personalization ->> 'catalog_checked_at')::timestamptz
      );
    END LOOP;
    v_sort_order := v_sort_order + 1;
  END LOOP;

  INSERT INTO public.sicoob_quote_reorder_requests (
    actor_id, source_quote_id, idempotency_key, payload_hash, quote_id
  ) VALUES (p_actor_id, p_quote_id, trim(p_idempotency_key), p_request_hash, v_quote_id);

  INSERT INTO public.quote_history (quote_id, user_id, action, description, metadata)
  VALUES (
    v_quote_id, p_actor_id, 'created', 'Recompra criada com nova consulta ao catálogo.',
    jsonb_build_object(
      'source_quote_id', p_quote_id,
      'catalog_valid_until', v_valid_until,
      'stock_is_reserved', false
    )
  );
  RETURN v_quote_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.repair_ownership_orphans(_report_id uuid DEFAULT NULL::uuid, _dry_run boolean DEFAULT true, _triggered_by_label text DEFAULT 'manual_admin'::text)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_caller uuid := auth.uid();
  v_report record;
  v_detail jsonb;
  v_table text;
  v_col text;
  v_null_count bigint;
  v_orphan_count bigint;
  v_action text;
  v_rows int;
  v_results jsonb := '[]'::jsonb;
  v_total_deleted int := 0;
  v_total_deactivated int := 0;
  v_total_manual int := 0;
  -- Tabelas onde apagar é seguro (logs/efêmeros)
  v_safe_delete text[] := ARRAY[
    'workspace_notifications', 'rls_denial_log',
    'mcp_audit_log', 'mcp_keys_audit_log',
    'role_migration_audit', 'login_attempts'
  ];
  v_has_active boolean;
  v_has_is_active boolean;
  v_has_status boolean;
BEGIN
  -- Permissão
  IF v_caller IS NULL OR NOT (
    has_role(v_caller, 'admin'::app_role) OR has_role(v_caller, 'dev'::app_role)
  ) THEN
    RAISE EXCEPTION 'repair_ownership_orphans: acesso negado';
  END IF;

  -- Pega o relatório (último por padrão)
  IF _report_id IS NULL THEN
    SELECT * INTO v_report
    FROM public.ownership_audit_reports
    ORDER BY generated_at DESC LIMIT 1;
  ELSE
    SELECT * INTO v_report
    FROM public.ownership_audit_reports WHERE id = _report_id;
  END IF;

  IF v_report.id IS NULL THEN
    RAISE EXCEPTION 'repair_ownership_orphans: nenhum relatório encontrado';
  END IF;

  -- Itera detalhes
  FOR v_detail IN SELECT * FROM jsonb_array_elements(v_report.details)
  LOOP
    v_table := v_detail->>'table';
    v_col := v_detail->>'owner_column';
    v_null_count := COALESCE((v_detail->>'null_owner_count')::bigint, 0);
    v_orphan_count := COALESCE((v_detail->>'missing_user_count')::bigint, 0);

    -- Detecta colunas auxiliares disponíveis na tabela
    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='active')
      INTO v_has_active;
    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='is_active')
      INTO v_has_is_active;
    SELECT EXISTS(SELECT 1 FROM information_schema.columns
      WHERE table_schema='public' AND table_name=v_table AND column_name='status')
      INTO v_has_status;

    --- (1) NULL OWNERS ---
    IF v_null_count > 0 THEN
      v_action := 'manual_review';
      v_rows := 0;

      IF v_table = ANY(v_safe_delete) THEN
        v_action := 'deleted';
        IF NOT _dry_run THEN
          EXECUTE format('DELETE FROM public.%I WHERE %I IS NULL', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deleted := v_total_deleted + v_rows;
      ELSIF v_has_is_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format('UPDATE public.%I SET is_active=false WHERE %I IS NULL AND is_active=true', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format('UPDATE public.%I SET active=false WHERE %I IS NULL AND active=true', v_table, v_col);
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_status THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I SET status=''inactive'' WHERE %I IS NULL AND status<>''inactive''',
            v_table, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_null_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSE
        v_rows := v_null_count::int;
        v_total_manual := v_total_manual + v_rows;
      END IF;

      INSERT INTO public.ownership_repair_logs(
        report_id, table_name, owner_column, issue_type, action,
        rows_affected, dry_run, triggered_by, triggered_by_label,
        notes
      ) VALUES (
        v_report.id, v_table, v_col, 'null_owner', v_action,
        v_rows, _dry_run, v_caller, _triggered_by_label,
        CASE WHEN v_action='manual_review'
          THEN 'Sem coluna active/is_active/status; tabela não está na allowlist de exclusão segura'
          ELSE NULL END
      );

      v_results := v_results || jsonb_build_object(
        'table', v_table, 'owner_column', v_col,
        'issue', 'null_owner', 'action', v_action,
        'rows_affected', v_rows, 'dry_run', _dry_run
      );
    END IF;

    --- (2) MISSING USERS (órfãos) ---
    IF v_orphan_count > 0 THEN
      v_action := 'manual_review';
      v_rows := 0;

      IF v_table = ANY(v_safe_delete) THEN
        v_action := 'deleted';
        IF NOT _dry_run THEN
          EXECUTE format(
            'DELETE FROM public.%I t WHERE t.%I IS NOT NULL
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deleted := v_total_deleted + v_rows;
      ELSIF v_has_is_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET is_active=false WHERE t.%I IS NOT NULL AND t.is_active=true
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_active THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET active=false WHERE t.%I IS NOT NULL AND t.active=true
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSIF v_has_status THEN
        v_action := 'deactivated';
        IF NOT _dry_run THEN
          EXECUTE format(
            'UPDATE public.%I t SET status=''inactive'' WHERE t.%I IS NOT NULL AND t.status<>''inactive''
              AND NOT EXISTS (SELECT 1 FROM auth.users u WHERE u.id = t.%I::uuid)',
            v_table, v_col, v_col
          );
          GET DIAGNOSTICS v_rows = ROW_COUNT;
        ELSE
          v_rows := v_orphan_count::int;
        END IF;
        v_total_deactivated := v_total_deactivated + v_rows;
      ELSE
        v_rows := v_orphan_count::int;
        v_total_manual := v_total_manual + v_rows;
      END IF;

      INSERT INTO public.ownership_repair_logs(
        report_id, table_name, owner_column, issue_type, action,
        rows_affected, dry_run, triggered_by, triggered_by_label,
        notes
      ) VALUES (
        v_report.id, v_table, v_col, 'missing_user', v_action,
        v_rows, _dry_run, v_caller, _triggered_by_label,
        CASE WHEN v_action='manual_review'
          THEN 'Sem coluna active/is_active/status; reparo automático inseguro — revisar manualmente'
          ELSE NULL END
      );

      v_results := v_results || jsonb_build_object(
        'table', v_table, 'owner_column', v_col,
        'issue', 'missing_user', 'action', v_action,
        'rows_affected', v_rows, 'dry_run', _dry_run
      );
    END IF;
  END LOOP;

  RETURN jsonb_build_object(
    'report_id', v_report.id,
    'dry_run', _dry_run,
    'totals', jsonb_build_object(
      'deleted', v_total_deleted,
      'deactivated', v_total_deactivated,
      'manual_review', v_total_manual
    ),
    'actions', v_results
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.request_discount_approval_atomic(p_quote_id uuid, p_expected_quote_row_version integer, p_requested_discount_percent numeric, p_seller_notes text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, quote_id uuid, seller_id uuid, quote_row_version integer, requested_discount_percent numeric, max_allowed_percent numeric, negotiation_markup_percent numeric, real_discount_percent numeric)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_quote public.quotes%ROWTYPE;
  v_request public.discount_approval_requests%ROWTYPE;
  v_updated public.quotes%ROWTYPE;
  v_max_allowed_percent numeric;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação necessária.';
  END IF;
  IF p_expected_quote_row_version IS NULL
     OR p_requested_discount_percent IS NULL
     OR p_requested_discount_percent < 0
     OR p_requested_discount_percent > 100 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Parâmetros de aprovação inválidos.';
  END IF;

  SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Orçamento não encontrado.';
  END IF;
  IF v_quote.seller_id IS DISTINCT FROM v_actor_id
     OR v_quote.row_version IS DISTINCT FROM p_expected_quote_row_version
     OR v_quote.status::text NOT IN ('draft', 'pending') THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'O orçamento não pode solicitar aprovação neste estado.';
  END IF;
  IF p_requested_discount_percent IS DISTINCT FROM v_quote.real_discount_percent THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O percentual solicitado deve corresponder ao desconto real do orçamento.';
  END IF;

  SELECT max_discount_percent INTO v_max_allowed_percent
  FROM public.seller_discount_limits
  WHERE user_id = v_actor_id;
  IF v_max_allowed_percent IS NULL OR v_max_allowed_percent < 0 OR v_max_allowed_percent > 100 THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Limite de desconto do vendedor não configurado.';
  END IF;
  IF p_requested_discount_percent <= v_max_allowed_percent THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O desconto não exige aprovação adicional.';
  END IF;

  INSERT INTO public.discount_approval_requests (
    quote_id, seller_id, requested_discount_percent, max_allowed_percent,
    seller_notes, requested_quote_row_version, requested_real_discount_percent
  ) VALUES (
    p_quote_id, v_actor_id, p_requested_discount_percent, v_max_allowed_percent,
    p_seller_notes, v_quote.row_version, v_quote.real_discount_percent
  ) RETURNING * INTO v_request;

  PERFORM set_config('app.quote_governance_write', 'true', true);
  UPDATE public.quotes
  SET status = 'pending_approval', row_version = row_version + 1, updated_at = now()
  WHERE id = p_quote_id
  RETURNING * INTO v_updated;

  INSERT INTO public.quote_history (
    quote_id, user_id, action, description, field_changed, old_value, new_value, metadata
  ) VALUES (
    p_quote_id, v_actor_id, 'discount_approval_requested',
    format('Solicitação de desconto real de %s%%', p_requested_discount_percent),
    'status', v_quote.status::text, 'pending_approval',
    jsonb_build_object('request_id', v_request.id, 'max_allowed_percent', v_max_allowed_percent,
      'requested_quote_row_version', v_quote.row_version,
      'requested_real_discount_percent', v_quote.real_discount_percent)
  );

  RETURN QUERY SELECT v_request.id, v_updated.id, v_request.seller_id,
    v_updated.row_version, v_request.requested_discount_percent,
    v_request.max_allowed_percent, v_quote.negotiation_markup_percent,
    v_quote.real_discount_percent;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_sicoob_order_approval(p_order_id uuid, p_expected_status text, p_reason text, p_threshold numeric, p_is_escalated boolean DEFAULT false)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_order public.sicoob_orders%ROWTYPE;
  v_target_status text := CASE WHEN p_is_escalated THEN 'escalated_to_board' ELSE 'waiting_approval' END;
  v_threshold numeric;
  v_request_id uuid;
  v_comment text;
  v_policy record;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário não autenticado.';
  END IF;
  IF length(trim(COALESCE(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe uma justificativa com ao menos 10 caracteres.';
  END IF;
  IF (NOT p_is_escalated AND trim(COALESCE(p_expected_status, '')) <> 'pending')
    OR (p_is_escalated AND trim(COALESCE(p_expected_status, '')) <> 'waiting_approval') THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O status atual não permite esta solicitação de aprovação.';
  END IF;

  SELECT * INTO v_order
    FROM public.sicoob_orders
   WHERE id = p_order_id
   FOR UPDATE;

  IF NOT FOUND OR v_order.status IS DISTINCT FROM trim(p_expected_status) THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'O pedido mudou ou não está disponível; atualize a página e tente novamente.';
  END IF;
  IF NOT public.sicoob_actor_can_request_approval(v_actor_id, v_order.id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário fora do escopo do pedido.';
  END IF;

  SELECT limite_alcada INTO v_threshold
    FROM public.pa_budgets
   WHERE pa_id = v_order.pa_id
     AND ano = EXTRACT(YEAR FROM v_order.created_at)::integer
     AND mes = EXTRACT(MONTH FROM v_order.created_at)::integer;

  IF v_threshold IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A alçada do PA não está configurada para o período do pedido.';
  END IF;

  SELECT * INTO v_policy FROM public.get_sicoob_order_approval_policy(v_order.id);
  v_comment := format(
    'Solicitação de aprovação%s: %s',
    CASE WHEN p_is_escalated THEN ' para a Diretoria' ELSE '' END,
    trim(p_reason)
  );
  PERFORM set_config('app.sicoob_approval_operation', CASE WHEN p_is_escalated THEN 'escalate' ELSE 'request' END, true);
  PERFORM set_config('app.sicoob_order_status_comment', v_comment, true);

  IF p_is_escalated THEN
    SELECT id INTO v_request_id
      FROM public.sicoob_approval_requests
     WHERE order_id = v_order.id AND status = 'pending'
     FOR UPDATE;

    IF v_request_id IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'A escalação exige uma solicitação de aprovação pendente.';
    END IF;

    UPDATE public.sicoob_approval_requests
       SET metadata = COALESCE(metadata, '{}'::jsonb) || jsonb_build_object(
             'escalated', true,
             'level', 'board',
             'escalation_reason', trim(p_reason),
             'approval_policy_version', v_policy.policy_version,
             'client_threshold', p_threshold,
             'resolved_threshold', v_threshold
           ),
           updated_at = now()
     WHERE id = v_request_id;
  ELSIF EXISTS (
    SELECT 1 FROM public.sicoob_approval_requests
     WHERE order_id = v_order.id AND status = 'pending'
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O pedido já possui uma solicitação de aprovação pendente.';
  ELSE
    INSERT INTO public.sicoob_approval_requests (
      order_id,
      requester_id,
      request_reason,
      amount_at_request,
      threshold_at_request,
      status,
      metadata
    ) VALUES (
      v_order.id,
      v_actor_id,
      trim(p_reason),
      COALESCE(v_order.total_amount, 0),
      v_threshold,
      'pending',
      jsonb_build_object(
        'escalated', false,
        'level', 'manager',
        'approval_policy_version', v_policy.policy_version,
        'client_threshold', p_threshold,
        'resolved_threshold', v_threshold
      )
    )
    RETURNING id INTO v_request_id;
  END IF;

  UPDATE public.sicoob_orders
     SET status = v_target_status,
         approval_policy_id = COALESCE(v_order.approval_policy_id, v_policy.policy_id),
         approval_policy_version = COALESCE(v_order.approval_policy_version, v_policy.policy_version),
         updated_at = now()
   WHERE id = v_order.id;

  RETURN v_request_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.request_step_up_challenge(_action step_up_action, _target_ref text DEFAULT NULL::text, _ip inet DEFAULT NULL::inet, _user_agent text DEFAULT NULL::text)
 RETURNS TABLE(challenge_id uuid, otp_plain text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid UUID := auth.uid();
  _otp TEXT;
  _otp_h TEXT;
  _cid UUID;
  _exp TIMESTAMPTZ;
  _recent_count INT;
BEGIN
  IF _uid IS NULL THEN
    RAISE EXCEPTION 'unauthorized: no session';
  END IF;

  -- Apenas dev pode solicitar step-up para essas ações
  IF NOT public.is_dev(_uid) THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, ip_address, user_agent)
    VALUES (_uid, _action, _target_ref, 'unauthorized', _ip, _user_agent);
    RAISE EXCEPTION 'forbidden: dev role required';
  END IF;

  -- Rate limit: máx 5 challenges por usuário por hora
  SELECT count(*) INTO _recent_count
  FROM public.step_up_challenges
  WHERE user_id = _uid AND created_at > (now() - interval '1 hour');

  IF _recent_count >= 5 THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, ip_address, user_agent)
    VALUES (_uid, _action, _target_ref, 'rate_limited', _ip, _user_agent);
    RAISE EXCEPTION 'rate_limited: too many step-up requests';
  END IF;

  -- Gera OTP de 6 dígitos
  _otp := lpad((floor(random() * 1000000))::int::text, 6, '0');
  _otp_h := encode(extensions.digest(_otp || _uid::text, 'sha256'), 'hex');
  _exp := now() + interval '5 minutes';

  INSERT INTO public.step_up_challenges(user_id, action, target_ref, otp_hash, expires_at, ip_address, user_agent)
  VALUES (_uid, _action, _target_ref, _otp_h, _exp, _ip, _user_agent)
  RETURNING id INTO _cid;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, ip_address, user_agent)
  VALUES (_uid, _action, _target_ref, 'challenge_requested', _cid, _ip, _user_agent);

  RETURN QUERY SELECT _cid, _otp, _exp;
END;
$function$

CREATE OR REPLACE FUNCTION public.reset_optimization_queue(_only_running boolean DEFAULT true)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  affected int;
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin') THEN
    RAISE EXCEPTION 'forbidden';
  END IF;

  IF _only_running THEN
    UPDATE public.optimization_queue
       SET status = 'pending', started_at = NULL
     WHERE status = 'running';
  ELSE
    UPDATE public.optimization_queue
       SET status = 'pending', started_at = NULL, finished_at = NULL, error = NULL
     WHERE status IN ('running','failed','blocked');
  END IF;

  GET DIAGNOSTICS affected = ROW_COUNT;
  RETURN affected;
END;
$function$

CREATE OR REPLACE FUNCTION public.resolve_sicoob_approval_authority(p_actor_id uuid, p_order_id uuid, p_requester_id uuid, p_board_only boolean, p_competence text)
 RETURNS TABLE(delegation_id uuid, authority_delegator_id uuid)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_order public.sicoob_orders%ROWTYPE;
  v_policy record;
BEGIN
  IF p_competence NOT IN ('approve_order', 'reject_order') THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Competência de aprovação inválida.';
  END IF;
  SELECT * INTO v_order FROM public.sicoob_orders WHERE id=p_order_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Pedido não encontrado.';
  END IF;
  SELECT * INTO v_policy FROM public.get_sicoob_order_approval_policy(p_order_id);

  IF public.sicoob_actor_can_approve(p_actor_id, p_order_id, p_board_only) THEN
    PERFORM public.assert_sicoob_approval_actor(
      p_actor_id, p_order_id, p_requester_id, p_board_only
    );
    RETURN QUERY SELECT NULL::uuid, p_actor_id;
    RETURN;
  END IF;

  RETURN QUERY
  SELECT delegation.id, delegation.delegator_id
  FROM public.sicoob_approval_delegations delegation
  JOIN public.profiles delegate_profile
    ON delegate_profile.user_id=p_actor_id OR delegate_profile.id=p_actor_id
  WHERE delegation.delegate_id=p_actor_id
    AND delegation.revoked_at IS NULL
    AND delegation.starts_at <= statement_timestamp()
    AND delegation.ends_at > statement_timestamp()
    AND p_competence=ANY(delegation.competencies)
    AND delegation.cooperative_id=v_order.cooperative_id
    AND (delegation.pa_id IS NULL OR delegation.pa_id=v_order.pa_id)
    AND delegate_profile.is_active IS TRUE
    AND delegate_profile.deleted_at IS NULL
    AND delegate_profile.cooperativa_id=delegation.cooperative_id
    AND (delegation.pa_id IS NULL OR delegate_profile.pa_id=delegation.pa_id)
    AND public.sicoob_actor_can_approve(
      delegation.delegator_id, p_order_id, p_board_only
    )
    AND (
      NOT v_policy.forbid_self_approval
      OR (
        v_order.created_by NOT IN (p_actor_id, delegation.delegator_id)
        AND p_requester_id NOT IN (p_actor_id, delegation.delegator_id)
      )
    )
  ORDER BY delegation.ends_at, delegation.id
  LIMIT 1
  FOR SHARE OF delegation;

  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Ator sem autoridade própria ou delegação vigente para esta decisão.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.respond_discount_approval_atomic(p_request_id uuid, p_expected_quote_row_version integer, p_approved boolean, p_admin_notes text DEFAULT NULL::text)
 RETURNS TABLE(request_id uuid, quote_id uuid, seller_id uuid, quote_row_version integer, requested_discount_percent numeric, max_allowed_percent numeric, request_status text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_request public.discount_approval_requests%ROWTYPE;
  v_quote public.quotes%ROWTYPE;
  v_updated public.quotes%ROWTYPE;
  v_new_status text := CASE WHEN p_approved THEN 'pending' ELSE 'draft' END;
BEGIN
  IF v_actor_id IS NULL OR p_expected_quote_row_version IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Autenticação e versão esperada são obrigatórias.';
  END IF;

  SELECT * INTO v_request FROM public.discount_approval_requests WHERE id = p_request_id;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Solicitação de desconto não encontrada.';
  END IF;
  SELECT * INTO v_quote FROM public.quotes WHERE id = v_request.quote_id FOR UPDATE;
  IF NOT FOUND OR NOT public.can_manage_quote_scope(v_actor_id, v_request.quote_id) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Sem alçada para responder esta solicitação.';
  END IF;
  SELECT * INTO v_request FROM public.discount_approval_requests WHERE id = p_request_id FOR UPDATE;
  IF v_request.status <> 'pending'
     OR v_quote.status::text <> 'pending_approval'
     OR v_quote.row_version IS DISTINCT FROM p_expected_quote_row_version
     OR v_quote.real_discount_percent IS DISTINCT FROM v_request.requested_real_discount_percent
     OR v_request.requested_quote_row_version + 1 IS DISTINCT FROM v_quote.row_version THEN
    RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'A solicitação não corresponde mais ao orçamento atual.';
  END IF;

  UPDATE public.discount_approval_requests
  SET status = CASE WHEN p_approved THEN 'approved' ELSE 'rejected' END,
      admin_id = v_actor_id, admin_notes = p_admin_notes, responded_at = now(),
      approved_quote_row_version = CASE WHEN p_approved THEN v_quote.row_version + 1 ELSE NULL END,
      updated_at = now()
  WHERE id = p_request_id;

  PERFORM set_config('app.quote_governance_write', 'true', true);
  PERFORM set_config('app.quote_discount_approval_commit', 'true', true);
  UPDATE public.quotes
  SET status = v_new_status::public.quote_status, row_version = row_version + 1, updated_at = now()
  WHERE id = v_quote.id
  RETURNING * INTO v_updated;

  INSERT INTO public.quote_history (
    quote_id, user_id, action, description, field_changed, old_value, new_value, metadata
  ) VALUES (
    v_quote.id, v_actor_id,
    CASE WHEN p_approved THEN 'discount_approved' ELSE 'discount_rejected' END,
    CASE WHEN p_approved THEN 'Desconto aprovado pelo responsável' ELSE 'Desconto rejeitado pelo responsável' END,
    'status', 'pending_approval', v_new_status,
    jsonb_build_object('request_id', v_request.id, 'admin_notes', p_admin_notes)
  );

  RETURN QUERY SELECT v_request.id, v_updated.id, v_request.seller_id,
    v_updated.row_version, v_request.requested_discount_percent,
    v_request.max_allowed_percent, CASE WHEN p_approved THEN 'approved' ELSE 'rejected' END;
END;
$function$

CREATE OR REPLACE FUNCTION public.retry_failed_webhook_deliveries()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_supabase_url text := 'https://nmojwpihnslkssljowjh.supabase.co';
  v_service_key text;
  v_retried int := 0;
  v_skipped int := 0;
  rec record;
  v_max_attempts int;
BEGIN
  -- Busca service role key do vault (se disponível) ou usa o setting
  BEGIN
    v_service_key := current_setting('app.supabase_service_role_key', true);
  EXCEPTION WHEN OTHERS THEN
    v_service_key := NULL;
  END;

  IF v_service_key IS NULL OR v_service_key = '' THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'service_role_key not configured in app.supabase_service_role_key'
    );
  END IF;

  -- Pega a ÚLTIMA tentativa de cada (webhook_id, event, payload_hash) na última hora
  -- Re-dispara apenas se ainda há margem em retry_policy.max_attempts
  FOR rec IN
    WITH latest AS (
      SELECT DISTINCT ON (d.webhook_id, d.event, d.payload_hash)
        d.id, d.webhook_id, d.event, d.payload, d.attempt, d.success
      FROM public.webhook_deliveries d
      WHERE d.delivered_at > now() - interval '1 hour'
      ORDER BY d.webhook_id, d.event, d.payload_hash, d.attempt DESC
    )
    SELECT l.*, w.active, w.retry_policy
    FROM latest l
    JOIN public.outbound_webhooks w ON w.id = l.webhook_id
    WHERE l.success = false AND w.active = true
  LOOP
    v_max_attempts := COALESCE((rec.retry_policy->>'max_attempts')::int, 3);

    IF rec.attempt >= v_max_attempts THEN
      v_skipped := v_skipped + 1;
      CONTINUE;
    END IF;

    PERFORM net.http_post(
      url := v_supabase_url || '/functions/v1/webhook-dispatcher',
      headers := jsonb_build_object(
        'Content-Type', 'application/json',
        'Authorization', 'Bearer ' || v_service_key
      ),
      body := jsonb_build_object(
        'event', rec.event,
        'payload', rec.payload
      )
    );
    v_retried := v_retried + 1;
  END LOOP;

  RETURN jsonb_build_object(
    'ok', true,
    'retried', v_retried,
    'skipped_max_attempts', v_skipped,
    'ran_at', now()
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.retry_own_sicoob_export_job(p_job_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
BEGIN
  IF auth.uid() IS NULL THEN RAISE EXCEPTION 'authentication_required' USING ERRCODE = '42501'; END IF;
  UPDATE public.export_jobs
  SET status = 'pending', attempts = 0, error_message = NULL, updated_at = now()
  WHERE id = p_job_id AND user_id = auth.uid() AND status = 'failed';
  IF NOT FOUND THEN RAISE EXCEPTION 'export_job_not_retryable' USING ERRCODE = '42501'; END IF;
  RETURN true;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_sicoob_approval_delegation(p_delegation_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor uuid := auth.uid();
  v_delegation public.sicoob_approval_delegations%ROWTYPE;
  v_privileged boolean;
BEGIN
  IF v_actor IS NULL OR length(btrim(COALESCE(p_reason, ''))) < 10 THEN
    RAISE EXCEPTION USING ERRCODE='22023', MESSAGE='Informe uma justificativa de revogação com ao menos 10 caracteres.';
  END IF;
  SELECT * INTO v_delegation FROM public.sicoob_approval_delegations
  WHERE id=p_delegation_id FOR UPDATE;
  IF NOT FOUND THEN
    RAISE EXCEPTION USING ERRCODE='P0002', MESSAGE='Delegação não encontrada.';
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles
    WHERE user_id=v_actor AND role::text IN ('admin', 'manager', 'dev', 'supervisor')
  ) INTO v_privileged;
  IF v_delegation.delegator_id <> v_actor AND NOT v_privileged THEN
    RAISE EXCEPTION USING ERRCODE='42501', MESSAGE='Somente o delegante ou a supervisão pode revogar.';
  END IF;
  IF v_delegation.revoked_at IS NOT NULL THEN
    RAISE EXCEPTION USING ERRCODE='23514', MESSAGE='Delegação já revogada.';
  END IF;
  PERFORM set_config('app.sicoob_delegation_operation', 'revoke', true);
  UPDATE public.sicoob_approval_delegations
  SET revoked_at=clock_timestamp(), revoked_by=v_actor, revocation_reason=btrim(p_reason)
  WHERE id=v_delegation.id;
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_sicoob_invitation(p_invitation_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_invitation public.sicoob_invitations%ROWTYPE;
BEGIN
  IF v_actor_id IS NULL OR NULLIF(trim(p_reason), '') IS NULL OR length(trim(p_reason)) < 8 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe uma justificativa com pelo menos oito caracteres.';
  END IF;
  SELECT * INTO v_invitation
    FROM public.sicoob_invitations
   WHERE id = p_invitation_id
   FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Convite não encontrado.'; END IF;
  IF v_invitation.status = 'revoked' AND v_invitation.revoked_by = v_actor_id THEN RETURN; END IF;
  IF v_invitation.status <> 'pending' THEN
    RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'Somente convites pendentes podem ser revogados.';
  END IF;
  IF v_invitation.invited_by <> v_actor_id
     AND NOT public.sicoob_inviter_can_issue(v_actor_id, v_invitation.cooperative_id, v_invitation.role) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode revogar este convite.';
  END IF;
  UPDATE public.sicoob_invitations
     SET status = 'revoked', revoked_by = v_actor_id, revoked_at = now(), updated_at = now()
   WHERE id = v_invitation.id;
  INSERT INTO public.sicoob_invitation_events (
    invitation_id, cooperative_id, action, actor_id, details
  ) VALUES (
    v_invitation.id, v_invitation.cooperative_id, 'revoked', v_actor_id,
    jsonb_build_object('reason', trim(p_reason))
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.revoke_sicoob_user_access(p_user_id uuid, p_reason text)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_target_profile public.profiles%ROWTYPE;
  v_actor_is_platform_admin boolean;
BEGIN
  IF v_actor_id IS NULL OR p_user_id IS NULL OR p_user_id = v_actor_id THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Ator e usuário alvo distintos são obrigatórios.';
  END IF;
  IF NULLIF(trim(p_reason), '') IS NULL OR length(trim(p_reason)) < 8 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Informe uma justificativa com pelo menos oito caracteres.';
  END IF;
  SELECT * INTO v_target_profile
    FROM public.profiles p
   WHERE p.user_id = p_user_id
   FOR UPDATE;
  IF NOT FOUND OR v_target_profile.is_active IS DISTINCT FROM true OR v_target_profile.deleted_at IS NOT NULL THEN
    RETURN;
  END IF;
  SELECT EXISTS (
    SELECT 1 FROM public.user_roles ur
     WHERE ur.user_id = v_actor_id
       AND ur.role IN ('admin'::public.app_role, 'dev'::public.app_role)
  ) AND public.sicoob_actor_is_active(v_actor_id)
  INTO v_actor_is_platform_admin;

  IF NOT v_actor_is_platform_admin AND NOT (
    EXISTS (
      SELECT 1
        FROM public.profiles p
        JOIN public.user_roles ur ON ur.user_id = v_actor_id
       WHERE p.user_id = v_actor_id
         AND p.cooperativa_id = v_target_profile.cooperativa_id
         AND p.is_active IS TRUE
         AND p.deleted_at IS NULL
         AND ur.role IN ('gestor_compras'::public.app_role, 'comprador_singular'::public.app_role)
    )
    AND NOT EXISTS (
      SELECT 1 FROM public.user_roles ur
       WHERE ur.user_id = p_user_id
         AND ur.role NOT IN (
           'vendedor'::public.app_role,
           'gerente_pa'::public.app_role,
           'comprador_pac'::public.app_role
         )
    )
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Você não pode revogar este vínculo.';
  END IF;
  IF EXISTS (
    SELECT 1 FROM public.user_roles ur
     WHERE ur.user_id = p_user_id AND ur.role = 'dev'::public.app_role
  ) AND NOT EXISTS (
    SELECT 1 FROM public.user_roles ur
     WHERE ur.user_id = v_actor_id AND ur.role = 'dev'::public.app_role
  ) THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Somente outro desenvolvedor pode revogar acesso técnico.';
  END IF;

  UPDATE public.profiles
     SET is_active = false, deleted_at = now(), updated_at = now()
   WHERE user_id = p_user_id;
  DELETE FROM public.user_roles WHERE user_id = p_user_id;
  DELETE FROM auth.sessions WHERE user_id = p_user_id;
  UPDATE public.sicoob_invitations
     SET access_revoked_by = v_actor_id,
         access_revoked_at = now(),
         updated_at = now()
   WHERE accepted_by = p_user_id
     AND cooperative_id = v_target_profile.cooperativa_id
     AND access_revoked_at IS NULL;
  INSERT INTO public.sicoob_invitation_events (
    cooperative_id, action, actor_id, target_user_id, details
  ) VALUES (
    v_target_profile.cooperativa_id, 'access_revoked', v_actor_id, p_user_id,
    jsonb_build_object('reason', trim(p_reason), 'pa_id', v_target_profile.pa_id)
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.rotate_quote_approval_evidence_key(p_vault_secret_name text)
 RETURNS uuid
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public', 'vault'
AS $function$
DECLARE v_id uuid; v_secret text;
BEGIN
  IF p_vault_secret_name !~ '^quote_approval_evidence_hmac_v[0-9]+$' THEN
    RAISE EXCEPTION 'Nome de versão de chave inválido.' USING ERRCODE='22023';
  END IF;
  SELECT decrypted_secret INTO v_secret FROM vault.decrypted_secrets
    WHERE name=p_vault_secret_name ORDER BY updated_at DESC LIMIT 1;
  IF v_secret IS NULL OR length(v_secret)<32 THEN
    RAISE EXCEPTION 'A nova chave não existe no Vault ou é curta.' USING ERRCODE='55000';
  END IF;
  LOCK TABLE public.quote_approval_evidence_keys IN EXCLUSIVE MODE;
  IF EXISTS (SELECT 1 FROM public.quote_approval_evidence_keys WHERE vault_secret_name=p_vault_secret_name) THEN
    RAISE EXCEPTION 'Esta versão de chave já foi registrada.' USING ERRCODE='23505';
  END IF;
  UPDATE public.quote_approval_evidence_keys
    SET is_active=false,retired_at=clock_timestamp() WHERE is_active;
  INSERT INTO public.quote_approval_evidence_keys(vault_secret_name,is_active)
    VALUES(p_vault_secret_name,true) RETURNING id INTO v_id;
  RETURN v_id;
END;
$function$

CREATE OR REPLACE FUNCTION public.save_quote_atomic(p_quote jsonb, p_items jsonb, p_quote_id uuid DEFAULT NULL::uuid, p_expected_row_version integer DEFAULT NULL::integer, p_history jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_quote public.quotes%ROWTYPE;
  v_item jsonb;
  v_personalization jsonb;
  v_history_entry jsonb;
  v_ordinal bigint;
  v_item_id uuid;
  v_organization_id uuid;
  v_status text;
  v_quantity integer;
  v_personalized_quantity integer;
  v_unit_price numeric;
  v_unit_cost numeric;
  v_setup_cost numeric;
  v_personalization_unit_cost numeric;
  v_personalization_total numeric;
  v_real_subtotal numeric := 0;
  v_total_cost numeric := 0;
  v_markup numeric;
  v_subtotal numeric;
  v_discount_percent numeric;
  v_discount_amount numeric;
  v_shipping_cost numeric;
  v_total numeric;
  v_action text;
  v_description text;
  v_declared_item_ids uuid[];
  v_seen_item_ids uuid[] := '{}'::uuid[];
  v_pending_deletes integer;
  v_deleted_rows integer;
BEGIN
  IF v_actor_id IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário não autenticado.';
  END IF;
  IF jsonb_typeof(p_quote) IS DISTINCT FROM 'object'
     OR jsonb_typeof(COALESCE(p_items, '[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_typeof(COALESCE(p_history, '[]'::jsonb)) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cabeçalho, itens ou histórico do orçamento são inválidos.';
  END IF;

  v_markup := COALESCE(NULLIF(p_quote ->> 'negotiation_markup_percent', '')::numeric, 0);
  v_discount_percent := COALESCE(NULLIF(p_quote ->> 'discount_percent', '')::numeric, 0);
  v_discount_amount := COALESCE(NULLIF(p_quote ->> 'discount_amount', '')::numeric, 0);
  v_shipping_cost := COALESCE(NULLIF(p_quote ->> 'shipping_cost', '')::numeric, 0);
  IF v_markup < 0 OR v_markup > 50
     OR v_discount_percent < 0 OR v_discount_percent > 100
     OR v_discount_amount < 0 OR v_shipping_cost < 0 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Markup, desconto ou frete do orçamento são inválidos.';
  END IF;

  -- Primeira passagem: valida todo o documento e recalcula os totais sem
  -- confiar nos campos derivados enviados pelo navegador.
  FOR v_item, v_ordinal IN
    SELECT value, ordinality
    FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) WITH ORDINALITY
  LOOP
    IF jsonb_typeof(v_item) IS DISTINCT FROM 'object'
       OR NULLIF(trim(v_item ->> 'product_name'), '') IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('Item %s do orçamento é inválido.', v_ordinal);
    END IF;

    v_quantity := NULLIF(v_item ->> 'quantity', '')::integer;
    v_unit_price := NULLIF(v_item ->> 'unit_price', '')::numeric;
    v_unit_cost := COALESCE(NULLIF(v_item ->> 'unit_cost', '')::numeric, 0);
    IF v_quantity IS NULL OR v_quantity <= 0 OR v_unit_price IS NULL OR v_unit_price < 0 OR v_unit_cost < 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('Quantidade ou valor do item %s é inválido.', v_ordinal);
    END IF;
    IF jsonb_typeof(COALESCE(v_item -> 'personalizations', '[]'::jsonb)) IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('Personalizações do item %s são inválidas.', v_ordinal);
    END IF;

    v_real_subtotal := v_real_subtotal + (v_quantity * v_unit_price);
    v_total_cost := v_total_cost + (v_quantity * v_unit_cost);
    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      IF jsonb_typeof(v_personalization) IS DISTINCT FROM 'object' THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('Personalização do item %s é inválida.', v_ordinal);
      END IF;
      v_setup_cost := COALESCE(NULLIF(v_personalization ->> 'setup_cost', '')::numeric, 0);
      v_personalization_unit_cost := COALESCE(NULLIF(v_personalization ->> 'unit_cost', '')::numeric, 0);
      v_personalization_total := COALESCE(NULLIF(v_personalization ->> 'total_cost', '')::numeric, 0);
      v_personalized_quantity := COALESCE(NULLIF(v_personalization ->> 'personalized_quantity', '')::integer, v_quantity);
      IF v_setup_cost < 0 OR v_personalization_unit_cost < 0 OR v_personalization_total < 0
         OR v_personalized_quantity <= 0
         OR COALESCE(NULLIF(v_personalization ->> 'colors_count', '')::integer, 1) <= 0
         OR COALESCE(NULLIF(v_personalization ->> 'positions_count', '')::integer, 1) <= 0 THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = format('Custos ou quantidades da personalização do item %s são inválidos.', v_ordinal);
      END IF;
      v_real_subtotal := v_real_subtotal + v_personalization_total;
      v_total_cost := v_total_cost + v_setup_cost + (v_personalization_unit_cost * v_personalized_quantity);
    END LOOP;
  END LOOP;

  v_real_subtotal := round(v_real_subtotal, 2);
  v_total_cost := round(v_total_cost, 2);
  v_subtotal := round(v_real_subtotal * (1 + v_markup / 100), 2);
  v_discount_amount := round(v_discount_amount, 2);
  IF v_discount_amount > v_subtotal THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'O desconto não pode superar o subtotal do orçamento.';
  END IF;
  IF v_discount_percent > 0
     AND abs(v_discount_amount - round(v_subtotal * v_discount_percent / 100, 2)) > 0.01 THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Percentual e valor do desconto não correspondem.';
  END IF;
  v_total := round(
    v_subtotal - v_discount_amount
    + CASE WHEN COALESCE(p_quote ->> 'shipping_type', '') IN ('fob', 'fob_pre') THEN v_shipping_cost ELSE 0 END,
    2
  );

  IF (p_quote ? 'subtotal' AND abs((p_quote ->> 'subtotal')::numeric - v_subtotal) > 0.01)
     OR (p_quote ? 'total' AND abs((p_quote ->> 'total')::numeric - v_total) > 0.01)
     OR (p_quote ? 'total_cost' AND abs((p_quote ->> 'total_cost')::numeric - v_total_cost) > 0.01) THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Os totais enviados não correspondem aos itens do orçamento.';
  END IF;

  IF p_quote_id IS NULL THEN
    IF p_expected_row_version IS NOT NULL THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Uma criação não pode informar versão anterior.';
    END IF;
    v_status := COALESCE(NULLIF(trim(p_quote ->> 'status'), ''), 'draft');
    IF v_status <> 'draft' THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Um novo orçamento deve iniciar como rascunho.';
    END IF;
    -- organization_id precisa ser uuid bem formado antes do cast,
    -- senão o banco responde 22P02 genérico em vez do padrão legível da função.
    IF NULLIF(trim(p_quote ->> 'organization_id'), '') IS NOT NULL
       AND p_quote ->> 'organization_id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$' THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A organização informada é inválida.';
    END IF;
    -- client_id é texto livre (ID externo do CRM) — não se exige uuid aqui.
    v_organization_id := NULLIF(p_quote ->> 'organization_id', '')::uuid;
    IF v_organization_id IS NOT NULL
       AND NOT COALESCE(public.can_view_all_sales(), false)
       AND NOT EXISTS (
         SELECT 1
         FROM public.get_user_org_ids(v_actor_id) AS allowed(organization_id)
         WHERE allowed.organization_id = v_organization_id
       ) THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'A organização informada não pertence ao usuário.';
    END IF;

    INSERT INTO public.quotes (
      client_id, client_name, client_email, client_phone, client_company,
      seller_id, organization_id, status, subtotal, discount_percent,
      discount_amount, total, total_cost, negotiation_markup_percent,
      payment_terms, delivery_time, shipping_type, shipping_cost, notes,
      internal_notes, valid_until
    ) VALUES (
      NULLIF(p_quote ->> 'client_id', ''), NULLIF(p_quote ->> 'client_name', ''),
      NULLIF(p_quote ->> 'client_email', ''), NULLIF(p_quote ->> 'client_phone', ''),
      NULLIF(p_quote ->> 'client_company', ''), v_actor_id, v_organization_id,
      'draft', v_subtotal, v_discount_percent, v_discount_amount, v_total,
      v_total_cost, v_markup, NULLIF(p_quote ->> 'payment_terms', ''),
      NULLIF(p_quote ->> 'delivery_time', ''), NULLIF(p_quote ->> 'shipping_type', ''),
      v_shipping_cost, NULLIF(p_quote ->> 'notes', ''),
      NULLIF(p_quote ->> 'internal_notes', ''), NULLIF(p_quote ->> 'valid_until', '')::timestamptz
    ) RETURNING * INTO v_quote;
    v_action := 'created';
  ELSE
    IF p_expected_row_version IS NULL OR p_expected_row_version <= 0 THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A versão atual é obrigatória para editar o orçamento.';
    END IF;
    SELECT * INTO v_quote FROM public.quotes WHERE id = p_quote_id FOR UPDATE;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'Orçamento não encontrado ou fora do seu escopo.';
    END IF;
    IF v_quote.row_version IS DISTINCT FROM p_expected_row_version THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'O orçamento mudou; atualize a página antes de salvar.';
    END IF;
    IF NOT v_quote.is_latest_version OR v_quote.status NOT IN ('draft', 'revision', 'rejected', 'rejected_singular') THEN
      RAISE EXCEPTION USING ERRCODE = '23514', MESSAGE = 'O orçamento enviado para decisão deve ser revisado em uma nova versão.';
    END IF;
    IF p_quote ? 'status'
       AND NULLIF(trim(p_quote ->> 'status'), '') IS DISTINCT FROM v_quote.status THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Use o fluxo formal para alterar o status do orçamento.';
    END IF;

    -- Todo `id` declarado precisa ser único e pertencer a este orçamento.
    -- Um id desconhecido indica composição obsoleta no editor (outra aba ou
    -- usuário já alterou os itens) e recusa a gravação em vez de recriar
    -- linhas com identidade nova, o que perderia vínculos de arte e pedido.
    IF EXISTS (
      SELECT 1
      FROM jsonb_array_elements(p_items) AS entry
      WHERE NULLIF(trim(entry.value ->> 'id'), '') IS NOT NULL
        AND entry.value ->> 'id' !~* '^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$'
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Identificador de item inválido no orçamento.';
    END IF;
    SELECT COALESCE(array_agg((entry.value ->> 'id')::uuid), '{}'::uuid[])
      INTO v_declared_item_ids
      FROM jsonb_array_elements(p_items) AS entry
     WHERE NULLIF(trim(entry.value ->> 'id'), '') IS NOT NULL;

    IF (SELECT count(d.id) FROM unnest(v_declared_item_ids) AS d(id))
       <> (SELECT count(DISTINCT d.id) FROM unnest(v_declared_item_ids) AS d(id)) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Identificadores de itens duplicados no orçamento.';
    END IF;
    IF EXISTS (
      SELECT 1
      FROM unnest(v_declared_item_ids) AS d(id)
      WHERE NOT EXISTS (
        SELECT 1 FROM public.quote_items qi
        WHERE qi.id = d.id AND qi.quote_id = v_quote.id
      )
    ) THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Os itens do orçamento mudaram; atualize a página antes de salvar.';
    END IF;

    UPDATE public.quotes SET
      client_id = NULLIF(p_quote ->> 'client_id', ''),
      client_name = NULLIF(p_quote ->> 'client_name', ''),
      client_email = NULLIF(p_quote ->> 'client_email', ''),
      client_phone = NULLIF(p_quote ->> 'client_phone', ''),
      client_company = NULLIF(p_quote ->> 'client_company', ''),
      subtotal = v_subtotal,
      discount_percent = v_discount_percent,
      discount_amount = v_discount_amount,
      total = v_total,
      total_cost = v_total_cost,
      negotiation_markup_percent = v_markup,
      payment_terms = NULLIF(p_quote ->> 'payment_terms', ''),
      delivery_time = NULLIF(p_quote ->> 'delivery_time', ''),
      shipping_type = NULLIF(p_quote ->> 'shipping_type', ''),
      shipping_cost = v_shipping_cost,
      notes = NULLIF(p_quote ->> 'notes', ''),
      internal_notes = NULLIF(p_quote ->> 'internal_notes', ''),
      valid_until = NULLIF(p_quote ->> 'valid_until', '')::timestamptz,
      updated_at = clock_timestamp()
    WHERE id = p_quote_id AND row_version = p_expected_row_version
    RETURNING * INTO v_quote;
    IF NOT FOUND THEN
      RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'O orçamento mudou; atualize a página antes de salvar.';
    END IF;
    v_action := 'updated';
  END IF;

  -- Segunda passagem: todas as escritas estão na mesma transação do
  -- cabeçalho. Qualquer erro reverte também deleções e histórico.
  FOR v_item, v_ordinal IN
    SELECT value, ordinality
    FROM jsonb_array_elements(COALESCE(p_items, '[]'::jsonb)) WITH ORDINALITY
  LOOP
    v_quantity := (v_item ->> 'quantity')::integer;
    v_unit_price := (v_item ->> 'unit_price')::numeric;
    v_unit_cost := COALESCE(NULLIF(v_item ->> 'unit_cost', '')::numeric, 0);
    -- Ids declarados só valem na edição; na criação todo item nasce com uuid novo.
    v_item_id := CASE WHEN p_quote_id IS NULL THEN NULL
                      ELSE NULLIF(v_item ->> 'id', '')::uuid END;

    IF v_item_id IS NULL THEN
      INSERT INTO public.quote_items (
        quote_id, product_id, product_name, product_sku, product_image_url,
        quantity, unit_price, unit_cost, subtotal, color_name, color_hex,
        notes, sort_order, kit_group_id, kit_name, size_code, gender,
        source_variant_id, source_variant_sku, price_confirmed_at
      ) VALUES (
        v_quote.id, NULLIF(v_item ->> 'product_id', ''), trim(v_item ->> 'product_name'),
        NULLIF(v_item ->> 'product_sku', ''), NULLIF(v_item ->> 'product_image_url', ''),
        v_quantity, v_unit_price, v_unit_cost,
        round(v_quantity * v_unit_price + COALESCE((
          SELECT sum(COALESCE(NULLIF(value ->> 'total_cost', '')::numeric, 0))
          FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
        ), 0), 2),
        NULLIF(v_item ->> 'color_name', ''), NULLIF(v_item ->> 'color_hex', ''),
        NULLIF(v_item ->> 'notes', ''), (v_ordinal - 1)::integer,
        NULLIF(v_item ->> 'kit_group_id', ''), NULLIF(v_item ->> 'kit_name', ''),
        NULLIF(v_item ->> 'size_code', ''), NULLIF(v_item ->> 'gender', ''),
        NULLIF(v_item ->> 'source_variant_id', ''), NULLIF(v_item ->> 'source_variant_sku', ''),
        NULLIF(v_item ->> 'price_confirmed_at', '')::timestamptz
      ) RETURNING id INTO v_item_id;
    ELSE
      UPDATE public.quote_items SET
        product_id = NULLIF(v_item ->> 'product_id', ''),
        product_name = trim(v_item ->> 'product_name'),
        product_sku = NULLIF(v_item ->> 'product_sku', ''),
        product_image_url = NULLIF(v_item ->> 'product_image_url', ''),
        quantity = v_quantity,
        unit_price = v_unit_price,
        unit_cost = v_unit_cost,
        subtotal = round(v_quantity * v_unit_price + COALESCE((
          SELECT sum(COALESCE(NULLIF(value ->> 'total_cost', '')::numeric, 0))
          FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
        ), 0), 2),
        color_name = NULLIF(v_item ->> 'color_name', ''),
        color_hex = NULLIF(v_item ->> 'color_hex', ''),
        notes = NULLIF(v_item ->> 'notes', ''),
        sort_order = (v_ordinal - 1)::integer,
        kit_group_id = NULLIF(v_item ->> 'kit_group_id', ''),
        kit_name = NULLIF(v_item ->> 'kit_name', ''),
        size_code = NULLIF(v_item ->> 'size_code', ''),
        gender = NULLIF(v_item ->> 'gender', ''),
        source_variant_id = NULLIF(v_item ->> 'source_variant_id', ''),
        source_variant_sku = NULLIF(v_item ->> 'source_variant_sku', ''),
        price_confirmed_at = NULLIF(v_item ->> 'price_confirmed_at', '')::timestamptz,
        -- Qualquer edição invalida a consulta ao catálogo da recompra, como o
        -- antigo delete-recreate fazia ao nascer linhas novas sem esses campos.
        catalog_checked_at = NULL,
        catalog_available_stock = NULL,
        catalog_minimum_quantity = NULL,
        catalog_valid_until = NULL,
        catalog_stock_is_reserved = false,
        historical_unit_price = NULL,
        price_changed = false
      WHERE id = v_item_id AND quote_id = v_quote.id
      RETURNING id INTO v_item_id;
      IF NOT FOUND THEN
        RAISE EXCEPTION USING ERRCODE = '40001', MESSAGE = 'Os itens do orçamento mudaram; atualize a página antes de salvar.';
      END IF;
    END IF;

    v_seen_item_ids := v_seen_item_ids || v_item_id;

    -- As personalizações são linhas-filha reescritas a cada salvamento;
    -- a identidade preservada é a do item-pai.
    SELECT count(*) INTO v_pending_deletes
    FROM public.quote_item_personalizations
    WHERE quote_item_id = v_item_id;
    DELETE FROM public.quote_item_personalizations WHERE quote_item_id = v_item_id;
    GET DIAGNOSTICS v_deleted_rows = ROW_COUNT;
    IF v_deleted_rows < v_pending_deletes THEN
      RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Sem permissão para remover personalizações deste orçamento.';
    END IF;
    FOR v_personalization IN
      SELECT value FROM jsonb_array_elements(COALESCE(v_item -> 'personalizations', '[]'::jsonb))
    LOOP
      INSERT INTO public.quote_item_personalizations (
        quote_item_id, technique_id, technique_name, colors_count,
        positions_count, area_cm2, width_cm, height_cm, personalized_quantity,
        setup_cost, unit_cost, total_cost, notes
      ) VALUES (
        v_item_id, NULLIF(v_personalization ->> 'technique_id', ''),
        NULLIF(v_personalization ->> 'technique_name', ''),
        COALESCE(NULLIF(v_personalization ->> 'colors_count', '')::integer, 1),
        COALESCE(NULLIF(v_personalization ->> 'positions_count', '')::integer, 1),
        NULLIF(v_personalization ->> 'area_cm2', '')::numeric,
        NULLIF(v_personalization ->> 'width_cm', '')::numeric,
        NULLIF(v_personalization ->> 'height_cm', '')::numeric,
        NULLIF(v_personalization ->> 'personalized_quantity', '')::integer,
        COALESCE(NULLIF(v_personalization ->> 'setup_cost', '')::numeric, 0),
        COALESCE(NULLIF(v_personalization ->> 'unit_cost', '')::numeric, 0),
        COALESCE(NULLIF(v_personalization ->> 'total_cost', '')::numeric, 0),
        NULLIF(v_personalization ->> 'notes', '')
      );
    END LOOP;
  END LOOP;

  -- Itens ausentes do payload deixam de existir; os preservados mantêm id.
  -- DELETE filtrado pelo RLS não falha: confere a contagem para não
  -- retornar sucesso com linhas remanescentes (ex.: supervisor sem escopo
  -- de exclusão no orçamento de outro vendedor).
  SELECT count(*) INTO v_pending_deletes
  FROM public.quote_items
  WHERE quote_id = v_quote.id AND NOT (id = ANY(v_seen_item_ids));
  DELETE FROM public.quote_items
  WHERE quote_id = v_quote.id AND NOT (id = ANY(v_seen_item_ids));
  GET DIAGNOSTICS v_deleted_rows = ROW_COUNT;
  IF v_deleted_rows < v_pending_deletes THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Sem permissão para remover itens deste orçamento.';
  END IF;

  IF jsonb_array_length(COALESCE(p_history, '[]'::jsonb)) = 0 THEN
    PERFORM public.append_quote_history_note(
      v_quote.id, v_action,
      CASE WHEN v_action = 'created' THEN 'Orçamento criado' ELSE 'Orçamento atualizado' END
    );
  ELSE
    FOR v_history_entry IN SELECT value FROM jsonb_array_elements(p_history)
    LOOP
      IF jsonb_typeof(v_history_entry) IS DISTINCT FROM 'string'
         OR NULLIF(trim(v_history_entry #>> '{}'), '') IS NULL THEN
        RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Entrada de histórico inválida.';
      END IF;
      v_description := left(trim(v_history_entry #>> '{}'), 2000);
      PERFORM public.append_quote_history_note(
        v_quote.id, v_action, v_description, NULL, NULL, NULL,
        jsonb_build_object('source', 'save_quote_atomic')
      );
    END LOOP;
  END IF;

  RETURN to_jsonb(v_quote);
END;
$function$

CREATE OR REPLACE FUNCTION public.save_quote_atomic_idempotent(p_quote jsonb, p_items jsonb, p_idempotency_key uuid, p_history jsonb DEFAULT '[]'::jsonb)
 RETURNS jsonb
 LANGUAGE plpgsql
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_actor_id uuid := auth.uid();
  v_payload_hash text;
  v_legacy_hash text;
  v_existing public.quote_save_idempotency%ROWTYPE;
  v_result jsonb;
BEGIN
  IF v_actor_id IS NULL OR p_idempotency_key IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário autenticado e chave de idempotência são obrigatórios.';
  END IF;
  IF jsonb_typeof(p_quote) IS DISTINCT FROM 'object'
     OR jsonb_typeof(COALESCE(p_items, '[]'::jsonb)) IS DISTINCT FROM 'array'
     OR jsonb_typeof(COALESCE(p_history, '[]'::jsonb)) IS DISTINCT FROM 'array' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Cabeçalho, itens ou histórico do orçamento são inválidos.';
  END IF;

  v_payload_hash := encode(
    extensions.digest(
      p_quote::text || E'\x1f' || COALESCE(p_items, '[]'::jsonb)::text
        || E'\x1f' || COALESCE(p_history, '[]'::jsonb)::text,
      'sha256'
    ),
    'hex'
  );
  v_legacy_hash := md5(p_quote::text || ':' || COALESCE(p_items, '[]'::jsonb)::text);

  PERFORM pg_advisory_xact_lock(
    hashtextextended('quote-save:' || v_actor_id::text || ':' || p_idempotency_key::text, 0)
  );

  SELECT * INTO v_existing
    FROM public.quote_save_idempotency
   WHERE actor_id = v_actor_id
     AND idempotency_key = p_idempotency_key;
  IF FOUND THEN
    IF (length(v_existing.payload_hash) = 32 AND v_existing.payload_hash IS DISTINCT FROM v_legacy_hash)
       OR (length(v_existing.payload_hash) = 64 AND v_existing.payload_hash IS DISTINCT FROM v_payload_hash) THEN
      RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'A chave de idempotência já foi usada com conteúdo diferente.';
    END IF;
    SELECT to_jsonb(q) INTO v_result
    FROM public.quotes q
    WHERE q.id = v_existing.quote_id;
    IF v_result IS NULL THEN
      RAISE EXCEPTION USING ERRCODE = 'P0002', MESSAGE = 'O orçamento associado à chave de idempotência não está disponível.';
    END IF;
    RETURN v_result;
  END IF;

  v_result := public.save_quote_atomic(p_quote, p_items, NULL, NULL, p_history);
  INSERT INTO public.quote_save_idempotency (actor_id, idempotency_key, payload_hash, quote_id)
  VALUES (v_actor_id, p_idempotency_key, v_payload_hash, (v_result ->> 'id')::uuid);

  RETURN v_result;
END;
$function$

CREATE OR REPLACE FUNCTION public.seed_discount_test_users()
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _seller_id uuid;
  _admin_id uuid;
BEGIN
  -- Find existing test users by email in profiles
  SELECT user_id INTO _seller_id FROM public.profiles WHERE email = 'seller-test@discount-approval.test' LIMIT 1;
  SELECT user_id INTO _admin_id FROM public.profiles WHERE email = 'admin-test@discount-approval.test' LIMIT 1;

  -- If users don't exist, return error (auth.users insertion requires Supabase Admin API, not SQL)
  IF _seller_id IS NULL OR _admin_id IS NULL THEN
    RETURN jsonb_build_object(
      'ok', false,
      'error', 'Test users not found. Create them via Supabase Admin API first.',
      'seller_exists', _seller_id IS NOT NULL,
      'admin_exists', _admin_id IS NOT NULL
    );
  END IF;

  -- Ensure roles
  INSERT INTO public.user_roles (user_id, role)
  VALUES (_seller_id, 'vendedor')
  ON CONFLICT (user_id, role) DO NOTHING;

  INSERT INTO public.user_roles (user_id, role)
  VALUES (_admin_id, 'admin')
  ON CONFLICT (user_id, role) DO NOTHING;

  -- Sync role on profiles
  UPDATE public.profiles SET role = 'vendedor' WHERE user_id = _seller_id;
  UPDATE public.profiles SET role = 'admin' WHERE user_id = _admin_id;

  RETURN jsonb_build_object(
    'ok', true,
    'seller_id', _seller_id,
    'admin_id', _admin_id
  );
END;
$function$

CREATE OR REPLACE FUNCTION public.set_connection_failure_window_minutes(minutes integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  IF minutes NOT IN (0, 15, 30, 60, 120, 240) THEN
    RAISE EXCEPTION 'invalid window: must be one of 0, 15, 30, 60, 120, 240 minutes';
  END IF;

  INSERT INTO public.system_settings (key, value, updated_by, updated_at)
  VALUES ('connection_failure_window_minutes', to_jsonb(minutes), auth.uid(), now())
  ON CONFLICT (key) DO UPDATE
    SET value = EXCLUDED.value,
        updated_by = EXCLUDED.updated_by,
        updated_at = EXCLUDED.updated_at;

  INSERT INTO public.admin_audit_log (user_id, action, resource_type, resource_id, details)
  VALUES (
    auth.uid(),
    'connection_failure_window_changed',
    'system_setting',
    'connection_failure_window_minutes',
    jsonb_build_object('minutes', minutes)
  );

  RETURN minutes;
END;
$function$

CREATE OR REPLACE FUNCTION public.set_connections_auto_test_interval(minutes integer)
 RETURNS integer
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  schedule text;
  job_id bigint;
BEGIN
  -- Admin only
  IF NOT public.has_role(auth.uid(), 'admin'::public.app_role) THEN
    RAISE EXCEPTION 'forbidden: admin role required';
  END IF;

  IF minutes NOT IN (5, 10, 15, 30, 60, 120, 240) THEN
    RAISE EXCEPTION 'invalid interval: must be one of 5, 10, 15, 30, 60, 120, 240 minutes';
  END IF;

  IF minutes < 60 THEN
    schedule := '*/' || minutes::text || ' * * * *';
  ELSIF minutes = 60 THEN
    schedule := '0 * * * *';
  ELSIF minutes = 120 THEN
    schedule := '0 */2 * * *';
  ELSIF minutes = 240 THEN
    schedule := '0 */4 * * *';
  END IF;

  SELECT jobid INTO job_id FROM cron.job WHERE jobname = 'connections-auto-test' LIMIT 1;
  IF job_id IS NULL THEN
    RAISE EXCEPTION 'cron job connections-auto-test not found';
  END IF;

  PERFORM cron.alter_job(job_id := job_id, schedule := schedule);

  -- Audit
  INSERT INTO public.admin_audit_log (user_id, action, resource_type, resource_id, details)
  VALUES (
    auth.uid(),
    'connections_auto_test_interval_changed',
    'cron_job',
    job_id::text,
    jsonb_build_object('minutes', minutes, 'schedule', schedule)
  );

  RETURN minutes;
END;
$function$

