CREATE OR REPLACE FUNCTION public.transition_sicoob_order_status(p_order_id uuid, p_expected_status text, p_new_status text, p_comment text DEFAULT NULL::text)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
DECLARE
  v_order_id uuid;
  v_new_status text := trim(COALESCE(p_new_status, ''));
BEGIN
  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION USING ERRCODE = '42501', MESSAGE = 'Usuário não autenticado.';
  END IF;

  IF NULLIF(trim(COALESCE(p_expected_status, '')), '') IS NULL OR v_new_status = '' THEN
    RAISE EXCEPTION USING ERRCODE = '22023', MESSAGE = 'Status atual e novo status são obrigatórios.';
  END IF;

  IF v_new_status IN ('waiting_approval', 'escalated_to_board', 'confirmed', 'rejected') THEN
    RAISE EXCEPTION USING
      ERRCODE = '42501',
      MESSAGE = 'Use a RPC específica para preparar, solicitar, decidir ou escalar uma aprovação.';
  END IF;

  IF v_new_status = 'cancelled' THEN
    PERFORM set_config('app.sicoob_approval_operation', 'reject', true);
    UPDATE public.sicoob_approval_requests
       SET status = 'rejected',
           approver_id = auth.uid(),
           rejection_reason = 'Pedido cancelado: ' || COALESCE(NULLIF(trim(p_comment), ''), 'sem observação adicional'),
           updated_at = now()
     WHERE order_id = p_order_id AND status = 'pending';
  END IF;

  PERFORM set_config('app.sicoob_order_status_comment', COALESCE(p_comment, ''), true);

  UPDATE public.sicoob_orders
     SET status = v_new_status,
         updated_at = now()
   WHERE id = p_order_id
     AND status = trim(p_expected_status)
  RETURNING id INTO v_order_id;

  IF v_order_id IS NULL THEN
    RAISE EXCEPTION USING
      ERRCODE = 'P0002',
      MESSAGE = 'O pedido mudou ou não está disponível; atualize a página e tente novamente.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_auto_revoke_mcp_on_role_loss()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _now TIMESTAMP WITH TIME ZONE := now();
  _rec RECORD;
BEGIN
  -- Só agimos quando uma role 'dev' é removida E o usuário não tem outra linha 'dev'
  IF OLD.role IS DISTINCT FROM 'dev'::app_role THEN
    RETURN OLD;
  END IF;

  IF EXISTS (
    SELECT 1 FROM public.user_roles
     WHERE user_id = OLD.user_id AND role = 'dev'::app_role
  ) THEN
    -- Ainda é dev por outra atribuição: nada a fazer
    RETURN OLD;
  END IF;

  FOR _rec IN
    SELECT id FROM public.mcp_api_keys
     WHERE created_by = OLD.user_id
       AND revoked_at IS NULL
       AND '*' = ANY(scopes)
     FOR UPDATE
  LOOP
    UPDATE public.mcp_api_keys
       SET revoked_at = _now, updated_at = _now
     WHERE id = _rec.id AND revoked_at IS NULL;

    INSERT INTO public.mcp_key_auto_revocations(key_id, created_by, revoked_at, source, reason)
    VALUES (_rec.id, OLD.user_id, _now, 'trigger', 'creator_lost_dev_role');

    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, metadata)
    VALUES (
      OLD.user_id,
      'mcp_full_issue',
      _rec.id::text,
      'auto_revoked',
      jsonb_build_object('reason','creator_lost_dev_role','source','trigger')
    );
  END LOOP;

  RETURN OLD;
END;
$function$

CREATE OR REPLACE FUNCTION public.trg_sync_external_connections()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _secret_name text;
  _op text := TG_OP;
BEGIN
  _secret_name := COALESCE(NEW.secret_name, OLD.secret_name);
  IF (TG_OP = 'DELETE' AND OLD.secret_name LIKE 'EXTERNAL_%')
     OR (TG_OP IN ('INSERT','UPDATE') AND NEW.secret_name LIKE 'EXTERNAL_%') THEN
    PERFORM public.sync_external_connections_from_credentials(
      _secret_name, _op, auth.uid()
    );
  END IF;
  RETURN COALESCE(NEW, OLD);
EXCEPTION WHEN OTHERS THEN
  RETURN COALESCE(NEW, OLD);
END;
$function$

