CREATE OR REPLACE FUNCTION public.validate_sicoob_order_budget()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_budget public.pa_budgets%ROWTYPE;
  v_old_consumes boolean := OLD.status IN (
    'confirmed', 'logistic', 'in_production', 'in_separation',
    'in_transit', 'delivered', 'completed'
  );
  v_new_consumes boolean := NEW.status IN (
    'confirmed', 'logistic', 'in_production', 'in_separation',
    'in_transit', 'delivered', 'completed'
  );
BEGIN
  IF v_old_consumes AND (
    NEW.pa_id IS DISTINCT FROM OLD.pa_id OR
    NEW.total_amount IS DISTINCT FROM OLD.total_amount OR
    NEW.created_at IS DISTINCT FROM OLD.created_at
  ) THEN
    RAISE EXCEPTION USING
      ERRCODE = '23514',
      MESSAGE = 'Pedido com verba consumida não permite alterar PA, valor ou período.';
  END IF;

  IF NOT v_old_consumes AND v_new_consumes THEN
    IF NEW.pa_id IS NULL OR COALESCE(NEW.total_amount, 0) <= 0 THEN
      RAISE EXCEPTION USING
        ERRCODE = '23514',
        MESSAGE = 'Pedido confirmado exige PA e valor total positivo.';
    END IF;

    SELECT *
      INTO v_budget
      FROM public.pa_budgets
     WHERE pa_id = NEW.pa_id
       AND ano = EXTRACT(YEAR FROM NEW.created_at)::integer
       AND mes = EXTRACT(MONTH FROM NEW.created_at)::integer
     FOR UPDATE;

    IF NOT FOUND THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'Orçamento não configurado para o PA no período do pedido.';
    END IF;

    IF v_budget.verba_consumida + NEW.total_amount > v_budget.verba_total THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'Saldo de orçamento insuficiente para confirmar o pedido.';
    END IF;

    UPDATE public.pa_budgets
       SET verba_consumida = verba_consumida + NEW.total_amount,
           updated_at = now()
     WHERE id = v_budget.id;

    NEW.audit_remaining_budget :=
      v_budget.verba_total - v_budget.verba_consumida - NEW.total_amount;
  ELSIF v_old_consumes AND NOT v_new_consumes THEN
    SELECT *
      INTO v_budget
      FROM public.pa_budgets
     WHERE pa_id = OLD.pa_id
       AND ano = EXTRACT(YEAR FROM OLD.created_at)::integer
       AND mes = EXTRACT(MONTH FROM OLD.created_at)::integer
     FOR UPDATE;

    IF NOT FOUND OR v_budget.verba_consumida < OLD.total_amount THEN
      RAISE EXCEPTION USING
        ERRCODE = 'P0001',
        MESSAGE = 'Inconsistência de orçamento impede o estorno automático.';
    END IF;

    UPDATE public.pa_budgets
       SET verba_consumida = verba_consumida - OLD.total_amount,
           updated_at = now()
     WHERE id = v_budget.id;

    NEW.audit_remaining_budget :=
      v_budget.verba_total - v_budget.verba_consumida + OLD.total_amount;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_sicoob_order_document()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'pg_catalog', 'public'
AS $function$
DECLARE
  v_document public.sicoob_document_registry%ROWTYPE;
  v_owner uuid;
  v_linked_record_id uuid;
BEGIN
  IF TG_TABLE_NAME='sicoob_order_invoices' THEN
    SELECT * INTO v_document FROM public.sicoob_document_registry
    WHERE final_path=NEW.file_path AND order_id=NEW.order_id AND uploaded_by=NEW.created_by
      AND status='clean' AND purpose=CASE WHEN NEW.file_type='pdf' THEN 'invoice_pdf' ELSE 'invoice_xml' END
    FOR UPDATE;
    IF NOT FOUND OR (v_document.linked_record_id IS NOT NULL AND v_document.linked_record_id IS DISTINCT FROM NEW.id) THEN
      RAISE EXCEPTION 'A nota fiscal não possui inspeção limpa, íntegra e disponível.' USING ERRCODE='23514';
    END IF;
    NEW.document_id:=v_document.id;
    UPDATE public.sicoob_document_registry SET linked_at=clock_timestamp(),linked_entity='invoice',linked_record_id=NEW.id
    WHERE id=v_document.id;
  ELSIF TG_TABLE_NAME='sicoob_order_shipments' AND NEW.delivery_photo_path IS NULL THEN
    NEW.delivery_document_id:=NULL;
    NEW.delivery_photo_uploaded_by:=NULL;
  ELSIF TG_TABLE_NAME='sicoob_order_shipments' THEN
    v_owner:=COALESCE(auth.uid(),NEW.delivery_photo_uploaded_by,NEW.created_by);
    SELECT shipment.id INTO v_linked_record_id
    FROM public.sicoob_order_shipments shipment WHERE shipment.order_id=NEW.order_id;
    v_linked_record_id:=COALESCE(v_linked_record_id,NEW.id);
    SELECT * INTO v_document FROM public.sicoob_document_registry
    WHERE final_path=NEW.delivery_photo_path AND order_id=NEW.order_id AND uploaded_by=v_owner
      AND status='clean' AND purpose='delivery_proof'
    FOR UPDATE;
    IF NOT FOUND OR (v_document.linked_record_id IS NOT NULL AND v_document.linked_record_id IS DISTINCT FROM v_linked_record_id) THEN
      RAISE EXCEPTION 'O comprovante não possui inspeção limpa, íntegra e disponível.' USING ERRCODE='23514';
    END IF;
    NEW.delivery_document_id:=v_document.id;
    NEW.delivery_photo_uploaded_by:=v_owner;
    UPDATE public.sicoob_document_registry SET linked_at=clock_timestamp(),linked_entity='shipment',linked_record_id=v_linked_record_id
    WHERE id=v_document.id;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.validate_status_fields()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF TG_TABLE_NAME = 'quotes' AND NEW.status NOT IN (
    'draft', 'pending', 'sent', 'approved', 'rejected', 'expired',
    'revision', 'pending_approval', 'pending_singular_approval',
    'approved_singular', 'rejected_singular', 'converted', 'viewed'
  ) THEN
    RAISE EXCEPTION 'Invalid quote status: %', NEW.status;
  END IF;

  IF TG_TABLE_NAME = 'orders' THEN
    IF NEW.status NOT IN (
      'rascunho', 'enviado_gestor', 'aprovado_gestor', 'enviado_vendedor',
      'em_producao', 'em_separacao', 'em_transporte', 'entregue',
      'concluido', 'cancelado'
    ) THEN
      RAISE EXCEPTION 'Invalid order status: %', NEW.status;
    END IF;
    IF NEW.fulfillment_status NOT IN ('unfulfilled', 'partially_fulfilled', 'fulfilled') THEN
      RAISE EXCEPTION 'Invalid fulfillment status: %', NEW.fulfillment_status;
    END IF;
  END IF;

  IF TG_TABLE_NAME = 'custom_kits'
     AND NEW.status NOT IN ('draft', 'ready', 'shared', 'archived') THEN
    RAISE EXCEPTION 'Invalid kit status: %', NEW.status;
  END IF;

  IF TG_TABLE_NAME = 'kit_share_tokens'
     AND NEW.status NOT IN ('active', 'expired', 'responded', 'revoked') THEN
    RAISE EXCEPTION 'Invalid kit status: %', NEW.status;
  END IF;

  IF TG_TABLE_NAME = 'quote_approval_tokens'
     AND NEW.status NOT IN ('active', 'expired', 'responded') THEN
    RAISE EXCEPTION 'Invalid approval token status: %', NEW.status;
  END IF;

  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.verify_step_up_otp(_challenge_id uuid, _otp text)
 RETURNS TABLE(token text, expires_at timestamp with time zone)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  _uid UUID := auth.uid();
  _row RECORD;
  _otp_h TEXT;
  _token TEXT;
  _token_h TEXT;
  _tid UUID;
  _exp TIMESTAMPTZ;
BEGIN
  IF _uid IS NULL THEN RAISE EXCEPTION 'unauthorized'; END IF;

  SELECT challenge.* INTO _row FROM public.step_up_challenges AS challenge
  WHERE challenge.id = _challenge_id AND challenge.user_id = _uid
    AND challenge.consumed = false AND challenge.expires_at > now()
  FOR UPDATE;

  IF NOT FOUND THEN
    INSERT INTO public.step_up_audit_log(user_id, event_type, challenge_id, metadata)
    VALUES (_uid, 'failed', _challenge_id, '{"reason":"challenge_not_found_or_expired"}'::jsonb);
    RAISE EXCEPTION 'invalid_or_expired_challenge';
  END IF;

  IF NOT _row.password_verified THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, '{"reason":"password_not_verified"}'::jsonb);
    RAISE EXCEPTION 'password_not_verified_first';
  END IF;

  IF _row.attempts >= _row.max_attempts THEN
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, '{"reason":"max_attempts"}'::jsonb);
    RAISE EXCEPTION 'max_attempts_exceeded';
  END IF;

  _otp_h := encode(extensions.digest(_otp || _uid::text, 'sha256'), 'hex');

  IF _otp_h <> _row.otp_hash THEN
    UPDATE public.step_up_challenges SET attempts = attempts + 1 WHERE id = _challenge_id;
    INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, metadata)
    VALUES (_uid, _row.action, _row.target_ref, 'failed', _challenge_id, jsonb_build_object('reason','wrong_otp','attempt', _row.attempts + 1));
    RAISE EXCEPTION 'invalid_otp';
  END IF;

  -- OK: gera token de uso único
  _token := encode(extensions.gen_random_bytes(32), 'hex');
  _token_h := encode(extensions.digest(_token, 'sha256'), 'hex');
  _exp := now() + interval '5 minutes';

  INSERT INTO public.step_up_tokens(user_id, action, target_ref, token_hash, challenge_id, expires_at)
  VALUES (_uid, _row.action, _row.target_ref, _token_h, _challenge_id, _exp)
  RETURNING id INTO _tid;

  UPDATE public.step_up_challenges
    SET otp_verified = true, consumed = true
    WHERE id = _challenge_id;

  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, token_id)
  VALUES (_uid, _row.action, _row.target_ref, 'otp_verified', _challenge_id, _tid);
  INSERT INTO public.step_up_audit_log(user_id, action, target_ref, event_type, challenge_id, token_id)
  VALUES (_uid, _row.action, _row.target_ref, 'token_issued', _challenge_id, _tid);

  RETURN QUERY SELECT _token, _exp;
END;
$function$
